["bm_msk_santa_happy_desc"] = "SANTA CLAUS, SAİNT NİCHOLAS, FATHER CHRİSTMAS VE KRİS KRİNGLE (?) ADLARIYLA DA BİLİNEN SANTA, DESTANSI BOYUTLARDA BİR ADAMDIR. EFSANEVİ, MİTOLOJİK, TARİHÎ VE FOLKLORİK GİBİ SÖZCÜKLER BU ADAM AZMANINI EN İYİ ANLATIR.$NL;$NL;BU, HAPPY SANTA MASKESİ. KOCAMAN GÜLÜMSEMESİ, KIRMIZI YANAKLARI VE NEŞESİYLE BUNU TAKTIĞINDA EN HUYSUZ BULLDOZER’I BİLE KEYİFLE GÜLÜMSETİRSİN.",
["bm_msk_santa_mad_desc"] = "SANTA CLAUS, SAİNT NİCHOLAS, FATHER CHRİSTMAS VE KRİS KRİNGLE (?) ADLARIYLA DA BİLİNEN SANTA, DESTANSI BOYUTLARDA BİR ADAMDIR. EFSANEVİ, MİTOLOJİK, TARİHÎ VE FOLKLORİK GİBİ SÖZCÜKLER BU ADAM AZMANINI EN İYİ ANLATIR.$NL;$NL;BU, FURIOUS SANTA MASKESİ. ÖFKELİ İNTERNET KULLANICILARI VE İSTEDİKLERİ HEDİYEYİ ALAMAYAN YARAMAZ ÇOCUKLAR TAKAR.",
["bm_msk_santa_surprise_desc"] = "SANTA CLAUS, SAİNT NİCHOLAS, FATHER CHRİSTMAS VE KRİS KRİNGLE (?) ADLARIYLA DA BİLİNEN SANTA, DESTANSI BOYUTLARDA BİR ADAMDIR. EFSANEVİ, MİTOLOJİK, TARİHÎ VE FOLKLORİK GİBİ SÖZCÜKLER BU ADAM AZMANINI EN İYİ ANLATIR.$NL;$NL;BU, SURPRISED SANTA MASKESİ. NEDEN ŞAŞIRMIŞ, KİM BİLİR? BİRİ KIZAĞINI MI ÇALDI? RENGEYİKLERİNİ Mİ ÇALDI? YOKSA AZ ÖNCE BİRİNİN BANKA SOYDUĞUNU MU GÖRDÜ?",
