["bm_msk_scarecrow_desc"] = "KARGALARI, SERÇELERİ VE KOLLUK KUVVETLERİNİ DEHŞET TARLANA GİRMEKTEN CAYDIR.$NL;$NL;EFSANEYE GÖRE UZAK DİYARLARDA HER ŞEYİ BİLEN AMA YÜRÜYEMEYEN BİR TANRI YAŞARMIŞ. AÇGÖZLÜ İNSANLAR TANRIYI BULUP BİLGELİĞİNİ KAZANABİLECEKLERİNİ DÜŞÜNEREK BAŞINI KESMİŞ.$NL;$NL;AMA BUNUN YERİNE DEHŞETLE LANETLENMİŞLER.",
["bm_msk_scm_01_desc"] = "YERALTI DÜNYASININ SAVAŞÇI MUHAFIZI, BAST’IN EŞİ ANUBİS; ZAMANIN ŞAFAĞINDA DOĞMUŞ KADİM BİR GÜÇ. GÖZCÜNÜN AHDİ’NİN MUHAFIZLARI, LAYIK OLMAYAN HİÇBİR RUHUN GEÇEMEYECEĞİ KAPILARI KAPALI TUTARKEN ONUN BİLGELİĞİ VE VAHŞETİYLE GÜÇLENİR. BU KADİM SAVAŞÇIYI YENECEK KADAR GÜÇLÜ ÖLÜMLÜLER ONUN MASKESİNİ TAKABİLİR, BELKİ DE BARINDIRDIĞI GÜCE BİR ANLIĞINA TANIK OLABİLİR.",
["bm_msk_scm_02_desc"] = "ANUBİS’İN EŞİ BAST, ESKİ MISIRLILARIN KEDİ SAVAŞÇI OLARAK TAPTIĞI AMA ASLINDA DÜNYADA ÇOK DAHA ESKİ BİR GÜÇTÜR. GÜCÜYLE KUTSANAN GUARDİANS OF THE ARK OF THE WATCHER, BİTMEYEN GÖREVLERİNİ YERİNE GETİRİRKEN SAYGI GÖSTERMEK İÇİN ONUN MASKESİNİ TAKAR. YÜZÜNÜ TAŞIYAN ÖLÜMLÜLERİN OLAĞANÜSTÜ ŞANSLA KUTSANDIĞI VE KAPIYA GELDİĞİNDE ÖLÜMÜ KANDIRABİLDİĞİ SÖYLENİR.",
["bm_msk_sdm_01_desc"] = "KLAUS PEK ZEKİ BİR KÖPEK SAYILMAZ AMA AKIL EKSİĞİNİ KOCA YÜREĞİYLE KAPATIR. KEMİKLERİNİ SÜRÜNÜN GERİ KALANIYLA PAYLAŞMAYA HER ZAMAN HAZIRDIR.",
["bm_msk_sdm_02_desc"] = "BURADA ESKİ USUL SOKAK ZEKÂSI VE SERT BİR DAYANIKLILIK VAR. LAFI UZATMADAN İŞİ BİTİREN BİR KİŞİLİK. GANİMETİNE BUNDAN DAHA SADIK BİR BEKÇİ BULAMAZSIN.",
["bm_msk_sdm_03_desc"] = "SEVİMLİ, SARKIK KULAKLI FROU FROU HİÇ DE ÜRKEK BİR AFGAN TAZISI DEĞİL. ZEKİ VE KIVRAK ZEKÂLI BU DOST, KURNAZLIĞIN YANI SIRA AKIL DA İSTEYEN SOYGUNLARDA YÜZÜNÜ ÖRTMEK İÇİN İDEAL.",
["bm_msk_sdm_04_desc"] = "KÜÇÜK CÜSSESİNE, DARMADAĞINIK TÜYLERİNE ALDANMA. BU UFAKLIĞIN DELİCİ BAKIŞLARI HEMEN HERKESİ SİNDİREBİLİR. O NÖBETTEYKEN BİR ŞEY ÇALMAYA KALKIŞANIN VAY HÂLİNE.",
