["bm_msk_silverback_desc"] = "GÜMÜŞ SIRTLI GORİL STEVEN. SADECE DEV GİBİ DEĞİL, FENA HÂLDE GÜÇLÜ DE. SANA BAKARAK BİLE BELİNİ KIRABİLİR. HAFTALARCA HASTANEDE KALIRSIN. ÜSTÜNE AYLARCA TEDAVİ DE VAR. YENİDEN YÜRÜMEYİ ÖĞRENMEK NE KADAR ZOR, BİLİYOR MUSUN? BAŞKA NE SERT, BİLİYOR MUSUN? STEVEN’IN KASLARI. 22 YIL ÖNCE BİR ASKERÎ GEMİDE AŞÇIYDI. 103 DAKİKADA HERKESİ ÖLDÜRDÜ.",
["bm_msk_simpson_desc"] = "BAZILARI YARIŞ TULUMUNUN AĞARTILMIŞ YUNUS DERİSİNDEN YAPILDIĞINI, YAĞLI SALGILARININ ÇİN TIBBINDA DEĞER GÖRDÜĞÜNÜ SÖYLÜYOR. TEK BİLDİĞİMİZ... ADI THE TIDS.",
["bm_msk_skm_01_desc"] = "HERKESİN İÇİNDE SEÇKİN SOYGUNCUYA HİTAP EDEN BİR ŞEY VARDIR. NEW YORK’UN ÜNLÜ ŞAPKACILARININ YAPTIĞI BU KLASİK ŞAPKA, HER KOLLUK GÖREVLİSİNİN BAKIŞINI ÜZERİNE ÇEKER.",
["bm_msk_skm_02_desc"] = "CİLAYI SÜR, CİLAYI SİL. GANİMETİNLE SİSLİ GECEYE KARIŞIP GÜLERKEN ONU GÖNLÜNCE BUR.",
["bm_msk_skm_03_desc"] = "KEŞKE ŞU MUHTEŞEM GÖZLÜKTE BİR HOLOGRAFİK MERCEK DE OLSAYDI. AMA NE YAZIK Kİ YALNIZCA KASAYA DOĞRU TUŞ BİRLEŞİMİNİ GİRERKEN KLASİK BİR ŞIKLIK SERGİLEMENİ SAĞLAYACAK.",
["bm_msk_skm_04_desc"] = "ESKİ USUL KÖTÜLÜĞÜN ZİRVESİ. İSTER FRAKLA İSTER ZIRHLA TAMAMLA; BU TAKIM HERKESE CİDDİ OLDUĞUNU, HEM DE EN SUÇLU ANLAMIYLA CİDDİ OLDUĞUNU ANLATIR.",
["bm_msk_skm_05_desc"] = "GELECEKTEN GELEN ROBOT EFENDİLER, SEVİNİN! LİDERİNİZ GELDİ; YANINDA DA BOLCA POZİTİF YÜKLÜ PARÇACIK GETİRDİ.",
["bm_msk_skm_06_desc"] = "BU MİĞFERLE POLİSLERE, 80’LERİN BÜTÜN METAL GRUPLARININ TANRISI TARAFINDAN SALDIRIYA UĞRADIKLARINI DÜŞÜNDÜR!",
["bm_msk_skm_07_desc"] = "KORSAN KRALLARI’NIN EN GİZEMLİSİ KORKUNÇ SKULLTOOTH, ORTALIKTAKİ TÜM KOLLUK KUVVETLERİNE TİTREME GETİRECEK. YARR!",
["bm_msk_skm_08_desc"] = "SÖYLENTİYE GÖRE BU MİĞFER TERK EDİLMİŞ BİR RUS NÜKLEER TESİSİNDE BULUNMUŞ. TAKAN KİŞİ ZAMANLA SÜPER GÜÇLER KAZANACAKMIŞ. AMA SADECE SÖYLENTİ.",
["bm_msk_skull_desc"] = "ÖLÜMÜ VE FANİLİĞİ TEMSİL EDEN ÖZEL BİR MASKE.$NL;$NL;TANRILAR TARAFINDAN GÖKLERDE YARATILIP ONLARA EN BAŞINDAN İNANAN, TAPINAKLARINI KURAN VE İNANÇLARINI DİYAR DİYAR YAYAN KADINLARLA ERKEKLERE ARMAĞAN EDİLDİ.$NL;$NL;BİZE İNANDIĞINIZ İÇİN TEŞEKKÜRLER! SİZİ SELAMLIYORUZ!",
