["bm_msk_skullhard_desc"] = "İNSAN KAFATASI TUHAF BİR ŞEY. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR.",
["bm_msk_skullhard_desc_WIN32"] = "İNSAN KAFATASI TUHAF BİR ŞEY. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR.$NL;$NL;BÜTÜN SOYGUNLARI ZOR ZORLUKTA BİTİRDİN Mİ? SEN NESİN, PROFESYONEL FALAN MI? BELKİ DE BU MASKE SANA YAKIŞIR.",
["bm_msk_skullmonkey_desc"] = "SİYAH BAŞLIKLI SİNCAP MAYMUNU CLİNT. ADSIZ BİR MAYMUN DEĞİL YANİ. GERÇEK CLİNT GİBİ BU MAYMUN DA BOŞ İŞLERLE UĞRAŞMAZ. KENDİ İŞİNE BAKAR. KENDİSİNE KONUŞULMADAN KONUŞMAZ; AZ SÖYLEDİKÇE GÜÇLENDİĞİNİ BİLİR. GERÇEKTEN BİR ŞEY SÖYLEMEYE KALKIŞTIĞINDA İSE ÇIĞLIK ATAR; ÇÜNKÜ LANET OLASI BİR MAYMUNDUR.",
