["bm_msk_skulloverkill_desc_WIN32"] = "HASSİKTİR, BU YENİ ŞEYTANLIK DA NE? İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. AMA BU İNSAN KAFATASINA BENZEMİYOR.$NL;$NL;BÜTÜN SOYGUNLARI OVERKILL ZORLUĞUNDA BİTİRDİN Mİ? SEN NESİN, CEHENNEM ZEBANİSİ FALAN MI? BELKİ DE BU MASKE SANA YAKIŞIR.",
["bm_msk_skulloverkillplus_desc"] = "OVERKILL SENİ SELAMLIYOR; ÖLÜMÜ GETİREN, KOLLUK KUVVETLERİNİ KATLEDEN, TÜM ZORLUKLARI TAMAMLAYAN KİŞİ. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. AMA BU BİR İNSAN KAFATASI DEĞİL, BAMBAŞKA BİR ŞEY.",
["bm_msk_skulloverkillplus_desc_WIN32"] = "OVERKILL SENİ SELAMLIYOR; ÖLÜMÜ GETİREN, KOLLUK KUVVETLERİNİ KATLEDEN, TÜM ZORLUKLARI TAMAMLAYAN KİŞİ. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. AMA BU BİR İNSAN KAFATASI DEĞİL, BAMBAŞKA BİR ŞEY.$NL;$NL;BÜTÜN SOYGUNLARI DEATH WISH ZORLUĞUNDA BİTİRDİN Mİ? SEN NESİN, İBLİS FALAN MI? BELKİ DE BU MASKE SANA YAKIŞIR.",
["bm_msk_skullveryhard_desc"] = "İNSAN KAFATASI TUHAF BİR ŞEY. GERÇİ BU KAFATASI ARTIK PEK İNSANA BENZEMİYOR. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. AMA BU KAFATASINDA TUHAF BİR ŞEYLER VAR.",
["bm_msk_skullveryhard_desc_WIN32"] = "İNSAN KAFATASI TUHAF BİR ŞEY. GERÇİ BU KAFATASI ARTIK PEK İNSANA BENZEMİYOR. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. AMA BU KAFATASINDA TUHAF BİR ŞEYLER VAR.$NL;$NL;BÜTÜN SOYGUNLARI ÇOK ZOR ZORLUKTA BİTİRDİN Mİ? SEN NESİN, CANAVAR FALAN MI? BELKİ DE BU MASKE SANA YAKIŞIR.",
["bm_msk_slicer_desc"] = "KARDEŞİNİN ÖLDÜRÜLMESİNDEN SONRA IKAS, EĞİTİM ALIP EN ÖLÜMCÜL SAVAŞÇILARI OLMAK İÇİN GİZLİ BİR NİNJA KLANINA KATILDI. IKAS KENDİNİ ÇABUCAK KANITLADI VE KLANIN BÜTÜN AMERİKA KOLUNUN BAŞINA GETİRİLDİ. KENDİNE ÖZGÜ MASKESİ ARTIK KORKU VE SAYGI UYANDIRIYOR; BÖYLE MASKE TAKAN HERKES ACHİLLES CLAN’İN KARDEŞİ SAYILIR.",
["bm_msk_slimy_goat_desc"] = "YUNUS, HAYVANLAR ÂLEMİNİN EN SİNSİ VE ACIMASIZ SOYGUNCUSUDUR; DOST CANLISI VE SEVİMLİ GÖRÜNÜMÜYLE HERKESİ KANDIRIR. AMA HEPSİ BİR ALDATMACA! YUNUS YALNIZCA KENDİNİ VE GANİMETİ DÜŞÜNÜR, BİRİNİ GERİDE BIRAKMAKTA BİR SANİYE BİLE TEREDDÜT ETMEZ. BU MASKEYİ TAKAN BİR SOYGUNCUYLA KARŞILAŞIRSAN DİKKATLİ OL.",
["bm_msk_smiley_desc"] = "BİR ZAMANLAR GÜLÜMSEYEMEYEN BİR PALYAÇO VARDI. DİĞER PALYAÇOLARIN GENCE YAŞLIYA NEŞE VE MUTLULUK VERDİĞİNİ İZLEDİ. KISKANÇLIĞI VE ÖFKESİ BÜYÜDÜ; SONUNDA GENİŞ BİR SIRITIŞ ELDE ETMEK İÇİN DUDAKLARINI YANAKLARINA ZIMBALADI. AMA HERKESİ MUTLU ETMEK YERİNE KORKUTTU. NEDENİNİ ANLAYAMADI.$NL;$NL;BELKİ DE GÖREVİNİN BU OLDUĞUNA KARAR VERDİ; İNSANLARI KORKUTMAK... HEM DE ÇOK KORKUTMAK.",
["bm_msk_smo_01_desc"] = "BİR SOYGUNCU SOKAKTA BU MASKEYLE YÜRÜYORSA DÜNYA ONUN HİÇBİR ŞEYDEN KORKMADIĞINI ANLAR. DOKUZ CANIN DA CANI CEHENNEME!",
["bm_msk_smo_02_desc"] = "EFSANELERE GÖRE OKİNAWA ORMANLARINDA ALEV BAŞLI BİR TİLKİNİN RUHU YAŞAR. BU TİLKİNİN SENİ GÖRMESİ BİR NİMET SAYILIR AMA BU MASKEYİ TAKMIŞ BİR SOYGUNCUNUN SENİ GÖRMESİ MUHTEMELEN ÖYLE DEĞİLDİR!",
["bm_msk_smo_03_desc"] = "1990’LARIN BİR VİDEO OYUNUNDAKİ ŞEYTAN’A TAPANLAR ARADI; DÜŞÜK POLİGONLU KEÇİLERİNİ GERİ İSTİYORLARMIŞ. VERECEK MİSİN, YOKSA ONLARI BOŞ MU ÇEVİRECEKSİN?",
["bm_msk_smo_04_desc"] = "BAZI VUDU RAHİPLERİ SONSUZ YAŞAMIN SIRRINI BİLDİKLERİNİ İDDİA EDER. BU MASKEYİ TAKMANIN ONU SAĞLAYACAĞININ GARANTİSİ YOK AMA DÜŞMANLARININ ÖDÜNÜ MUHTEMELEN KOPARIR. BELKİ BİR JAMAİKA BARBEKÜSÜNE DAVET EDİLMENİ DE SAĞLAR.",
["bm_msk_smo_05_desc"] = "BU MASKEYİ TAKARKEN POLİSLERE ATTIĞIN EL BOMBALARINI FIÇI SAYABİLİRSİN. ONLAR HOŞLANMAZ AMA BİR ŞEYLERİ PATLATMANIN TEKDÜZELİĞİNİ BELKİ BOZAR!",
["bm_msk_smo_06_desc"] = "AH, NE DÜŞÜNCELERE DALABİLİRSİN; ZENGİN VE KÜFÜRBAZ HÂLİNLE, UNUTULMAMIŞ PARANIN O TUHAF, MERAK UYANDIRAN YIĞINI ÜZERİNDE. BÖYLE BUYURDU SOYGUNCU.",
["bm_msk_smo_07_desc"] = "1980’LERİN HER ÇOCUĞU BU MASKE İÇİN ADAM ÖLDÜRÜR. NEON OTOYOLLARIN GERÇEK HÂKİMİ KİMMİŞ, HERKESE GÖSTER.",
["bm_msk_smo_08_desc"] = "ŞEYTANLAR DA İBLİSLER DE BU MASKEYİ TAKAN SOYGUNCUNUN İHTİŞAMINI GÖRDÜKLERİNDE HAYRANLIKLA TİTREYECEK.",
["bm_msk_smo_09_desc"] = "TRAGİC CLOWN’A BU EN BÜYÜK SAYGI GÖSTERİSİNİN İŞKENCE EDERCESİNE MUTLU SIRITIŞINA, ÇÜRÜYEN ALTIN DİŞLERİNE VE DERİNDEN BÜYÜLEYEN BAKIŞINA BİR BAK.",
["bm_msk_smo_10_desc"] = "MEZUNİYET BALOSU KRALİÇELERİ, ALNINA BU PARLAK SÜSÜ TAKAN BİR SOYGUNCUNUN YANINDA HİÇ KALIR. SÖYLENTİYE GÖRE TAŞLARIN HEPSİ 1800’LERDE DÜNYA’YA DÜŞEN BİR PERSEİD GÖKTAŞINDAN GELMİŞ.",
["bm_msk_smo_11_desc"] = "BİR MISIR TANRISI GİBİ HAVLA; GANİMET YIĞINLARINI KORUYUP KOLLARKEN SONSUZA DEK NÖBET TUT.",
["bm_msk_smo_12_desc"] = "BU MASKENİN DEHŞETİNİ SALIP HEM POLİSLERE HEM SİVİLLERE 1960’LARIN BİR KORKU FİLMİNDE OLDUKLARINI DÜŞÜNDÜR.",
["bm_msk_smoker_desc"] = "BÖYLE BİR MASKEYİ ANCAK GERÇEK BİR TEKNİSYEN TASARLAYABİLİR.$NL;$NL;SON TEKNOLOJİ HAVA FİLTRELEME SİSTEMİ SAYESİNDE, O PEK OLASI OLMAYAN \"METAMFETAMİN PİŞİRMEM GEREK\" DURUMLARINDA KİMYAGER BAŞLIĞI OLARAK DA KULLANILABİLİR.$NL;$NL;BU MASKE, KÖTÜ ŞÖHRET AĞACI ÖDÜLÜDÜR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_sms_01_desc"] = "DALLAS BAZEN BAIN’İN SECRET’IN BAZI AYRINTILARINI ONDAN SAKLADIĞINI HİSSEDİYORDU. FIRST WORLD BANK’TEKİ İŞTEN SONRA BAIN, MAYA ALTINININ NEDEN BU KADAR ÖNEMLİ OLDUĞUNU HİÇ AÇIKLAMADI. THE PAYDAY GANG BİR AİLE VE GÜVEN HER ZAMAN KURŞUNGEÇİRMEZ DEĞİL. AMA DALLAS ARTIK, YOLUN SONUNDA, BAIN’İN GİZLİLİK İHTİYACINI ANLIYOR. ONUN BİLGELİĞİ SAYESİNDE İKİSİ DE KENDİ İSTEDİĞİNİ ALDI.",
["bm_msk_sms_02_desc"] = "CHAINS, SECRET ARAYIŞINI HİÇ FAZLA CİDDİYE ALMADI; SIK SIK BİR SÜRÜ \"TUHAF ZIRVA\" DERDİ. AMA AYAKLARI YERE BASAN PRATİK BİR ADAM OLARAK BAIN İLE İLİŞKİSİNE GÜVENEREK KARARLI VE SADIK KALDI.",
["bm_msk_sms_03_desc"] = "HOXTON, YENİ ÜLKEDE VURGUNUNU YAPMAK İÇİN ESKİ ÜLKE’Yİ GERİDE BIRAKTI. BAIN ONA SECRET’I İLK ANLATTIĞINDA KADİM EŞYALARIN OLASI DEĞERİ İÇİN PEŞLERİNE DÜŞME FİKRİ HOŞUNA GİTMİŞTİ. BAIN’İN SÖZÜNÜ ETTİĞİ EFSANEVİ GÜCÜN GERÇEK OLUP OLMADIĞINIYSA PEK UMURSAMIYORDU.",
["bm_msk_sms_04_desc"] = "WOLF HEP ŞİDDETE MEYİLLİ, ÖNGÖRÜLEMEZ BİR MÜTTEFİKTİ. BU YÜZDEN BAIN, SECRET ARAYIŞININ NE KADARINI ONA ANLATACAĞINDAN BAŞTA EMİN DEĞİLDİ. SONUNDA DEĞERİ ORTAYA ÇIKTI AMA BAIN ARAYIŞINI NİHAYET AÇIKLADIĞINDA WOLF AKLINI KAÇIRACAK KADAR HEYECANLANDI. HEM ALTIN KAZANCINDAN PAYINI ALACAKTI HEM DE İYİ BİR KOMPLOYA BAYILIRDI.",
["bm_msk_sms_05_desc"] = "BİR LİDER OLARAK KARİYERİ BOYUNCA ÇOK ŞEYDEN VAZGEÇMEK ZORUNDA KALDI. İŞLER, EKİP ÜYELERİ, KİŞİSEL HEDEFLER; İŞİ BİTİRMEK İÇİN NE GEREKİYORSA. MEZOAMERİKA KÜLTÜRLERİ TANRILARI HOŞNUT ETMEK İÇİN NASIL KURBAN VERDİYSE DALLAS DA SOYGUN TANRILARINA, YANİ İŞVERENLERE ÖYLE KURBANLAR VERDİ.",
["bm_msk_sms_06_desc"] = "VAHŞİLİK, ÖLÜME MEYDAN OKUMA VE ALTIN; ESKİ MISIRLILARIN HER ŞEYE KARŞI KOYARAK GELİŞİP FETHETMESİNİN UNSURLARI. BU KADİM KÜLTÜRÜ ONURLANDIRAN MASKEYİ WOLF’UN TAKMASI DA BU YÜZDEN BİR BAKIMA YERİNDE.",
["bm_msk_sms_07_desc"] = "SÜMERLER BİLGELİK, MÜZİK VE RUHSAL GÜÇ ÇAĞINI BAŞLATTI; DÜNYANIN NASIL BAŞLADIĞINA DAİR FİKİRLER KURACAK HAYAL GÜCÜNE SAHİPLERDİ. CHAINS DIŞARIDAN PROFESYONEL BİR SİLAH USTASI OLABİLİR AMA İÇİNDE HAYATTAN BİLE BÜYÜK BİR RUH TAŞIR. BU YÜZDEN BU MASKENİN TEMSİL ETTİĞİ KÜLTÜRÜ ONURLANDIRIR.",
["bm_msk_sms_08_desc"] = "İNSANLIĞA EN BÜYÜK ARMAĞANI VERENLER, UYGARLIKLARI TOPRAĞIN VE SUYUN ALTINDA YATIYOR OLABİLECEK OLANLAR NEREDEN GELDİ? KİM OLURLARSA OLSUNLAR, VARLIKLARININ İZLERİNİN ÇOĞU ZAMANLA SİLİNDİ. YENİ BİR GELECEK ARAYAN GEZGİN HOXTON GERÇEĞİ BİLMİYOR OLABİLİR AMA SECRET’IN KÖKENİNİ ONURLANDIRMAK İÇİN YİNE DE ONLARIN MASKESİNİ TAKIYOR.",
["bm_msk_sokol_begins_desc"] = "BU, SOKOL’UN İKONİK MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_sokol_desc"] = "ST PETERSBURG BOMBERS HOKEY TAKIMINDA MÜCADELECİ BİR OYUNCU OLMAK SOKOL’A BİR ŞEYİN DEĞERİNİ ÖĞRETTİYSE O DA YAKIŞIKLI RUS YÜZÜNÜ KORUYAN KORKUTUCU BİR MASKENİN ÖNEMİYDİ.",
["bm_msk_solus_desc"] = "GEZEGEN MEZARI MUHAFIZLIĞI YALNIZ BİR İŞTİR. AMA YAPILMASI GEREKEN BİR İŞTİR. GÖRÜNÜRDE TEK BİR CANLI BİLE OLMADAN ÇAĞLAR GEÇER. YILDIZLAR VE GÜNEŞLER GÜNDÜZLE GECEYİ AYDINLATIR. AMA YALNIZLIK KORKUNÇTUR. DERKEN BİR GÜN BİR UZAY ARACI SESSİZLİĞİ BOZAR; ARTIK YALNIZ DEĞİLSİN. BİRİ, EVİM DEDİĞİN BU GEZEGENİ ZİYARET EDİYOR.",
["bm_msk_sombrero_desc"] = "BUNU TAKAN SOYGUNCUYA GÜLEN KİŞİ, YÜZÜNDEKİ KOCAMAN MERMİ DELİĞİYLE GÜLEMİYORSA SON KEZ GÜLDÜĞÜNÜ YAKINDA ANLAYABİLİR.",
["bm_msk_spa_01_desc"] = "KAPTAN KÖPRÜDE! MÜRETTEBATINI BANKALARDA SAĞ SALİM GEZDİR; ELVERİŞLİ BİR RÜZGÂR SENİ BÜYÜK MACERALARA TAŞISIN. KIYIYI VURUP HAZİNELERİNİ AL, SONRA UFUKTA KAYBOL.",
["bm_msk_spa_02_desc"] = "HAZİNE FİLOSUNDA DENİZE AÇIL. BATIK ALTINI ARARKEN ARMAYA TIRMANIP PEŞİNDEKİ GEMİLERE GÖZ KULAK OL. YETİŞİRLERSE OLDUĞUN SIÇAN GİBİ GEMİYİ TERK ET AMA ALTINI ALMAYI UNUTMA.",
["bm_msk_spa_03_desc"] = "YÜKSEKLERDE SÜZÜL, AŞAĞI DALIP AVINA ACIMASIZ, ÖLÜMCÜL PENÇELERLE SALDIR. SONRA YÜKSEKLERDEKİ YUVANA UÇ, AVININ NİMETLERİNİ TAT. BESİN ZİNCİRİNİN TEPESİNDEKİ YIRTICI SENSİN VE HER ŞEYİ SİLİP SÜPÜRECEKSİN.",
["bm_msk_spa_04_desc"] = "ÖZGÜRLÜK. YAKALANIP HAPSE ATILMIŞ TÜM SOYGUNCULARA ÖZGÜRLÜK. BANKALARIN KARANLIK BODRUM KASALARINDA HÜZÜNLE BEKLEYEN TÜM ALTINLARA ÖZGÜRLÜK. GİRİŞİM RUHUNA, İSTEDİĞİNİ ALMA İRADESİNE, SİLAHIN HÜKMÜNE ÖZGÜRLÜK. DAHA BÜYÜK BİR VURGUN ARAYANLARA ÖZGÜRLÜK.",
["bm_msk_spackle_desc"] = "BİR ZAMANLAR ÜNLÜ BİR SİRK PALYAÇOSU OLAN SPACKLE, CAMİANIN EN İYİ MAKYAJ SANATÇISIYDI. İNSANLARI KENDİLERİNE HİÇ BENZEMEZ HÂLE GETİRME BECERİSİYLE TANINIYORDU; BU SANATA SAPLANTILI HÂLE GELDİ.$NL;$NL;KENDİ YÜZÜNÜ TUVAL YAPIP YORULMADAN KAT KAT MAKYAJ SÜRDÜ. HER KATMAN DAHA ÇARPIKTI. MAKYAJLARINI YAPARKEN BEŞ KİŞİYİ ÖLDÜRDÜKTEN SONRA AKIL HASTANESİNE GÖNDERİLDİ.",
["bm_msk_speed_demon_desc"] = "MOTORCU YAŞAMININ HİÇBİR ŞEYİ UMURSAMAYAN TAVRINI SİMGELEMEK İÇİN DEVİL’IN YÜZÜNÜ TAKMAKTAN DAHA İYİ NE OLABİLİR? KANUNU ÇİĞNEMENİN NİHAİ SİMGESİ.",
["bm_msk_speedfreak_desc"] = "KAFANDAKİ SESLER SENİ DELİRTMEK İSTİYORSA ÖNCE YAKALAMALARI GEREKECEK.",
["bm_msk_speedrunner_desc"] = "HIZLI BİR KOŞUNUN ZAMANI GELDİ! SPEEDRUNNER, NEW RUSH CİTY HALKININ ŞAMPİYONU. SUÇA VE YARDIMA MUHTAÇLARA DOĞRU KOŞARAK, KAYARAK, SALINARAK İLERLER; BİRİNCİLİKTEN AZINI KABUL ETMEZ. SPEEDRUNNER’IN İHTİYACI... KOŞMAK!",
["bm_msk_spider_desc"] = "SEKİZ GÜÇLÜ BACAKLI TARANTULALARIN BOYU, BACAKLARI TAMAMEN AÇILDIĞINDA TIRNAK KADAR KÜÇÜKTEN TABANCA KADAR BÜYÜĞE KADAR DEĞİŞİR. ADI ASLINDA BİR KURT ÖRÜMCEĞİ TÜRÜ OLAN LYCOSA TARANTULA’DAN GELİR. TARANTULALAR GENELLİKLE AĞAÇLARDA, YERDE VEYA YERE YAKIN AVLANIR. EV HAYVANI OLARAK DA POPÜLERDİRLER.",
["bm_msk_sports_utility_mask_desc"] = "HANTAL VE DEMODE KASKLARI UNUT; BU MUHTEŞEM ŞEY HER ADRENALİN TUTKUNUNUN EN İYİ DOSTU. SERT ABS PLASTİKTEN YAPILMIŞ YÜZ KORUMASI KARA, KUM SAVRULMALARINA VE DOLUYA KARŞI SAĞLAM KORUMA SAĞLAR. YETER Kİ KAFANA AĞIR DARBE ALMA. AİRBOARD YAPAN ARKADAŞLARIN SANA GIPTA ETSİN DOSTUM!",
["bm_msk_sputnik_desc"] = "ORİJİNAL SPUTNİK YALNIZCA BİPLEYEN KÜÇÜCÜK BİR KÜRE OLMASINA RAĞMEN 1950’LERİN WASHINGTON’INDA SİYASİ ŞOK DALGALARI YARATTI. BU KLASİK AMA SÜSLENİP PÜSLENMİŞ SÜRÜMLE BAŞKENTTE SUÇ DALGALARI YARAT.",
["bm_msk_starvr_desc"] = "GERÇEK HAYAT KİRLİ, RAHATSIZ, YAPIŞKAN, TERLİ, PİS KOKULU; TADI KÖTÜ, SONUNDA SENİ YAŞLI VE KIRIK DÖKÜK BIRAKIYOR. BOŞ VER GİTSİN. STARVR HEADSET, İNANILMAZ GERÇEKÇİ BİR SANAL DÜNYANIN İÇİNE DALMANI SAĞLAR.",
["bm_msk_stoneface_desc"] = "BU GÖZLÜK, UZAK BİR DİYARDAN BİR SUİKASTÇIYA AİTTİ. JOHN’UN ÖLDÜRMEYE GÖNDERİLDİĞİ SUİKASTÇI MAKİNE GİBİYDİ. BU ZORLU BİR İŞ OLACAKTI. ÖZELLEŞTİRİLMİŞ BİR GELİŞTİRİLMİŞ BİRLEŞİK TAKTİK YELEK KULLANIYORDU. BAŞTAN AŞAĞI ZIRHLIYDI, ÇOK SAĞLAMDI. AMA JOHN BÜTÜN O ZIRHIN ALTINDA YALNIZCA ET VE KEMİK OLDUĞUNU BİLİYORDU.$NL;$NL;SONUNDA JOHN ONU ÖLDÜRMEYİ BAŞARDI. AMA ONU YERİNDEN ETTİĞİNDE YERİNE BİR BAŞKASININ GELECEĞİNİ BİLİYORDU.",
["bm_msk_stonekisses_desc"] = "DUDAK BÜZMEK, İNSANLARIN YAPABİLDİĞİ BİR YÜZ İFADESİDİR.$NL;$NL;ÖZELLİKLE SOMURTKAN BİR HOŞNUTSUZLUĞU ANLATMAK İÇİN DUDAKLARIN DIŞARI UZATILMASIDIR.$NL;$NL;BOYNUZLARI ÖYLE TESTEREYLE KESİLSE KİM HOŞNUTSUZ OLMAZ Kİ?",
["bm_msk_strinch_achievement"] = "AÇMAK İÇİN NOEL'İ ÇALMAK BAŞARIMINI TAMAMLA!",
["bm_msk_surprise_desc"] = "SAVAŞ SURATIN VAR MI! AAAAAAAAHH! İŞTE SAVAŞ SURATI BUDUR, HADİ SENİNKİNİ GÖREYİM!$NL;$NL;...$NL;$NL;SAÇMALIK. BENİ İKNA ETMEDİN. GERÇEK SAVAŞ SURATINI GÖREYİM!$NL;$NL;...ASLINDA BU FENA DEĞİL...$NL;$NL;BU MASKE BİR POETRY JAM MASKESİDİR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_sweettooth_desc"] = "ASIL ADI MARCUS \"NEEDLES\" KANE OLAN SWEET TOOTH, TWİSTED METAL VİDEO OYUNU SERİSİNİN BİR KARAKTERİDİR. SWEET TOOTH EN ÇOK SAVAŞ DONANIMLI BİR DONDURMA KAMYONU SÜREN KATİL PALYAÇO OLARAK TANINIR.$NL;$NL;BİR ZAMANLAR AKIL HASTANESİNDEN KAÇTIĞI SÖYLENİR. ŞİMDİ SUÇ DOLU BİR HAYAT SÜRÜYOR.",
["bm_msk_sydney_begins_desc"] = "BU, SYDNEY’NİN İKONİK MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_sydney_desc"] = "SIRITIŞ, TEBESSÜM, ALAYCI GÜLÜŞ; NE DERSEN DE. BU SIRITAN PUNK MASKESİNİN YAKLAŞTIĞINI GÖRDÜĞÜNDE KAFANDAN EŞ ANLAMLI SÖZCÜKLER GEÇMEYECEK, MERMİLER GEÇECEK. SYDNEY BUNU GARANTİ EDER.",
["bm_msk_tall_goat_desc"] = "ZÜRAFA HİÇBİR ŞEYİ KAÇIRMAZ; ÇEVRESİNİN HEP TAMAMEN FARKINDADIR. HAYVANLAR ÂLEMİNDE SOYGUN İÇİN KUSURSUZ BİR \"GÖZCÜ\" YOLDAŞIDIR. NE GELİYORSA KİLOMETRELERCE ÖTEDEN GÖRÜRSÜN, POLİSLER DE SENİ HAZIRLIKSIZ YAKALAMAYI UNUTSUN.",
["bm_msk_tam_desc"] = "YOLCU BİN YIL UYUDU; YILDIZLAR HİZALANIP YETERİNCE YETENEKLİ BİR ÖLÜMLÜ ONU O KUTSAL OLMAYAN HAPİSHANEDEN ÇIKARANA DEK BEKLEDİ. SEVİNİN! O GÜN GELDİ. BU GÜCÜ... AKILLICA KULLAN.",
["bm_msk_tane_desc"] = "TANE, MUAZZAM GÜCÜYLE ANNE BABASI OLAN YERİ VE GÖĞÜ BİRBİRİNDEN AYIRAN ORMAN TANRISIYDI. EFSANELER İLK İNSAN TİKİ’Yİ DE ONUN YARATTIĞINI SÖYLER. BÖYLECE BİLDİĞİMİZ DÜNYAYI VE İÇİNDEKİ İNSANLARI YARATTI.",
["bm_msk_tcn_desc"] = "YALNIZCA EN HIRSLI SOYGUNCUYA LAYIK BİR MASKE.$NL;$NL;BÜTÜN GANİMETİ AL, HİÇBİR ŞEY BIRAKMA.$NL;GERÇEK SUÇ DEHASININ İŞARETİ BUDUR.$NL;BÜTÜN ELMASLARI, KÜÇÜK KAZANÇLARI TOPLA.$NL;ARTIK SUÇLA DOLU BÜYÜK HAYALLERİN VAR.$NL;$NL;BU MASKE BİR POETRY JAM MASKESİDİR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_tech_lion_desc"] = "BU MASKE, MISIR SAVAŞ TANRISI MAAHES’İN MODERN BİR YORUMU. \"BIÇAĞI TAŞIYAN\", \"KATLİAMIN EFENDİSİ\" VE \"HAKSIZLIKLARIN ÖCÜNÜ ALAN\" OLARAK BİLİNEN MAAHES, DÜZENLE DENGENİN KİŞİLEŞMİŞ HÂLİ MA`AT’IN KURALLARINI ÇİĞNEYENLERİ CEZALANDIRIRDI. GÜNEŞİN YAKICI SICAĞININ VÜCUT BULMUŞ HÂLİ SAYILIR, SAVAŞTA FİRAVUNU SAVUNAN KORUYUCU BİR TANRI OLARAK DA GÖRÜLÜRDÜ.$NL;$NL;GENELLİKLE BIÇAK TAŞIYAN, ATEF TACI VEYA GÜNEŞ DİSKİ TAKAN ASLAN BAŞLI BİR ADAM YA DA BİR KURBANI YİYEN ASLAN ŞEKLİNDE TASVİR EDİLİR.",
["bm_msk_the_king_mask_desc"] = "İNSAF! O HAVALI PİLOT GÖZLÜKLERİ, BELALI POMPADUR SAÇ VE TAKTİK FAVORİLERDEN OLUŞAN KRALİYET ÜÇLÜSÜNÜ TAŞIYACAK KADAR FENA BİR DELİKANLI YA DA KIZ MISIN? VEGAS’IN DÖRT BİR YANINDA BUNU TAKIP BAŞARIYA ULAŞAN İKİNCİ EL OTOMOBİL SATICILARININ VE APAR TOPAR NİKÂH KIYAN DİN ADAMLARININ YILMAZ RUHUNU ÇAĞIR. YA DA EN AZINDAN TOPLUM İÇİNDE HAFİF BİR MAHCUBİYETE ULAŞANLARIN. KRALI SELAMLAYIN!",
["bm_msk_the_overkill_mask_desc"] = "HAZIR OL! PEKÂLÂ DİNLEYİN, SİZİ SOYGUNCU PİÇLER. SAVAŞA GİDİYORSUNUZ. ÇATIŞMANIN ACISINI HİSSEDECEKSİNİZ. SAVAŞTA DA LİDER GEREKİR. GENERAL OVERKILL’LE TANIŞIN. O POLİS PİSLİKLERİNİ KAZDAN BOK GEÇER GİBİ GEÇMENİZİ SAĞLAYACAK. DAĞILIN!",
["bm_msk_the_strinch_desc"] = "BAYRAM DÖNEMİNİN TECRÜBELİ SOYGUNCUSU STRİNCH, 1957’DEN BERİ NOELLERİ ÇALIYOR. 1972’DEKİ HALLOWEEN HEİST İLE DE BAĞLANTILI.",
["bm_msk_threap_desc"] = "ONU ON ARABALIK ZİNCİRLEME KAZALARIN FOTOĞRAFLARINDA, KAMYON ÇARPIŞMALARININ HABER GÖRÜNTÜLERİNDE GÖRDÜN; HEP KORKUNÇ BİR KAZANIN YANINDAN GEÇERKEN. TEPEDEN TIRNAĞA SİYAHA BÜRÜNMÜŞ BİR MOTOSİKLETLİ, HIZDAN BULANIKLAŞAN SOLGUN BİR YÜZ. SANA ONUN SIRADAN BİR MOTORCU OLDUĞUNU SÖYLÜYORLAR. MİLYONLARCASINDAN BİRİ. AMA ONU DAHA ÖNCE GÖRDÜĞÜNÜ BİLİYORSUN. ŞİMDİ DE BU BUZLU, KARDAN GÖZ GÖZÜ GÖRMEYEN OTOYOLDA HEMEN ÖNÜNDE SÜRDÜĞÜNÜ GÖRÜR GİBİ OLUYORSUN...$NL;FRENLERİNİN ÇALIŞMADIĞINI İŞTE O AN FARK EDİYORSUN.",
["bm_msk_tiara_desc"] = "TAMAM, YÜZÜNÜ GİZLEMİYOR VE SANA DOĞRU VIZILDAYAN MERMİLERİ DE KESİNLİKLE DURDURMAZ... AMA VAY BE. MRS VOLKOV’UN GELİN TACINI TAKTIĞINDA BALONUN EN GÜZELİ SEN OLACAKSIN.",
["bm_msk_tiger_desc"] = "TONY KENDİSİNE BULAŞAN HERKESİ ÖFKE DOLU YUMRUKLARIYLA PATAKLAR.$NL;$NL;TONY, 1970’LERDE DOĞMUŞ İTALYAN ASILLI BİR AMERİKALIDIR. PEK ÇOK KİŞİ TONY’Yİ KOLAYCA TANIR. MUHTEMELEN HEM TİGER MASKESİ HEM DE SEVMEDİĞİ İNSANLARA KARŞI FİZİKSEL VAHŞETİ SAYESİNDE.",
["bm_msk_tinted_love_desc"] = "CİNAYET, HARAÇ, ŞİDDET, YIKIM, UYUŞTURUCU, SİLAH VE HIRSIZLIK. BUNLARIN HEPSİ VLAD’LA İLİŞKİLENDİRİLEN SUÇLAR AMA HİÇBİRİ ONUN MODA ANLAYIŞI KADAR BÜYÜK DEĞİL.",
["bm_msk_titan_desc"] = "BİR ZAMANLAR ARAMIZDA YÜRÜRLERDİ. KULELER KADAR UZUN, DEVASA VARLIKLAR. PRİMAT ATALARIMIZ ATEŞE ULURKEN ONLAR ZATEN YAŞLIYDI. ARTIK YOKLAR; YALNIZCA GÖLGELERİ, YARI DÜŞLENMİŞ TÜR HATIRALARINDA BİZE ULAŞIYOR.",
["bm_msk_tonys_revenge_desc"] = "NEREDEYSE KUSURSUZ YIRTICI. KAPLANLAR SON DERECE GÜÇLÜ, BİR O KADAR DA HIZLIDIR. VAHŞİ AMA SABIRLIDIRLAR. SESSİZCE SOKULUP BİR ANDA ŞİDDETLE SALDIRABİLİRLER. KUSURSUZ BİR ÖLÜM MAKİNESİ. BUNA RAĞMEN KAPLANLARIN SAYISI AZALIYOR. KAÇAK AVCILAR, GELENEKSEL TIP İÇİN KAPLAN PENİSİNE DEĞER BİÇİYOR. O YÜZDEN SAKIN CANLI ELE GEÇME.",
["bm_msk_toon_01_desc"] = "BAZILARI HAYATTA BEDAVADAN YOL ALMAK, YAKIŞIKLILIKLA VE ŞANSLA İLERLEMEK İSTER. BAZEN ÖYLE GÖRÜNSE DE DÜNYA ÖYLE İŞLEMEZ. YETENEK YALNIZCA BAŞLANGIÇTIR; EĞİTİM, ADANMIŞLIK, KARARLILIK GEREKİR. LİDER OLARAK KENDİ KARARINI VERMELİSİN. KARARLARINA SAYGI DUYARSAN BAŞKALARI DA DUYAR.",
["bm_msk_toon_02_desc"] = "NE ZAMAN BIRAKMAMAK GEREKTİĞİNİ BİLMEK, NE ZAMAN HAVLU ATACAĞINI BİLMEKTEN ZORDUR. KİBİR VEYA APTALCA GURUR SENİ YOLDAN ÇIKARMASIN. BAZEN BİR SORUNA ÖYLE KAPILIRSIN Kİ ASIL SORUNUN NE OLDUĞUNU GÖREMEZSİN. BU, HERKESİN BAŞINI BÜYÜK BELAYA SOKAR. ÇOK KÖTÜ BELAYA. O YÜZDEN DOĞRU OLANI YAP, YANLIŞ YOLA SAPMAZSIN.",
["bm_msk_toon_03_desc"] = "DÜNYADA BİR ŞEYİN YALNIZCA TEK ÖRNEĞİ KALDIĞINDA O ŞEY PAHA BİÇİLMEZ OLUR. NEYİ YAPABİLDİĞİNİ, BAŞKALARININ NEYİ DAHA İYİ YAPABİLDİĞİNİ BİL. İŞİ BİTİR. KISKANÇLIĞA KAPILMA; O KONUŞAN KORKUDUR. KORKU SENİ AŞAĞI ÇEKER. SEVGİDEN DOĞMAZ. BİRİNİ GERÇEKTEN SEVDİĞİNDE ONA GÜVENİRSİN. PAHA BİÇİLMEZ ŞEYLER YÜZÜNDEN KÖTÜLEŞMEYECEK KADAR GÜVENİRSİN.",
["bm_msk_toon_04_desc"] = "ŞU ANKİ DOSTLARIN, HAYATIN BOYUNCA İHTİYAÇ DUYACAĞIN BÜTÜN DOSTLARIN OLMAYABİLİR. YENİ DOSTLARI UZAK TUTARAK GELECEKTEKİ BİR KAZANCI KAÇIRMA. ÇÖLDE KAYBOLMAK KOLAYDIR; TEK YANLIŞ DÖNÜŞ YETER. KAYBOLDUĞUNDA O YENİ DOSTLAR BİR VAHAYA ÇIKIŞ BİLETİN OLABİLİR.",
["bm_msk_tormentor_desc"] = "BİR GÜLÜMSEME EN ÖLÜMCÜL DÜŞÜNCEYİ SAKLAYABİLİR AMA GÖZLER ASLA YALAN SÖYLEMEZ. BİRİNİ OKUMAK, ÇOĞUNLUKLA DOĞRUDAN GÖZLERİNE BAKMAKTIR. ASIL KORKUNÇ OLAN, DÜŞÜNCELERİ YÜZÜNE YANSIYAN İNSANLARDIR; BAKAN KİŞİ BİR SANİYE İÇİNDE ÇIĞLIĞINI BASTIRMAKTA ZORLANIR.",
["bm_msk_tounge_desc"] = "BU MASKE BİR ŞEKİLDE BİRBİRİNE ZIT VEYA ÇELİŞKİLİ DUYGULARI, İNANÇLARI VE GÜDÜLERİ AYNI ANDA ANLATIP YANSITIYOR.$NL;$NL;EFSANEYE GÖRE DÖRT YARATIK BİRLEŞEREK YÜZÜ BU MASKEYE BENZEYEN DAHA BÜYÜK BİR VARLIK OLUŞTURMUŞ.$NL;$NL;ÖZETLE, FENA HÂLDE KORKUTUCU BİR MASKE.",
["bm_msk_triceratops_desc"] = "TİMOTHY THE TRİCERATOPS, JURASSİC HİGH’IN EN POPÜLER DİNOZORLARINDAN BİRİ. AMA TEDDY THE TYRANNOSAURUS’A BÜYÜK BİR KİNİ VARDI. İRİ OLMALARINA VE DİNOZORLAR ÇAĞININ SON DÖNEMİNDE BİRLİKTE YAŞAMALARINA RAĞMEN BİR TÜRLÜ DOST OLAMADILAR. ÖZELLİKLE DE BAHAR TATİLİNDE KULÜBEYE GİTTİKLERİ O SEFERDEN SONRA. TEDDY VE ARKADAŞLARI, O KORKU FİLMİYLE VE GÖKTAŞININ ÇARPMASINA YEDİ GÜN KALDIĞINI SÖYLEYEN TELEFON ARAMASIYLA TİMOTHY’YE ŞAKA YAPMIŞTI. TİMOTHY BUNU HİÇ KOMİK BULMADI.",
["bm_msk_trik_tophatske_desc"] = "İYİ GİYİMLİ HER İSKELETİN GÖRÜNÜMÜNÜ TAMAMLAYACAK İYİ BİR ŞAPKAYA İHTİYACI VARDIR. KEMİKLER MODA, RENK DE SİYAH. EKİM AYI BOYUNCA 18. YÜZYIL TARZINDA SOYGUN YAP.$NL;$NL;YARATICI: LUKE MİLLANTA.",
["bm_msk_trik_tophatskeblue_desc"] = "KEYFİN Mİ YOK? BATAKLIK TARAFINDA SOYGUN İŞİN Mİ VAR? MAVİ DOĞRU SEÇİM. BU İSKELET SIRITIŞI ONLARI KAÇIRIRKEN SEN ORTADAKİ TÜM GANİMETİ ÇALARSIN!$NL;$NL;YAPIM: LUKE MİLLANTA.",
["bm_msk_trik_tophatskered_desc"] = "YENİ BİR GÖRKEMLİ SOYGUNA HAZIRLANIRKEN ETRAFINI KÜKREYEN, İBLİS ÖZENTİSİ PARTİ CANAVARLARI MI SARDI? BUNU TAK, SONRA DURUP ONLARA BAK. ÇOCUKLARIN DA POLİSLERİN DE ÖDÜNÜ KOPARACAĞI GARANTİLİ!$NL;$NL;YARATICI: LUKE MİLLANTA.",
["bm_msk_troll_desc"] = "İŞTE KÖPRÜ ALTINDA SAKLANMAKTAN BIKMIŞ BİR TROL.$NL;$NL;ONUN YERİNE NEDEN DÜNYAYI GÖRMESİN, KÖY YAĞMALAMASIN, HALKIN ALTIN HAZİNELERİNİ ALIP ÖFKELİ KALABALIKLARDAN KAÇMASIN?",
["bm_msk_tstp_daemon_desc"] = "MUHTEMELEN BİR YERLERDE BU MASKENİN ADINDAN ESİNLENMİŞ BİR ŞARKI VARDIR. O DÜZENLİ HECELER AKILDA KALAN BİR RİTİM OLUŞTURUYOR, DEĞİL Mİ?",
["bm_msk_tstp_dragon01_desc"] = "EJDERHALAR GÜLER Mİ? GERÇEKTEN Mİ? BAZILARI TERBİYELİ OLSA DA GENELDE HUYSUZ PİÇLERDİR. BİR DE BUNU TAKIP KOCAMAN BİR EL TOPUYLA SANA ATEŞ EDEN BİR SOYGUNCUNUN KARŞISINDA OLDUĞUNU DÜŞÜN.",
["bm_msk_tstp_dragon02_desc"] = "EJDERHA BAĞIRIYORSA KAPLAN KÜKRER Mİ? GENELLİKLE SOYGUNDA YÜKSEK SESLE KENDİNİ BELLİ ETMEK BAŞARIYA ZARAR VERİR. AMA BAZEN SIRF HAVALI OLDUĞU İÇİN AKIŞINA BIRAKMALISIN. O YÜZDEN HADİ... KENDİNİ ŞIMART.",
["bm_msk_tstp_godess_desc"] = "ETİKETİNDE, STRESLİYKEN VE KENDİNİ TOPARLAMAK İÇİN BİRAZ FENG SHUİ’YE İHTİYAÇ DUYDUĞUNDA HARİKA OLDUĞU YAZIYOR. AMA KÜÇÜK YAZIYI UNUTMA: \"ÜRETİCİ, KULLANIMINDAN, YANLIŞ KULLANIMINDAN VEYA BUNUN SONUCUNDA HAPSE GİRİLMESİNDEN SORUMLU DEĞİLDİR!\"",
["bm_msk_twitch_orc_desc"] = "KABA, SALDIRGAN VE GENEL OLARAK İTİCİ ORKLAR HER ZAMAN NEFRET EDİLEN BİR IRK OLMUŞTUR. GOBLİN KUZENLERİNDEN DAHA İRİ VE GÜÇLÜ, OGRE KARDEŞLERİNDEN İSE DAHA KÜÇÜK VE ZAYIFTIRLAR. BU MOR TENLİ ORK, VAHŞİ SAVAŞÇILARI VE AŞIRI GÜÇLÜ MELEZ ŞAMANLARIYLA TANINAN STONETREMBLE KLANINDAN GELMİŞTİR.",
["bm_msk_twitch_orc_desc_WIN32"] = "KABA, SALDIRGAN VE GENEL OLARAK İTİCİ ORKLAR HER ZAMAN NEFRET EDİLEN BİR IRK OLMUŞTUR. GOBLİN KUZENLERİNDEN DAHA İRİ VE GÜÇLÜ, OGRE KARDEŞLERİNDEN İSE DAHA KÜÇÜK VE ZAYIFTIRLAR. BU MOR TENLİ ORK, VAHŞİ SAVAŞÇILARI VE AŞIRI GÜÇLÜ MELEZ ŞAMANLARIYLA TANINAN STONETREMBLE KLANINDAN GELMİŞTİR.$NL;$NL;BU BİR HUMBLE BUNDLE E3 MASKESİDİR. PAYDAY SIRASINDA KAZANILAMAZ VE SATILAMAZ. BUNUN YERİNE ÜCRETSİZ OLARAK MASKE ZULANA GERİ KONABİLİR AMA YAPILAN ÖZELLEŞTİRMELER VE BUNLARA ÖDENEN ÜCRET KAYBOLUR.",
["bm_msk_unborn_desc"] = "BİR ZAMANLAR BÜYÜK BİR OYUNCU, İÇİNE ŞEYTANİ BİR RUH GİRDİĞİNİ İDDİA EDİP DEFORME OLMUŞ GÖRÜNÜMÜNÜ SAKLAMAK İÇİN MASKE TAKMAYA BAŞLADI. BİR GÜN MASKE KIRILDI; ALTINDA GİZLENEN ŞEY BİR DAHA ASLA HAPSEDİLEMEDİ.",
["bm_msk_unforsaken_desc"] = "BU EFSANEVİ MASKE, TOPLULUĞUMUZUN BAĞLILIĞINA, ANLAYIŞINA VE SÜREKLİ DESTEĞİNE MİNNETTARLIĞIMIZIN BİR GÖSTERGESİ. OVERKILL EKİBİ OLARAK SİZİ SELAMLIYORUZ.$NL;$NL;İYİ GÜNDE DE KÖTÜ GÜNDE DE MİĞFERLERİ UÇURMAYA DEVAM.",
["bm_msk_unic_desc"] = "TAK TAK, KİM O? UNİC! NEW RUSH CİTY’NİN KARANLIK SOKAKLARINDA İÇTEN BİR GÜLÜMSEMEDEN DAHA PARLAK NE OLABİLİR? ÇAYIRLARDA DÖRT NALA KOŞUP ARKADAŞLARIYLA VAKİT GEÇİREN UNİC, DÜNYANIN GÜZEL YANLARINI GÖSTERMEYE KENDİNİ ADAMIŞ. PEMBE MAYOSU VE MOR ÇİZMELERİ BU HIZLI KOŞUCUYU GERÇEKTEN EŞSİZ KILIYOR!",
["bm_msk_unicorn_desc"] = "PETER GERÇEK BİR EFSANEDİR; HEM DE SANKİ EZELDEN BERİ. ALNINDAN UZUN, SİVRİ, SARMAL BİR BOYNUZ ÇIKAN BU YARATIĞI BÜTÜN İNSANLIK, GÖKKUŞAĞINA DOKUNMAK İSTEDİĞİNDE GİDİLECEK KİŞİ OLARAK TANIR. HAYIR, DOKUN. O LANET GÖKKUŞAĞINA DOKUN. ŞİMDİ TADINA BAK.$NL;$NL;ŞŞŞ. SORUN YOK. İYİ YAPTIN.",
["bm_msk_uno_01_desc"] = "CESEDİ KIYAFETLERİYLE BİRLİKTE YAKMANI SÖYLÜYORLAR. İZ BIRAKMA. FIRINA ATIYORSUN. EN YÜKSEK ISI. HİÇBİR ŞEY KALMAYACAK... GÖZLÜK HARİÇ. ONU NEDEN SAKLADIĞINDAN EMİN DEĞİLSİN. DÜRTÜSEL DEĞİLSİN, GENELLİKLE HATIRA ALMAZSIN. AMA BUNDAN FAZLASI VAR, DEĞİL Mİ? BİR ADAM BU CAMLARDAN SUÇLA SİYASETİN, SADAKATLE İHANETİN DÜNYASINI GÖRDÜ VE HEPSİNİ KENDİ LEHİNE BÜKMEYİ ÖĞRENDİ.$NL;BU GÖZLÜĞÜN SAHİBİ, EN ÇILGIN HAYALİNİN ÖTESİNDE BİR KOMPLO ÖRDÜ. BELKİ YANINDA TUTARSAN ONUN GÖRDÜĞÜNÜ GÖREBİLİRSİN.",
["bm_msk_vampire_desc"] = "VAMPİR, YAŞAYANLARIN KANIYLA BESLENDİĞİ SÖYLENEN MİTOLOJİK BİR YARATIKTIR; YAŞAYAN ÖLÜLERDENDİR.$NL;$NL;VAMPİRLER NORMAL İNSAN GİBİ GÖRÜNEBİLİR.$NL;$NL;SALDIRIYA UĞRADIKLARINDA YÜZLERİ DEĞİŞİR, UZUN VE SİVRİ DİŞLERİ ÇIKAR; VAMPİR ÇEHRELERİ ORTAYA ÇIKAR.",
["bm_msk_velociraptor_desc"] = "VİNCENT THE VELOCİRAPTOR VE EN İYİ DOSTU PROTOCERATOPS ANDREAS HÄLL PENNİNGER, BİR GÜN ORMANDA DOLAŞIRKEN KAVGA ETTİ. ASLINDA BÜYÜK BİR MESELE DEĞİLDİ AMA VİNCENT PEŞİNİ BIRAKMADI. İNATÇI PROTOCERATOPS ANDREAS DA VİNCENT’A LAF ATMAYI SÜRDÜRDÜ. ŞİDDETLİ BİR DÖVÜŞ ÇIKTI; BUGÜN BİLE KİMİN KAZANDIĞI BİLİNMİYOR.",
["bm_msk_venomorph_desc"] = "VENOMORPH’U GÖRDÜĞÜNDE OYUNUN BİTTİĞİNİ BİLİRSİN DOSTUM. OYUN BİTTİ!$NL;BELKİ ATEŞ YAKIP BİRKAÇ ŞARKI SÖYLEMEYİ DENEYEBİLİRSİN.$NL;$NL;ASLINDA GERİ DÖNÜP SAKLANSAN İYİ OLUR. YAKINDA KARANLIK OLACAK VE BU YAVRULAR ÇOĞUNLUKLA YALNIZCA GECELERİ ÇIKAR... ÇOĞUNLUKLA.",
["bm_msk_viking_desc"] = "VİKİNG GEMİLERİNİN PRUVASINA TAKILAN EJDERHA BAŞI, DENİZ CANAVARLARINI VE KÖTÜ RUHLARI KORKUTMAK İÇİN KULLANILIRDI. BULLDOZER’LAR VE CLOAKER’LAR KÖTÜ, DEĞİL Mİ? İŞE YARAYIP YARAMADIĞINI NEDEN DENEMEYESİN? AMA NE OLUR NE OLMAZ SİLAHIN HAZIR OLSUN. GÜVENLİK İÇİN.",
