["bm_msk_vlad_armor_desc"] = "\"HEY! PAYDAY PALYAÇOLARI! VLAD BURADA, ANA VATAN’DAN UFAK BİR ŞEY GETİRDİ. DONETSK’TEKİ BÜTÜN GÜNLERİMDE BU GÜZEL, AĞIR MERETİ TAKTIM. SİZİN NARİN AMERİKAN MASKELERİNİZ GİBİ GÜZEL DEĞİL AMA BENİ KORUDU!\"",
["bm_msk_volt_desc"] = "MERAKLI BİR AŞAĞILIK OLAN HADEME DAVİD DAVİDSON, ÇALIŞTIĞI ASKERÎ ARAŞTIRMA TESİSİNDE ÇALMASI KOLAY BİR ŞEY ARAYARAK GİZLİCE DOLANIYORDU. ANAHTARININ OLMADIĞI BİR KAPI BULDU. MERAKINA YENİLİP KAPIYI TEKMELEYEREK AÇTI VE BİR TÜR PARLAK IŞIĞIN SALDIRISINA UĞRADI. BİR ŞEKİLDE HAYATTA KALDI, İNSANÜSTÜ GÜÇLER KAZANDI.$NL;$NL;YENİ GÜÇLERİYLE KENDİNE VOLT ADINI VERDİ.",
["bm_msk_war_desc"] = "MAHŞERİN İKİNCİ ATLISI SAVAŞ’TIR; İNSANLIĞIN ŞİDDET DOLU RUHUDUR. SAVAŞ, İNSANLARIN DOĞUŞTAN VAHŞİ OLDUĞUNA, DÖVÜŞMEK VEYA ÖLDÜRMEK İÇİN GERÇEK BİR NEDENE İHTİYAÇ DUYMADIKLARINA İNANIR. ATEŞ KIRMIZISI BİR ATA BİNERDİ; GİTTİĞİ HER YERDE KAN AKACAĞINI ANLATIYORDU.",
["bm_msk_washington_desc"] = "ORDULAR GENERALİ, BAŞKOMUTAN, KURUCU BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETTİ.$NL;$NL;İLK BAŞKAN; HEM DE BÜYÜK BİR BAŞKAN.$NL;$NL;1. BAŞKAN, TARİHİN EN SEVİLEN BAŞKANLARINDAN BİRİYDİ VE 1 $ BANKNOTUN ÜZERİNDEKİ YÜZDÜ. SUÇLULAR ARASINDA HÂLÂ SON DERECE POPÜLER.",
["bm_msk_wasp_desc"] = "İKİ ÇİFT KANAT, BİR YUMURTA BORUSU VEYA İĞNE, KALIN TÜYLERDEN YOKSUN BİR BEDEN VE BİR ÇİFT PENÇE. İŞTE SANA YABAN ARISI. NEREDEYSE HER ZARARLI BÖCEK TÜRÜNÜ AVLAYAN VEYA ONA ASALAKLIK EDEN EN AZ BİR YABAN ARISI TÜRÜ VAR. BU DA SAYILARINI DOĞAL YOLDAN DENETLEMEDE YABAN ARILARINI ÇOK ÖNEMLİ KILIYOR.",
["bm_msk_water_spirit_desc"] = "TANE’NİN KARDEŞİ TAWHİRİ, HAVANIN, ÖZELLİKLE DE ŞİDDETLİ FIRTINALARIN VE ŞİMŞEKLERİN TANRISIDIR. BODHI İKİSİNDEN DE BOLCA NASİBİNİ ALDI. TUVALU’DA RESİF DALIŞI SIRASINDA YAŞANAN ÖZELLİKLE ŞİDDETLİ BİR PATLAMA, BODHI’NİN BU GÜÇLÜ TANRININ KIYMETİNİ GERÇEKTEN ANLAMASINI SAĞLADI.",
["bm_msk_wayfarer_desc"] = "BU GÖZLÜK BEŞ YABANCIYA AİTTİ. JOHN, KUSURSUZ SUÇU İŞLEMEYE HAZIRLANAN BİR GRUP İNSANI ÖLDÜRMEK İÇİN TUTULMUŞTU. HEPSİ AYNI GİYİNİYOR, KOD ADLARI KULLANIYORDU; BU YÜZDEN TANIMALARI KOLAYDI.$NL;$NL;AMA JOHN OLAY YERİNE ÇOK GEÇ GELDİ. POLİS ÇOKTAN ORADAYDI. GİTMEDEN ÖNCE YABANCILARIN HEPSİNİN ÖLDÜĞÜNDEN EMİN OLDU.",
["bm_msk_waytexase_desc"] = "DAYANIKLI OL. GURURLU OL. İNATÇI OL. DOST CANLISI OL. ALTIPATLARLA ÇOK İYİ NİŞAN AL.$NL;EN ÇOK DA SONUNCUSU.",
["bm_msk_welder_desc"] = "GERÇEKTEN EFSANEVİ BİR İNFAZCI MASKESİ.$NL;$NL;SÖYLENTİYE GÖRE YILLAR ÖNCE PİNK PANTHER EKİBİNİN EN İYİ TETİKÇİLERİNDEN BİRİ İÇİN YAPILMIŞ AMA TAKMAYA CESARET EDEMEMİŞ. FAZLA DİKKAT ÇEKERMİŞ.$NL;$NL;SENİN DERDİN DEĞİL.$NL;$NL;BU MASKE, KÖTÜ ŞÖHRET AĞACI ÖDÜLÜDÜR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_white_wolf_desc"] = "DENNİS BIÇAKLARI SEVER.$NL;$NL;BOZKURT, GEZEGENDEKİ EN İYİ BİLİNEN VE EN ÇOK ARAŞTIRILAN HAYVANLARDAN BİRİDİR. İNSANLARIN EVCİLLEŞTİRDİĞİ İLK HAYVAN VE TEK BÜYÜK ETOBURDUR.$NL;$NL;BUGÜN İNSANLARIN ZULMÜ YÜZÜNDEN NÜFUSUNUN YALNIZCA ÜÇTE BİRİ KALDI.",
["bm_msk_witch_desc"] = "CADI, ÇOĞU ZAMAN BİR ŞEYTANIN VEYA YARDIMCI RUHUN DESTEĞİYLE KARA BÜYÜ YAPAN KİŞİDİR.$NL;$NL;ÇİRKİN YAŞLI BİR ACUZEDEN ÇEKİCİ BİR KADINA KADAR HER ŞEY OLABİLİR.$NL;$NL;SONRA SÜPÜRGESİ, ŞAPKASI FALAN VAR. BÖ!",
["bm_msk_wmp_01_desc"] = "KRALİYET HAVA KUVVETLERİ’NDEN BİR PİLOT, 2. DÜNYA SAVAŞI SIRASINDA POLONYA’NIN BİALYSTOK ŞEHRİNİN BİRKAÇ MİL DIŞINDA DÜŞTÜ. ÇATIŞMADA ÖLDÜĞÜ SANILIYORDU AMA YILLAR SONRA BİALOWİEZA ORMANI’NIN DERİNLİKLERİNDE BULUNDU. BALIK, KÖK VE YAKALAYABİLDİĞİ HAYVANLARLA HAYATTA KALMIŞTI. SAĞDI, SAĞLIKLIYDI AMA DELİLİK PENÇELERİNİ ONA GEÇİRMİŞTİ. SOL BACAĞINI KESMEK ZORUNDA KALMIŞTI. YİNE DE ENFEKSİYON KAPMADAN YAŞAMAYI BAŞARMIŞTI. UÇAĞINDAN KURTARDIĞI PARÇALARLA BİRLİKTE KÜÇÜK BİR KULÜBE DE BULUNDU. BULUNDUĞUNDA YIL 1978’Dİ.",
["bm_msk_wmp_02_desc"] = "KÜÇÜK POMTSBURG KÖYÜNDE KÜÇÜK BİR ANIT BULUNUR. YOSUN TUTMUŞ LEVHAYI PEK AZ KİŞİ OKUR AMA ÜZERİNDE GENÇ BİR ÇOCUĞUN HİKÂYESİ YAZILIDIR. ALMANLAR POMTSBURG’A YÜRÜDÜĞÜNDE DİRENİŞE CESARETLE VE KARARLILIKLA ÖNDERLİK ETTİ. POMTSBURG ONUN DOĞDUĞU YERDİ VE KİMSE ONU YOK EDEMEYECEKTİ. POMTSBURG SAVAŞI TARİH KİTAPLARINA HİÇ GİRMEDİ; NASIL BİTTİĞİNİ BİLE PEK AZ KİŞİ HATIRLIYOR. AMA ÇOCUK BU HATIRAYI ÇALMAYI BAŞARDI. ONA VE BAŞKALARINA ZULME HER ZAMAN KARŞI DURMAK GEREKTİĞİNİ HATIRLATACAK BİR ŞEY.",
["bm_msk_wmp_03_desc"] = "BU PİLOTKA, ALMANYA’DAKİ MÜRİTZ GÖLÜ YAKININDA BİR CESEDİN ÜZERİNDE BULUNDU. ZAVALLI ÖLÜ ASKERİN BAŞINA İPLE BAĞLANMIŞTI. ADSIZ ADAMIN YANINDA BAŞKA CESET YOKTU. PİLOTKA RUS YAPIMI OLDUĞUNDAN ONUN DA AYNI ÜLKEDEN GELDİĞİ VARSAYILABİLİR. PEK ÇOK TAHMİN VARDI, HİÇBİRİ DOĞRU DEĞİLDİ. AMA EN İLHAM VERİCİ HİKÂYE, VATANIYLA ÖYLESİNE GURUR DUYAN BİR ASKERİN ÖLMEDEN ÖNCE PİLOTKASINI BAŞINA BAĞLAMASIYDI.",
["bm_msk_wmp_04_desc"] = "BU EŞYA 1990’LARDA KUZEY FRANSA’DAKİ BİR AÇIK ARTIRMADA ORTAYA ÇIKTI. KATILANLAR ARASINDA ELLİLİ YAŞLARINDA BİR KADIN VARDI. ONU TANIDI; TAKAN SUBAYIN ADINI HATIRLAMASA DA YÜKLÜ BİR PARA ÖDEDİ. GENÇ BİR KIZKEN SEBZE ALMAK İÇİN MEYDANA GİTMİŞTİ. DERKEN PARAŞÜTÇÜLER İNMEYE BAŞLADI. SİLAH SESLERİ, PATLAMALAR, KORKU VE ACI ÇIĞLIKLARI HAVAYI DOLDURDU. SUBAY ONU BİR DEVLET BİNASINDAKİ SIĞINAĞA GÖTÜRDÜ. ONU KURTARMAK İÇİN İYİLİKTEN BAŞKA NEDENİ YOKTU. AMA KENDİ CANI TEHLİKEDEYKEN BİLE ONUN CANINI KURTARMAK İÇİN RİSKE GİRDİ. KADIN O ZAMAN KÜÇÜCÜK BİR KIZDI AMA ŞAPKAYI YİNE DE TANIDI.",
["bm_msk_wolf_clean_desc"] = "BU, İKONİK WOLF MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_wolf_desc"] = "WOLF’UN MASKESİ.",
["bm_msk_wolf_glow_desc"] = "MEGA WOLF MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_xm20_dog_desc"] = "BU MASKENİN YANINDA, YAPIMCISI EDUARDO MAQUEVERA’NIN EL YAZISIYLA YAZDIĞI BİR MEKTUP VARDI. MASKENİN İLHAMINI, ORMANDA YOLCULUK EDERKEN YAŞADIĞI VE KARŞILAŞTIĞI HAYVANLARIN KENDİSİYLE KONUŞTUĞU BİR PEYOTE RÜYASINDAN ALDIĞINI ANLATIYORDU.",
["bm_msk_xm20_jaguar_desc"] = "BULUC’UN ADAMLARI BU MASKEYİ YAPMAK İÇİN GERÇEK LEOPAR DERİSİ KULLANILMASINI İSTEDİ AMA USTA MASKE YAPIMCISI EDUARDO MAQUEVERA ONUN YERİNE SAHTESİNİ YAPMAK İÇİN FAZLADAN UĞRAŞTI. ARADAKİ FARKI HİÇ ANLAMADILAR!",
["bm_msk_xm20_mega_max_desc"] = "SARHOŞ HİKÂYESİNE GÖRE TANRILARIN KENDİLERİ XİBALBA’DA BİR ARAYA GELİP BU MASKEYİ DÖVDÜ. 1000 SAVAŞÇININ KANINDA SERTLEŞTİRİLDİ, 1000 BAKİRENİN GÖZYAŞINDAN YAPILAN TEKİLAYLA ARINDIRILDI. SANGRES BÖYLE DİYOR. ONUNLA KİM TARTIŞACAK?$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_xm20_msq_01_desc"] = "MUCHO MİKE BU MASKEYİ BULUC’UN 40. DOĞUM GÜNÜ İÇİN KARABORSADAN ALDI. SETİNİ TAMAMLAMAK İÇİN GEREKEN SON MASKEYDİ. BULUC, NADİR GÖRÜLEN İÇTEN BİR MİNNETTARLIK ANINDA MİKE’A TERFİ VERDİ; ONU DÖRDÜNCÜ KİŞİSEL KORUMASI VE SIRDAŞI YAPTI.",
["bm_msk_xm20_msq_02_desc"] = "BU MASKE, AİLESİNDE NESİLLERDİR SAKLANAN YAŞLI BİR ÇİFTÇİDE BULUNDU. ADAM SATMAYI REDDEDİNCE BULUC’UN ADAMLARI BÜYÜK BİR ZALİMLİKLE ÇİFTLİĞİNİ VE GEÇİM KAYNAĞINI YAKIP ONU MECBUR BIRAKTI. UMARIZ BU TARİHÎ ESERİN GELECEKTEKİ SAHİPLERİNİN TALİHİ DAHA İYİ OLUR VE DAHA AZ BARBARCA DAVRANIRLAR.",
["bm_msk_xm20_msq_03_desc"] = "BU, BULUC’UN MASKE KOLEKSİYONUNDA MAYA KÖKENLİ SU ALTI HARABESİNDEN ÇIKARILAN İKİNCİ MASKE. O DA AĞIR BEDELLERLE BULUNDU; ONU GETİREN KEŞİF EKİBİNİN TEK SAĞ KALANI, LANETLİ OLDUĞUNU SÖYLÜYOR. BULUC BU TÜR DÜŞÜNCELERİ DE EMRİNDEKİ İNSANLARIN KAYBINI DA UMURSAMIYOR. ONU GETİRMEK İÇİN KULLANILAN KÜÇÜK AHŞAP TEKNENİN ENKAZI, BULUC’UN MALİKANESİ YAKININDAKİ BİR KUMSALDA ÇÜRÜYOR.",
["bm_msk_xm20_msq_04_desc"] = "BULUC’UN ADAMLARI, KOLEKSİYONUNA DEĞERLİ KALINTILAR ARARKEN MEKSİKA KIYISI AÇIKLARINDAKİ BİR SU ALTI MAYA HARABESİNE DALIP BU MASKEYİ BULDU. SÖYLENTİYE GÖRE TEKNEDEKİ ADAMI RAUL DALGIÇLARI ÖYLESİNE ZORLADI Kİ BİRKAÇI ÖLDÜ.",
["bm_msk_xm20_owl_desc"] = "BU MASKENİN İÇİNDE İMZA YOK. DEMEK Kİ EDUARDO MAQUEVERA’NIN KENDİSİ DEĞİL, ÇIRAKLARINDAN BİRİ YAPMIŞ.",
["bm_msk_xm20_serpent_desc"] = "BU MASKEYİ USTA MASKE YAPIMCISI EDUARDO MAQUEVERA, SAN DİEGO’DAKİ ATÖLYESİNDE YAPTI. GERÇEKTEN ÜNLÜ BİR ZANAATKÂR OLARAK FİLM SEKTÖRÜNÜN BÜYÜK BÖLÜMÜNE MASKE VE AKSESUAR SAĞLIYOR.",
["bm_msk_yor_desc"] = "GÜVENİLİR BİR KUNDAKÇISIN; HEP DAKİK, HEP HEDEFTE. YENİ YIL BAŞLARKEN GÖZÜNÜ EN SOYLU METAL OLAN O PARILDAYAN ALTINA DİKECEKSİN. NİYETLERİN KARANLIK OLABİLİR AMA YEDİ MUHTEŞEMDİR VE DAHA FARKINA VARMADAN KUSURSUZ SOYGUNU KUTLAMAK İÇİN ÇAK YAPIYOR OLACAKSIN. BELKİ SONUNDA O SEKİZ NUMARALI BİLARDO TOPU DÖVMESİNİ DE YAPTIRIRSIN.",
["bm_msk_yufuhelmet_desc"] = "WANG GERÇEKTEN DE ATEŞ PÜSKÜRTEN ZORLU BİR DÜŞMANDI. MOUNTAIN MASTER’IN ELDE DÖVÜLMÜŞ BU TACI, ZAFERİNİN ETKİLEYİCİ BİR SİMGESİ OLACAK.",
["bm_msk_zipper_desc"] = "FERMUAR MASKESİ, ARALARINDAKİ SÜRGÜ ÇEKİLEREK BİRBİRİNE GEÇİRİLEBİLEN VEYA AYRILABİLEN İKİ PARALEL DİŞ DİZİSİNDEN OLUŞUR.$NL;$NL;İLETİŞİM KURMAN GEREKTİĞİNDE FERMUARI AÇ.",
["bm_msk_zombie_desc"] = "ZOMBİ, BİR ŞEKİLDE YENİDEN CANLANMIŞ HAREKETLİ BİR CESETTİR.$NL;$NL;BEYİN?",
["bm_msk_ztm_desc"] = "BU MASKE BAZILARINA DEHŞET, BAZILARINA HAYRANLIK VERECEK. BU BAŞLIĞI TAKMAK İÇİN EŞİT ÖLÇÜDE SAKİNLİĞE VE KAOSA SAHİP OLMALISIN; SUÇ ÇEVRELERİNDE NADİREN GÖRÜLEN BİÇİMDE BİR ARAYA GELEN İKİ UÇ.$NL;$NL;THE ALMIR, PEK ÇOK KİŞİNİN BİR EKİBE SALMAYA ÇEKİNECEĞİ BİR MASKE. ONU TAKACAK KADAR ÇILGIN BİRİ BİR GÜN BÜYÜK İŞLER BAŞARABİLİR, ERTESİ GÜNSE PSİKOTİK BİR KATLİAMA GİRİŞEBİLİR. AMA BAZEN ZOR DURUMDAN ÇIKIP SOYGUNU TAMAMEN BATIRMAMAK İÇİN BÖYLE BİRİNE İHTİYACIN OLUR.$NL;$NL;BÖYLE BİRİNİN BAŞARI GETİRME ŞANSI KADAR BAŞARISIZLIK GETİRME ŞANSI OLDUĞUNU BİLEREK, EKİBİNE BİR ALMIR ALMAYA CESARET EDER MİSİN?$NL; ;)",
["bm_msl_sds_01_desc"] = "GÖZLERİN YAŞARANA KADAR ÖDÜLÜNE KİLİTLENİYORSUN. SAHİP OLMA İHTİYACI BENLİĞİNİ ELE GEÇİRİRKEN GEVŞEMİŞ ÇENENDEN YERE BİR DAMLA SALYA DÜŞÜYOR. ÖZLEDİĞİN KİŞİ BİR NESNE, NESNE BİR KİŞİ. KÖRLEŞMİŞ DUYULARIN İÇİN HİÇ FARK ETMİYOR.",
["bm_msl_sds_02_desc"] = "NE DİYE UĞRAŞASIN? EVREN GENİŞLESİN, ÖLSÜN, KARARSIN. EN UFAK ÇABA GÖSTERMEN GEREKEN HER ANLAMSIZ ANGARYAYI PROTESTO ETMEK İÇİN PARMAĞINI KIPIRDATMAYA SONSUZ ZAMANIN VAR. SEN SÜREKLİ HIRSTAN YOKSUN KALIRKEN YAŞAM ENERJİN RUHUNDAN SIZIP BOŞLUKTA ERİYEREK ZİYAN OLUYOR.",
["bm_msl_sds_03_desc"] = "HAKSIZLIK, DEĞİL Mİ? HAYATTAKİ HER ŞEYİ HAK ETMİŞ HÂLDE ORADA DURUYORSUN AMA EVREN SANA VERMEYİ REDDEDİYOR. BAŞKALARI GÜLÜP OYNARKEN SEN İÇİNE KAPANIYOR, HERKESE BEDAVADAN VERİLEN BAŞARIYI NEDEN KİMSENİN SANA ARMAĞAN ETMEDİĞİNİ DÜŞÜNÜYORSUN. AH, ÖYLE ÇOK İSTİYORSUN Kİ; AMA ALMAYA NASIL CESARET EDEBİLİRSİN?",
["bm_msl_sds_04_desc"] = "KALBİNDE SOĞUK BİR ATEŞ VAR. SANA HAKSIZLIK EDEN HERKES BEDEL ÖDEYECEK. YANGINDA ONLARLA BİRLİKTE YANMAN GEREKSE BİLE SANA YAPILMIŞ GERÇEK YA DA HAYALÎ HER HAKARETİN HESABINI SORACAKSIN. ÖFKENİN MANTIĞI YOK; SADECE DOYURULMALI.",
["bm_msl_sds_05_desc"] = "SEN KIRILMAZSIN. GEMİ SU ALIYOR AMA KIPIRDAMAYI REDDEDİYORSUN. İLKELERİN ÖYLE SAĞLAM Kİ HATANI VE HERKES KADAR YANILABİLİR OLDUĞUNU KABUL ETMEK YERİNE ÇÖKEN BİR KURUMLA DERİNLERE İNMEYİ SEÇİYORSUN. ADALET SENİN TANIMLADIĞIN ŞEYDİR; HAKLI BİLGELİĞİNE KARŞI GELENLERE DE LANET OLSUN.",
["bm_msl_sds_06_desc"] = "İŞTE YİNE O BİTMEK BİLMEYEN, SÜREKLİ AÇLIKTAN ÖLÜYORMUŞÇASINA VAHŞİ BİR HIRSLA TIKINIP KARNINI DOYURMA İHTİYACI. DURDUĞUNDAYSA MİDENDE DOYURULMAYI BEKLEYEN KOCA BİR BOŞLUK AÇILIYOR SANKİ.",
["bm_msl_sds_07_desc"] = "DAHA FAZLASI ASLA YETMEZ. HİÇBİR ALTIN VEYA HAZİNE MİKTARI SENİ DOYURAMAZ. TEK AMAÇ, İSTER MADDİ İSTER MANEVİ OLSUN, ŞİŞKİN SANDIKLARINA EKLEYECEĞİN BİR SONRAKİ GEREKSİZ SERVET YIĞININI ELDE ETMEKTİR. ACILARINDAN KAZANÇ SAĞLAYABİLİYORSAN BAŞKALARININ ÇİLESİNİN ÖNEMİ YOKTUR.",
