["bm_mtl_wicker1"] = "HASIR",
["bm_paycheck_chains_desc"] = "PAYCHECK CHAINS KAFAYI TAMAMEN SIYIRMAK İSTİYOR. AMA DOĞRUSU, MASKENİN ARDINDA AHLAKSIZ YOLLARDAN GEÇİNMEYE ÇALIŞAN SIRADAN BİR ADAM VAR. SIRADANLIĞINI DELİLİĞE ÇEVİRMEK İÇİN, BİR SOYGUNDA POLİS GELİNCE BİR KANİŞİ REHİN ALDI. BUNU ANCAK BİR DELİ YAPAR, ÖYLE DEĞİL Mİ? AMA BULAŞMAK İÇİN YANLIŞ AZGIN İTİ SEÇMİŞTİ. EKİP BU YARATIKTAN KAÇMAYI BAŞARANA KADAR KÖPEK HEPSİNİ ISIRDI. SOYGUNUN ARDINDAN ÇIKAN HABERLERDE KÖPEĞİN KUDUZ BELİRTİLERİ GÖSTERDİĞİ SÖYLENDİ. BELKİ DE PAYCHECK CHAINS SONUNDA OLMAK İSTEDİĞİ KADAR DELİRİR...",
["bm_paycheck_dallas_desc"] = "PAYCHECK DALLAS SONUNDA GİZLENMEK İÇİN SİYAH ÇÖP POŞETİ KULLANMAKTAN VAZGEÇTİ. CESARETİNİ TOPLAYIP İDOLÜNÜ ONURLANDIRMAK İÇİN GERÇEK BİR DALLAS MASKESİ SİPARİŞ ETTİ AMA İNTERNETTEKİ BASKI HİZMETİNİN GÖNDERDİĞİ ŞEY PEK ASLINA BENZEMİYORDU... YİNE DE MASKESİYLE İŞİ BÜYÜTMEYE ÇALIŞTI VE PAYCHECK ÇETESİNİ BİR PORSELENCİ DÜKKÂNINI BASMAYA İKNA ETTİ. GÜVENLİK KAMERASI GÖRÜNTÜLERİNDE PAYCHECK DALLAS’IN İÇERİ DALARKEN EN BÜYÜK VAZOYU YANLIŞLIKLA KIRDIĞI GÖRÜLÜYOR. BUNUN ÜZERİNE DÜKKÂN SAHİBİNDEN ÖZÜR DİLEYİP KASADAKİ BÜTÜN BOZUKLUKLARI KAPTI VE KAPIYA KOŞTU. O SIRITAN NEON MASKENİN ALTINDA MUHTEMELEN DOMATES GİBİ KIZARMIŞTI.",
["bm_sad_seal_desc"] = "BİR BULLDOZER’IN İŞİNİ BİTİRMEK ÜZEREYKEN TETİĞİ ÇEKİP MÜHİMMATININ BİTTİĞİNİ FARK ETTİĞİN O AN. YA DA SON ÇANTAYI DOĞRUCA DENİZE ATTIĞIN AN. YA DA HİÇ UĞRAŞMADIĞIN MASKENE DİĞER SOYGUNCULARIN İLTİFAT ETTİĞİ AN. YA DA SENİNLE AYNI ANDA BİRİNİN MATKABI ONARDIĞI AN.",
["bm_sfm_01_desc"] = "SOĞUK VE KIPIRTISIZ, ONLARI YUKARIDAN İZLİYORSUN. ALTIN BAKIŞIN O ZAVALLI YUMUŞAKLARIN ÜZERİNE HAK ETMEDİKLERİ BİR LÜTUF GİBİ DÜŞTÜĞÜNDE İHTİŞAMINI KISKANACAKLAR. GECENİN SERT SOĞUĞUYLA GÜNEŞİN GÖZ KAMAŞTIRAN IŞILTISINI BİRLEŞTİRİYORSUN. GÖRKEMLİ, ALTIN VE GÜZEL; ARZUYLA AKILLARINI BAŞLARINDAN ALACAK, SONLARINI GETİRECEKSİN.",
["bm_sfm_02_desc"] = "TİMOTHY MİLLER BÜYÜYÜNCE SİNEMA IŞIKLANDIRMASINDA ÇALIŞMAYI HAYAL EDİYORDU. BİR CADILAR BAYRAMI PARTİSİ İÇİN GOLDEN HOUR MASKESİNİ YAPTI. AMA TAKIP AYNAYA BAKTIĞINDA GÖZLERİ, GÜN BATIMININ KUSURSUZ YUMUŞAK KIRMIZI PARILTISIYLA ÇEVRİLİYDİ. O AN YENİ BİR HAYAL DOĞDU. İNSANLARIN GÜN BATIMININ HUZURUNU YAKINDAN GÖRMESİNİ, SONSUZA DEK RETİNALARINA KAZINMASINI İSTEDİ. ADLİ TABİBİN DOĞRULAYABİLDİĞİ TEK ŞEY, TÜM KURBANLARIN GÜN BATIMINDAN AZ ÖNCE ÖLDÜĞÜ VE GÖZLERİNİN DAİMA AÇIK BIRAKILDIĞIYDI.",
["bm_sfm_03_desc"] = "CHAD’İN BARRORI FLEX GÜNEŞ GÖZLÜĞÜNÜ ALDIĞI GÜN HER ŞEY DEĞİŞTİ. HAYATTA NEYİN ÖNEMLİ OLDUĞUNA YEPYENİ BİR AÇIDAN BAKMASINI SAĞLADI. HAVALI VE UMURSAMAZ GÖRÜNMEK AMACI, YAŞAMA NEDENİ OLDU. İTALYAN SPOR CEKETİ, BEJ KETEN PANTOLONU VE MOKASENLERİYLE GİTTİĞİ HER YERDE KISKANÇ BAKIŞLAR TOPLUYOR, BAŞLARI DÖNDÜRÜYORDU. AMA BU SÜREMEZDİ. CHAD’İN GÜZELLİĞİ SOLUNCA YAŞAMA İSTEĞİ DE SOLDU. EN İYİ KIYAFETLERİYLE BİR KUTU DİYET HAPINI YUTTUĞUNDA İYİ GÖRÜNÜMLÜ BİR CESET OLDU.",
["bm_sfm_04_desc"] = "KAPLANIN ÖFKESİ DİLLERE DESTANDIR; ORMANIN KRALI KENDİ İSTEĞİYLE TUTSAK OLMAZ. SENİ DENETİM ALTINDA TUTTUKLARINI SANABİLİRLER AMA KAFESE KAPATILMIŞ BİR KAPLANIN HİDDETİNE HİÇBİR ŞEY BENZEMEZ. ZİNCİRLERİNİ KIRDIĞINDA BUNU ANLAYACAKLAR. KRALLIĞINI GERİ ALIRKEN PENÇELER PARÇALAYACAK, DİŞLER ETİ KEMİKTEN AYIRACAK.",
["bm_sha_01_desc"] = "KUDRETLİ BOYNUZLU İBLİS. İNTİKAMCI, AĞLAYAN YOK EDİCİ. ONU ÖFKELENDİRME.",
["bm_sha_02_desc"] = "HIZLI VUR, SERT VUR, SESSİZ VUR. CLOAKER’LARI BİLE UTANÇ İÇİNDE SURAT ASAR HÂLDE BIRAKACAKSIN.",
["bm_sha_03_desc"] = "SALDIRGAN, ACIMASIZ, HER YANI SARAN BİR TEHDİDE DÖNÜŞ. ŞEHRE GİRDİĞİNDE ÖLÜM SENİ ATEŞ BİÇİMİNDE İZLER.",
["bm_sha_04_desc"] = "BIÇAKLARI HAVADA UÇURAN HIZLI VE ÇEVİK BİR KATİL. HER AN VURMAYA HAZIR. ÇOK HAYRANI OLAN POPÜLER BİR KATİL.",
["bm_sm_wish_desc"] = "İBLİS! İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. BU ARTIK KESİNLİKLE İNSAN KAFATASI DEĞİL. İYİ OLMAK İÇİN ŞEYTANİ GÜÇLERİNİ ÇAĞIRDIĞINDA BÖYLE OLUR.$NL;$NL;BİZ OVERKILL OLARAK ŞAŞKINIZ, AFALLADIK VE GERÇEKTEN ETKİLENDİK. BAŞARDIN. VAZGEÇMEYİP DÜŞÜNEBİLDİĞİMİZ EN ZOR ZORLUĞU GERÇEKTEN TAMAMLAYAN AZ SAYIDA KİŞİDEN BİRİSİN. SAVAŞTIN, ACI ÇEKTİN VE DİRENDİN. SONSUZ SAYGIMIZ SENİNLE, İBLİSLERİN HÜKÜMDARI.",
["bm_sparkle_party_desc"] = "PARTİ ŞAPKALARININ MODASI GEÇMEZ. İSTER SUÇ DOLU BİR ŞENLİK İSTER YENİ EVE TAŞINMA KUTLAMASI OLSUN, EĞLENCELİ HER ETKİNLİĞİN VAZGEÇİLMEZ AKSESUARIDIR. BİRİNİ TAK, KRAVATINI GEVŞET. PARTİ ZAMANI. MÜKEMMEL.",
["bm_suit_badsanta_desc"] = "KABUL EDELİM MİLLET; SANTA BACANIZDAN BUNU GİYEREK İNİYORSA SİZE GÜZEL BİR ŞEY GETİRMEYECEK. ÜSTELİK SÜTLE KURABİYEDEN FAZLASINI DA GÖTÜREBİLİR. AMA BAIN’İN ESKİDEN DEDİĞİ GİBİ: \"ALMANIN MEVSİMİ GELDİ!\"",
["bm_suit_baron_desc"] = "KAÇ SOYGUNCU İŞTE SEKİZ BAŞARILI YIL GEÇİRDİĞİNİ SÖYLEYEBİLİR? EVET, SAYI PEK BÜYÜK DEĞİL. AMA SEN HÂLÂ BURADASIN, DEĞİL Mİ? HÂLÂ EN İYİLER GİBİ KASA AÇIP GANİMET TAŞIYORSUN. O YÜZDEN BU ANI TARZLA, GÖSTERİŞLE KUTLA!",
["bm_suit_bikerjacket_desc"] = "KALIN BİR EGZOZ DUMANI SİSİNDEN ÇIKIYORLAR; SICAKTA TİTREŞEN KÂBUS GİBİ BİR SERAP. METAL VE KAUÇUKTAN KÜKREYEN ATLARA BİNMİŞLER, HIZLA GELİYORLAR. SAYILAMAYACAK KADAR ÇOKLAR. KARŞI DURULAMAYACAK KADAR GÜÇLÜLER. YOLU AÇ, YOKSA SENİ YOLDA EZİLMİŞ LEŞE ÇEVİRİRLER.",
["bm_suit_bikerjacket_gray_desc"] = "KÖTÜ OLMAK İYİYSE SEN EN İYİSİSİN.",
["bm_suit_bikerjacket_green_desc"] = "KAZADAN SAĞ ÇIKMANA MUCİZE DİYORLAR AMA DOĞRUSU BİRAZ DAHA ÖLÜ DİRİLTMEYE YAKINDI.",
["bm_suit_bikerjacket_red_desc"] = "TABİİ Kİ İŞARETLERİ GÖRMEDİN! ÇOK HIZLI GİDİYORDUN.",
["bm_suit_bikervest_camo_desc"] = "TAHTIN SAHİBİNE BULAŞANIN BAŞI AĞIR GELİR.",
["bm_suit_bikervest_desc"] = "ÇOĞU İNSAN BUNUN HIZLA GEÇEN BİR TIR GİBİ KAYBOLAN ŞİDDET DÜRTÜSÜ, GEÇİCİ BİR DURUM OLDUĞUNU SANIR. AMA SEN YOL ÖFKESİNİN GERÇEĞİNİ BİLİYORSUN: BU BİR YAŞAM BİÇİMİ. SENİN İÇİN DÜNYA ON ŞERİTLİ KOCAMAN BİR OTOYOL, TRAFİK DE KİLİTLENMİŞ. SÜRÜYLE BİRLİKTE AĞIR AĞIR MI İLERLEYECEKSİN? YOKSA DİŞİNİ SIKIP GAZA BASACAK, DÖVÜŞEREK ÖNE Mİ GEÇECEKSİN? UNUTMA: BİRİ YARALANIRSA ARABA KULLANMAYI DAHA İYİ ÖĞRENMELİYDİ.",
["bm_suit_bikervest_red_desc"] = "ATEŞ SENİNLE YÜRÜR.",
["bm_suit_bikervest_white_desc"] = "MOTOSİKLETİNİ TAMİR EDEBİLİRSİN AMA KENDİNİ EDEMEZSİN. NE OLMUŞ? SEN TAMİRCİSİN, LANET BİR PSİKİYATRİST DEĞİL.",
["bm_suit_boss_desc"] = "DÜŞÜNÜNCE PAYDAY GANG’İN İŞİ BİRAZ KOLAY. SOYGUNCULUKTA BÜYÜKLÜĞE VE GANİMETE GİDEN YOLLARINDAKİ POLİSLE, FEDERALLERLE VE KOYUN SÜRÜSÜYLE SAVAŞMALARI YETERLİ. ARA SIRA TUHAFLIKLA KARŞILAŞIYORLAR ELBETTE AMA SAİNT'S ROW EKİBİNİN UĞRAŞTIĞI TÜRDEN DEĞİL. CİDDEN; UZAYLILAR, KOMPLOLAR, CEHENNEME AÇILAN GEÇİTLER Mİ? BUNCA ŞEYLE UĞRAŞIRKEN BİR İŞİ NASIL BİTİRİYORSUN? BU YÜZDEN BİR ÜNLÜ EKİPTEN DİĞERİNE SAYGI GÖSTERGESİ OLARAK BU KIYAFETLERİ GİYEBİLİR, SUÇ DÜNYASINA İYİ DUYGULAR YAYABİLİRSİN.",
["bm_suit_boss_suit_desc"] = "GELENEKSEL ZHONGSHAN TAKIMINDAN ESİNLENEN BU SEÇKİN KIYAFET, GERÇEK BİR LİDERİN HAVASINI YAYAR.",
["bm_suit_bullranch_suit_desc"] = "TARİHİ ÖNCÜLER YAZAR. ŞIKLIĞI VE KULLANIŞLILIĞI EŞİT ÖLÇÜDE TAŞIYAN BİR KIYAFETLE YOL AÇAN KİŞİ GİBİ GÖRÜN. BÜYÜK BİLİNMEZ’DE HAVA SOĞUR; DOĞRU CEKET BÜYÜK FARK YARATIR. BAZEN TEK İHTİYACIN ÜZERİNDEKİ KIYAFETLERDİR.",
["bm_suit_bunny_desc"] = "PEMBE BİR TAVŞAN KOSTÜMÜ MÜ? NEDEN OLMASIN? KIYAFETİNLE SİLAHININ TEZATI GÖZ KAMAŞTIRACAK!",
["bm_suit_cable_guy_desc"] = "BELKİ \"BİRİNİN ÇOCUK BAKICISINI ÖLDÜRMESİ GEREK\" DİYE DÜŞÜNEN TÜRDEN BİRİ OLMAK İSTİYORSUN. BELKİ DE YALNIZCA YÖNETİM KURULU ODASINA FARK EDİLMEDEN GİRİP SABİTLENMEMİŞ HER ŞEYİ ÇALMAK İSTİYORSUN. HER İKİ DURUMDA DA BU TAKIM İŞİNİ GÖRÜR.",
["bm_suit_candycane_desc"] = "NOEL BABA’NIN ELFLERİ GREVE ÇIKTI! BU YIL KUZEY KUTBU’NDA OYUNCAK YAPILMIYOR! HİÇBİR KÜÇÜK SOYGUNCUNUN ÇORABINA KÖMÜR GİRMESİN DİYE NOEL BABA’NIN KIYAFETİNİ GİY, ÜLKENİN DÖRT BİR YANINDAKİ USLU BANKALARDAN, KUYUMCULARDAN VE KASA DEPOLARINDAN \"BAĞIŞ\" TOPLARKEN NEŞE YAY VE ONA YARDIM ET!",
["bm_suit_cargocasual_cassette_desc"] = "İYİ BİR MÜZİK OLMADAN SOYGUN OLUR MU?",
["bm_suit_cargocasual_desc"] = "HAVALI VE RAHAT GÖRÜNÜMÜN ÖZÜ; ŞEHİRDEKİ SOYGUNLARIN KEŞFİ İÇİN KUSURSUZ BİR KIYAFET. İNSANLAR SENİ GÖRÜNCE ŞÖYLE DÜŞÜNECEK: \"ŞU ADAMA BAK! BANKA KASASININ TUŞ TAKIMIYLA BAYAĞI İLGİLENİYOR GİBİ. KIYAFETLERİ DE MÜTHİŞ! ACABA O GÖMLEĞİ NEREDEN ALDI? KEŞKE BENİM DE BÖYLE KIYAFETLERİM OLSA...\"$NL;\"BANKA KASASI\" KISMININ NASIL ARADA KAYNADIĞINI GÖRDÜN MÜ?",
["bm_suit_cargocasual_monke_desc"] = "İLK İNSANLAR DÜNYA’YI SOYMADAN ÖNCE O MUZ ÇALIYORDU.",
["bm_suit_cargocasual_texas_desc"] = "EE, NERELİSİN SEN- HA.",
["bm_suit_cartelboss_desc"] = "BU KIYAFETİN BEYAZ İPLİKLERİNİN SİMGELEDİĞİ ÖLÜM, GÜNAHLARI PEŞLERİNE DÜŞTÜĞÜNDE BÜTÜN KARTEL LİDERLERİNİN VARACAĞI YERDİR.",
["bm_suit_classyske_desc"] = "EVET MİLLET, YİNE YILIN O ZAMANI GELDİ. SIRADAN İNSANLAR, BÜTÜN YIL GİYMEYİ DİLEDİKLERİ ÇILGIN KOSTÜMLERİ GİYEBİLİYOR! AMA BİZ SOYGUNCULARIN BÖYLE DERTLERİ YOK, DEĞİL Mİ? İSTEDİĞİMİZİ İSTEDİĞİMİZ ZAMAN GİYERİZ. YİNE DE BAYRAMIN HAVASINA KEMİKLİ BİR ŞIKLIKLA KATILMAKTA BİR SAKINCA YOK.$NL;$NL;YARATICI: LUKE MİLLANTA.",
["bm_suit_clown_desc"] = "DİKKAT DAĞITMAK SOYGUNCUNUN EN İYİ ARACI OLABİLİR. DOĞRU KIYAFET DE BUNU SAĞLAYIP DÜŞMANI NE OLUP BİTTİĞİNİ DÜŞÜNMEYE İTER. \"SİRK Mİ GELMİŞ? NE BİÇİM PALYAÇO SİLAH TAŞIR?\" BÖYLE DÜŞÜNÜNCE BUNU BİRAZ TARZ VE RENKLİ GÖSTERİŞLE YAPMAMAN İÇİN NEDEN YOK. BU YÜZDEN BU PEK ŞIK KIYAFET VAR; SANA KENDİNİ SUÇUN PRENSİ GİBİ HİSSETTİRECEK.",
["bm_suit_clown_desc_2"] = "ON YILLIK SOYGUNCULUK. ON. YIL. MÜTHİŞ BİR SUÇ SERİSİ. BİR ON YIL DAHA GİTMESİNE KARŞI BAHİS OYNAMAZDIK. SEN OYNAR MIYDIN?$NL;$NL;KONSEPT: ANGUSBURGERS.",
["bm_suit_contintental_desc"] = "HOXTON, NEW YORK’TA GECE YAPTIĞI BİR İNFAZ TERS GİDİNCE ÜÇ POLİS ARABASINDAN KAÇMAK ZORUNDA KALMIŞTI. DÜŞMAN KANINA BULANMIŞ HÂLDE MASKESİNİ VE SİLAHINI OLUĞA ATIP SAKLANMAK İÇİN EN SEVDİĞİ GECE KULÜBÜNE YÖNELDİ. (ACİLEN İÇKİYE DE İHTİYACI VARDI.) YOLDA BU TAKIMI BİR MAĞAZANIN VİTRİNİNDE GÖRDÜ. O HÂLİYLE GİZLENEMEYECEĞİNİ ANLAYAN HOX İÇERİ GİRİP ÜSTÜNÜ HIZLICA DEĞİŞTİRDİ. İLK POLİS ARABASI KÖŞEYİ DÖNDÜĞÜNDE HOXTON HER ZAMANKİ ZARAFETİYLE KULÜP KUYRUĞUNDAKİ KADINLARLA SOHBET EDİYORDU. ARABA YANINDAN GEÇERKEN DOĞRUDAN PROJEKTÖRE BAKTI... SÜRÜCÜ AVINI HİÇ TANIMADI.",
["bm_suit_corl_desc"] = "GÜCÜN PEK ÇOK BİÇİMİ VAR. DÜŞMANLARINA ÜSTÜN GELMENİ SAĞLAYAN KUVVET. TEK SÖZLE BAŞKALARINI YÖNETECEK NÜFUZ. BEŞ ADIM SONRASINI DÜŞÜNECEK KURNAZLIK. BİRİNDE USTALAŞMAK SENİ DOĞRUDAN ZİRVEYE TAŞIYABİLİR. HEPSİNDE USTALAŞMAKSA ORADA KALMANI SAĞLAR.",
["bm_suit_cyberhoodie_desc"] = "ELEKTRONİK MÜZİK HAVASI TAŞIYAN MODERN BİR KAPÜŞONLU YORUMU.",
["bm_suit_cybertrench_desc"] = "TRENÇKOTUN KARA FİLM TARZINI MODERN BİR TEKNOLOJİ HAVASIYLA BİRLEŞTİRİR.",
["bm_suit_darkprince_desc"] = "THE DEVİL İÇİN AYAKKABI ÜRETİLMİYOR. ASIRLARDIR ARIYOR AMA TOYNAKLARINA UYACAK, CEHENNEM’DEKİ UZUN YÜRÜYÜŞLERİNİN YAKICI SICAĞINA DAYANACAK BİR MARKA YOK. O ŞIK YELEĞİ VE CEKETİ BU YÜZDEN GİYİYOR; UMUDU, YALINAYAKLIĞININ UTANCINDAN DİKKATİNİ BAŞKA YÖNE ÇEKMEK!",
["bm_suit_desperado_desc"] = "MÜZİSYEN KILIĞINDA DOLAŞAN SİLAHŞORLARIN HİKÂYELERİ ANLATILIR. ADALETSİZLİĞE KARŞI SAVAŞAN, BUNU KENDİ YAPAMAYAN İNSANLARIN YAŞADIĞI TRAJEDİLERİN İNTİKAMINI ALAN SİLAHŞORLAR. EVET, BU TANIM PAYDAY GANG’E PEK UYMUYOR, DEĞİL Mİ?",
["bm_suit_dodsuit_desc"] = "BU KADAR GÖSTERİŞLİ BİR SİLAHŞOR TOPRAĞIN ALTINI HAK ETMEZ! SOMBRERONA TOPRAK BULAŞIR! DÜELLOLARLA İLGİLİ KÜÇÜK BİR SIR: VURULMAK KAYBETTİĞİN ANLAMINA GELMEZ. YALNIZCA YENİDEN KALKAMAZSAN KAYBEDERSİN.",
["bm_suit_elegantscarf_desc"] = "TARZI VE BİRAZ GÖSTERİŞİ ASLA KÜÇÜMSEME. BU HAUTE COUTURE PARÇASI ZARİF BİR İZLENİM BIRAKMANI SAĞLAYACAK. PLANIN NE OLURSA OLSUN ONU UYGULARKEN MUHTEŞEM GÖRÜNECEKSİN.",
["bm_suit_elfsuit_default_desc"] = "NOEL AĞAÇLARI ASLA PES ETMEZ.",
["bm_suit_elfsuit_desc"] = "MUHTEMELEN NAUGHTY ELVES’İ HİÇ DUYMADIN. TİMMY DE DUYMAMIŞTI. ÇOK İSTEDİĞİ MODEL TRENİ ALABİLMEK İÇİN BÜTÜN YIL USLU DURDU AMA HEDİYEYİ AÇAR AÇMAZ EVİN İÇİNE TÜKÜRMEYE VE ÇÖL FARELERİNİ MİKRODALGAYA KOYMAYA GERİ DÖNDÜ. SİSTEMİ ALT ETTİĞİNİ SANDI AMA KİMSE SANTA’YI ALT EDEMEZ. BÖYLE SAÇMALIKLAR YAPARSAN SANTA, OYUNCAKLARINI GERİ ÇALMALARI VE BELKİ İBRET OLSUN DİYE BAŞPARMAKLARINI KIRMALARI İÇİN NAUGHTY ELVES’İ GÖNDERİR. UNUTMA: USLULAR LİSTESİ’NDEYSEN ORADA KAL; YOKSA NAUGHTY ELVES SENİ MAHVEDER. TİMMY’YE SOR YETER.",
["bm_suit_elfsuit_red_desc"] = "ÇOBANPÜSKÜLÜYLE SÜSLEN, NEŞEYİ EKSİK ETME.",
["bm_suit_elfsuit_violet_desc"] = "ÜZÜLME. EN HAVALI İNSANLAR HEP BU LİSTEYE GİRER.",
["bm_suit_elfsuit_yellow_desc"] = "O SICAK KAKAOYU BİR PİÑA COLADA İLE DEĞİŞTİR!",
["bm_suit_enforcer_suit_desc"] = "GOLDEN DAGGER’IN RED POLES ÜYELERİNİN GİYDİĞİ, GELENEKSEL ÖĞELER TAŞIYAN MODERN KESİMLİ BİR TAKIM.",
["bm_suit_esport_desc"] = "İKİ PARÇALI TAKIM ELBİSE SOYGUNA PROFESYONELLİK KATAR, KORKMUŞ SİVİLLERE SAKİN BİR OTORİTE HİSSİ VEREBİLİR AMA PEK KULLANIŞLI VEYA RAHAT DEĞİLDİR. BANKAYI KURŞUNLAMAK YA DA KASA AÇMAK GİBİ YORUCU İŞLERDE RAHATLIĞIN KIYMETİ BÜYÜKTÜR. NİCE ÇETENİN YÜKSEK VEYA DÜŞÜK RÜTBELİ MAFYA ÜYELERİNİN, RESMÎ VE TÖRENSEL BİR YANI GEREKMEYEN İŞLERİ YÜRÜTÜRKEN EŞOFMANI TERCİH ETMESİNİN BİR SEBEBİ VAR.",
["bm_suit_fighterpilot_desc"] = "PEK BİLİNMEYEN BİR GERÇEK: BILE, 1. DÜNYA SAVAŞI’NIN HAVA MUHAREBELERİNE HAYRAN! DİKKATLİ GÖZLER, SOYGUNLARDA ONU SIK SIK ASLINA UYGUN AVCI PİLOTU ÜNİFORMASIYLA, HELİKOPTER YERİNE BİR AVRO 504 UÇURDUĞUNU HAYAL EDERKEN YAKALAR. GÖKTEN ÖLÜM YAĞDIRMAK İSTEYEN?",
["bm_suit_gangstercoat_desc"] = "BAZI ŞEYLER RESMEN \"GANGSTER\" DİYE BAĞIRIR, DEĞİL Mİ? BU TARZ TAKIM ELBİSENİN TAM DOĞRU PALTOYLA BİRLEŞMESİNDE BİR ŞEY VAR. PARLAK VE DAYANIKLI; SOYGUNLA GEÇEN GÜNÜN YA DA GECEN NE GETİRİRSE GETİRSİN SENİ ATLATMAYA HAZIR. ",
["bm_suit_general_desc"] = "SURLARDAN DIŞARI BAKIYORSUN; BİR ELİN KILICINDA, DİĞERİ KUSURSUZ DİKİLMİŞ PALTUNUN GÖĞSÜNDE. ADAMLARIN SANA SAYGI DUYUYOR, DÜŞMANLARIN SENDEN KORKUYOR. DİNLE! BORULAR ÇALIYOR! HAYKIRIŞ YÜKSELİYOR! SAVAŞA! VE... ÇATIRR! NE? YİNE Mİ! SİKTİĞİMİN BOZUK, İŞE YARAMAZ MATKABI SOYGUNCUYU HUZUR İÇİNDE HAYAL KURMAYA BİLE BIRAKMIYOR! AMA VAY BE... NE ŞIKSIN.",
["bm_suit_gentleman_desc"] = "BAZILARI UZUN PALTOLARIN 1990’LARDA DEMODE OLDUĞUNU SÖYLER. AMA PAYDAY GANG MODAYA UYMAZ. HER ŞEYİ HAVALI GÖSTEREBİLİRLER.",
["bm_suit_ghostly_desc"] = "ŞUNU SÖYLEYEYİM, HAYALET KOSTÜMÜNE BAYILDIM. UÇUŞAN KUMAŞLAR, SİS BULUTU FALAN, HARİKA. BENİM GİBİ AKILLI BİRİNİ KANDIRMAYA YETMEZ AMA POLİSLERİN ÖDÜ KOPACAK! YALNIZ, SORMADAN EDEMEYECEĞİM... YERDEN NASIL BÖYLE YÜKSELİYORSUN? ADIN NEYDİ SENİN? BU İŞ İÇİN BEŞİNCİ BİRİNİ TUTTUĞUMUZU HATIRLAMIYORUM.$NL;HOP, DOSTUM! GÖZLERİN PARLIYOR! NASIL... ŞEY... AA... HASSİKTİR...",
["bm_suit_gunslinger_desc"] = "YİRMİ ADIM MESAFEDE DÜELLOYA TUTUŞMA İHTİYACI HİSSEDEN SOYGUNCU İÇİN KUSURSUZ BİR TAKIM.",
["bm_suit_highinttech_desc"] = "ASYA’DA MUHAFIZLARIN, PARALI ASKERLERİN VE TRİAD ÜYELERİNİN GÖZDESİ BU HAFİF, TAKTİK TAKIM, BATILI BENZERLERİNDEN BİRAZ DAHA İYİ HAREKET KABİLİYETİ SUNAR.",
["bm_suit_hiphop_desc"] = "EZİLENLERİN RİTMİ. ŞEHİR İÇİNİN GÜRÜLTÜSÜNDE SESİNİ DUYURMAYA ÇALIŞAN SOKAK ŞAİRLERİNİN DÜŞÜNCELERİNDEN DOĞAN VAHŞİ BİR ÖFKE. GETTONUN SESLERİ SONSUZA DEK YANKILANACAK; TOPLUMSAL HAPİSHANENİN DUVARLARI YIKILIP YENİ BİR GÜNÜN KAPILARINI AÇACAK.",
["bm_suit_hippie_desc"] = "BU MODAYKEN SOYGUNCULUK ÇOK DAHA BASİTTİ. AĞLAR DEĞİL, BIÇAKLARLA İNSANLAR KESİLİRDİ; SİLAHŞORUN, KASA HIRSIZININ VEYA KAÇIŞ ŞOFÖRÜNÜN SAF BECERİSİ DAHA DA ÖNEMLİYDİ.",
["bm_suit_jail_pd2_clan_desc"] = "NASIL OLDUĞUNU BİLİYORSUN. BİR KEZ SÖYLE, İKİ KEZ SÖYLE; ÜÇÜNCÜDE OLUR. VE UNUTMA... ÇALMASINI İSTEDİĞİN HER ŞEYİ ÇALAR, HACKLEMESİNİ İSTEDİĞİN HER ŞEYİ HACKLER. ADINI SÖYLE; SENİ GÖZALTINDAN TAKASLA ÇIKARIR. BAIN! BAIN! B...",
["bm_suit_jumpsuit_desc"] = "KARİYERİNİ DEĞİŞTİREN BAZI SOYGUNLAR, YANINDA GETİRDİĞİN EKİPMANDAN ÇOK DAHA FAZLASINI İSTER. HAREKET KABİLİYETİ VE DAYANIKLILIK, BİR SOYGUNCUYU KELEPÇEDEN KURTARAN ŞEYLER OLABİLİR. BU KIYAFET DE TAM BUNUN İÇİN YAPILDI. GÜÇLENDİRİLMİŞ BİR TAKTİK YELEKLE TAMAMLANAN TEK PARÇALI TEMELİ, ÇEŞİTLİ ARAZİLERDE RAHATÇA HAREKET ETMENİ SAĞLAR VE BOLCA TAŞIMA OLANAĞI SUNAR.",
["bm_suit_jun21_thug_black_desc"] = "BULUTLU GÖĞÜ YARAN GÜNEŞ GİBİ, KÜÇÜK BİR RENK KIVILCIMIYLA AĞIRBAŞLI.",
["bm_suit_kungfumaster_desc"] = "BU KIYAFET, DÖVÜŞ TARZINI UYGULARKEN HIZ VE HAREKET ÖZGÜRLÜĞÜ SAĞLAR. BELALI ZARAFETİ DE İNKÂR EDİLEMEZ.",
["bm_suit_leather_desc"] = "DAHA MASUM BİR ZAMANA, 90’LARIN SONUNA DÖNELİM. AKSİYON KAHRAMANLARI EKRANDA TAKLALAR ATARAK UÇUŞUR, MERMİ YAĞDIRIR VE HER YANA BETON TOZU SAÇARDI. O GÜNLERİ ÖZLÜYORSAN BU TAKIM TAM SANA GÖRE.",
["bm_suit_leatherfluff_bats_desc"] = "HAFİFÇE ÜRPERTİCİ.",
["bm_suit_leatherfluff_desc"] = "BÖYLE BİR CEKETİN FAZLA SÜSE İHTİYACI YOK. OVALARIN BÜTÜN SERTLİĞİNİ, ŞEHRİN BÜTÜN TARZINI TAŞIYOR. AMA SEN İŞİ BİR ADIM İLERİ GÖTÜRMEYİ SEVERSİN. GÖSTERİŞLİ BİR ŞEY DEĞİL; DÜNYAYA KİM OLDUĞUNU ANLATACAK KÜÇÜK BİR AMBLEM. SONUÇTA BİR SİMGE BİN SÖZE BEDELDİR.",
["bm_suit_leatherfluff_dots_desc"] = "İYİ AVLAR!",
["bm_suit_leatherfluff_lightning_desc"] = "SİSTEME ELEKTRİK GİBİ ÇARP.",
["bm_suit_lonorwa_desc"] = "ŞIK VE ZARİF, AYNI ZAMANDA SICAK VE RAHAT. KARLI ORMANDA VEYA KIŞ SOKAKLARINDA PUSU MU? DERT ETME, HAZIRSIN.",
["bm_suit_lowinttech_desc"] = "ASYA’NIN BÜYÜK METROPOLLERİNDE POPÜLER BİR ŞEHİR KIYAFETİ. DAYANIKLILIĞI VE HAREKET RAHATLIĞI NEDENİYLE TRİAD ÜYELERİ VE DİĞER GANGSTERLER SIKÇA TERCİH EDER.",
["bm_suit_mar21_thug_default_desc"] = "ZENGİN ÇOCUKLARIN LİSE FUTBOL MAÇINA BUNU GİYEBİLMEK İÇİN ANNE BABALARINA YALVARDIĞINI BİLİYORSUN.",
["bm_suit_mar21_thug_desc"] = "HAKKINI VERMEK LAZIM. BAZI TRİAD ÜYELERİ, ESKİMİŞ GANGSTER KIYAFETİ KLİŞESİNİ ALIP GANGSTERLERİN YAPTIĞI VİCDANSIZ İŞLER İÇİN GEREKEN RAHATLIĞI BOZMADAN YENİDEN HAVALI KILMAYI İYİ BİLİYOR. HEM DE HİÇ ZORLANMADAN. BU, KÖTÜ BİR 1970’LER KUNG FU FİLMİNDE GÖRECEĞİN TÜRDEN DEĞİL. HİÇ DEĞİL. MODERN KESİM, UZAY ÇAĞI KUMAŞLARI, NE ARARSAN VAR.",
["bm_suit_mar22_thug_white_desc"] = "BUNU TAŞIYACAK KADAR ZARİFSEN MUHTEMELEN SOYGUN SIRASINDA KIYAFETLERİNE KAN BULAŞTIRMAMAKTA DA USTASINDIR.",
["bm_suit_mariachi_desc"] = "GERÇEK BİR MARİACHİ TAKIMI YAPMANIN İNCELİKLERİ KÜÇÜMSENMEMELİ. BAZILARI ALDATICI DERECEDE SADE GÖRÜNÜR AMA ALTINDA ÇOĞU ZAMAN NESİLDEN NESİLE AKTARILAN KARMAŞIK BİR USTALIK YATAR.",
["bm_suit_miami_desc"] = "KORUNMAK, ELBETTE MERMİLERİ DURDURMAK KADAR FARK EDİLMEMEKLE DE İLGİLİDİR. 1980’LER TARZI TAKIM ELBİSELERİN BOL KIVRIMLARI SİLAHLARI GİZLEMEK İÇİN GENİŞ ALAN SUNAR. KUMAŞ ÇEŞİTLİLİĞİ DE GEREKTİĞİNDE HAVA KOŞULLARINA UYUM SAĞLAMANI SAĞLAR. ",
["bm_suit_mocow_desc"] = "AMERİKAN KOVBOYUNUN O İKONİK FİYAKASI VAR, PİSLİĞİ VE HAYVAN KOKUSU YOK. DANS KULÜBÜNDE DE ESKİ BATI SALONUNDA DA HOŞ KARŞILANIRSIN.",
["bm_suit_moneysuit_default_desc"] = "PARAYI AL VE KAÇ!",
["bm_suit_moneysuit_desc"] = "İLK SOYGUNUMDU, TAMAM MI? KUŞ UÇMAZ KERVAN GEÇMEZ BİR YERDE MİNİCİK BİR BANKA ŞUBESİ. KASADA ÇOK PARA OLMAZ, SADECE VEZNELERDEN TOPLARIZ DİYE DÜŞÜNÜYORUM. İKİ GANİMET ÇANTASI HAYLİ HAYLİ YETER. MEĞER DÜŞÜNDÜĞÜMDEN ÇOK DAHA FAZLA VEZNE VARMIŞ. HEM BU KÜÇÜCÜK BANKA PEK DE KÜÇÜK DEĞİLMİŞ; KASA AĞZINA KADAR DOLU! AMA BENİ BİLİRSİN, GERİDE TEK DOLAR BIRAKMAM. KENDİ ÇANTALARIMI, BANKANIN ÇANTALARINI, SİVİLLERDEN ALABİLDİĞİM BÜTÜN EL VE SIRT ÇANTALARINI DOLDURDUKTAN SONRA GÖMLEĞİMLE İÇ ÇAMAŞIRIMI ÇIKARIP... ŞEY... YARATICI DAVRANDIM.$NL;GÜNEŞ GÖRMEYEN YERLERİMDE BİRKAÇ KÂĞIT KESİĞİ OLDU AMA DEĞDİ!$NL;",
["bm_suit_moneysuit_gold_desc"] = "AÇGÖZLÜLÜĞÜN İNSANIN RUHUNU YAKAN ATEŞ OLDUĞUNU SÖYLERLER AMA ÜZERİNDE İYİ DURUYOR.",
["bm_suit_moneysuit_money_desc"] = "AŞAĞI YUKARI BİR MİLYON DOLAR GİBİ GÖRÜNÜYORSUN. UMARIM YAĞMUR YAĞMAZ.",
["bm_suit_murky_suit_desc"] = "MURKYWATER PARALI ASKERLERİNİN KULLANDIĞI BİR ASKERÎ ÜNİFORMA. ÜZERİNDE MURKYWATER LOGOLU BİR ARMA BULUNUR.",
["bm_suit_newhorizon_desc"] = "YENİ BİR ÇAĞ DOĞUYOR. İTTİFAKLAR KURULDU. YOLLAR BELİRLENDİ. UZAKTAKİ O ATEŞLİ PARILTI GİDEREK GÜÇLENİYOR.$NL;$NL;SIRADAKİNE HAZIR MISIN?",
["bm_suit_nightwalker_desc"] = "GECENİN ÖLÜMSÜZ BİR YARATIĞI OLARAK PEK ÇOK MODA AKIMININ GELİP GEÇTİĞİNİ GÖRDÜN. BAZI GÖRÜNÜMLER ZAMANA DAHA İYİ DAYANIR AMA HİÇBİR ŞEYİN YAŞAYAN BİR ÖLÜYE 18. YÜZYIL ARİSTOKRATININ ZARİF İNCELİĞİ KADAR YAKIŞMADIĞINI BİLİRSİN. SEN KLAS BİR KAN EMİCİSİN!",
["bm_suit_none_desc"] = "BU, SOYGUNCUNUN SEÇİLİ ZIRHLA GİYDİĞİ VARSAYILAN KIYAFETTİR.",
["bm_suit_oct21_thug_red_desc"] = "BAZILARI BU TAKIMIN KIRMIZI KOLLARININ, DÜŞMANIN DİKKATİNİ AYAKLARININ YAPTIĞINDAN UZAKLAŞTIRACAĞINI SÖYLEDİ. YENİ BİR FİKİR AMA BELKİ DE KÖRÜ KÖRÜNE GÜVENMEYE DEĞMEZ!",
["bm_suit_overkillpunk_desc"] = "BİRAZ SERTLİK KATILMIŞ ŞEHİRLİ TAVIR NADİREN YANILTIR. ÜSTELİK ALTINDA KUSURSUZ BİR GÖMLEK VE KRAVATLA HEMEN HER DURUMA HAZIRSIN. BAŞKA BİR DEYİŞLE, ÖLDÜRMEK İÇİN GİYİNDİN.",
["bm_suit_peacoat_desc"] = "BİR SOYGUNCUNUN KIYAFETİ BAZEN HEM BELLİ ÖLÇÜDE RESMÎ VE SAYGIN HEM DE RAHAT VE İŞE UYGUN OLMALIDIR. BU KOT ALT PARÇA İLE DAHA CİDDİ ÜST PARÇANIN BİRLEŞİMİ, İKİ DÜNYANIN EN İYİ YANLARINI BİR ARAYA GETİRİR.",
["bm_suit_poolrepair_desc"] = "KARARSIZSAN HEP TAMİRCİ YOLUNU SEÇ. SAYISIZ BAYAĞI FİLMDEKİ EN AKILSIZ KURGU, ADİ İMALARIN KAYNAĞI OLABİLİR AMA HEMEN HER YERE GİRMENİ SAĞLAR. ÇOĞU KİŞİ TUVALETİNİ VEYA TELEVİZYONUNU KULLANAMAZSA ÇILDIRIR; ZENGİNLERİNSE HAVUZLARI HEP KUSURSUZ OLMALI. HAVUZCU KADIN VEYA ERKEK GENELLİKLE HOŞ KARŞILANIR. BOL CEBİ VE DAR ALANLARDA HAREKET ESNEKLİĞİYLE OLDUKÇA KULLANIŞLI BİR KIYAFET DE. KASA AÇMAK İÇİN SU ÇEKMEN GEREKTİĞİNDE DE KİM İTİRAZ EDECEK?",
["bm_suit_puffervest_blue_desc"] = "GÜNEŞ BATINCA YELEK GİYİLİR.",
["bm_suit_puffervest_desc"] = "HAVALI BİR ŞEHİRDE YAŞIYORSUN AMA HAVA SOĞUMAYA MI BAŞLADI? YELEK GİY! KAMP ATEŞİ PARTİSİNE Mİ GİDİYORSUN? YELEK! GİTAR ÇALAN BİR ZAMAN YOLCUSU MUSUN? TURUNCU YELEK! YELEKLER HARİKA. SICAK TUTARLAR, İYİ GÖRÜNÜRLER, HATTA BAZILARI CAN YELEĞİ OLARAK DA KULLANILABİLİR.",
["bm_suit_puffervest_grey_desc"] = "SADECE SANA BAKARAK ANLAYAMAZLAR.",
["bm_suit_puffervest_red_desc"] = "İYİ GÖRÜNMEK VE SICAK KALMAK BİRBİRİNİ DIŞLAMAZ.",
["bm_suit_punk_desc"] = "PUNK ROCK CEKETİ VE PANTOLONU, \"KİBAR\" TOPLUMUN YERLEŞİK KURALLARINA MEYDAN OKUYARAK GURURLA GİYİLEN BİR ZIRHTIR. GERÇEK BİR PUNK CEKETİNİN HER ZIMBASI EMEKLE, ELLE TAKILIR. YİNE ELLE YAPILAN HER BOYA SÜSLEMESİNİN, GİYEN KİŞİ İÇİN DERİN BİR ANLAMI VARDIR. TABİİ BÜTÜN DÜNYAYA ÇEKİLMİŞ KOCAMAN BİR SİKTİR DEĞİLSE.",
["bm_suit_railroad_desc"] = "BİR LOKOMOTİFTEN DAHA GÜÇLÜ KİMDİR? ONU YÖNETEN KİŞİ. TRENİN NE ZAMAN KALKACAĞINA, NE KADAR HIZLI GİDECEĞİNE, BİRİ İÇİN DURACAKSA KİMİN İÇİN DURACAĞINA SEN KARAR VERİRSİN. İSTESEN BÜTÜN OPERASYONU RAYDAN ÇIKARABİLİRSİN AMA YAPMIYORSUN. SENİ BAŞA BU YÜZDEN KOYDULAR.",
["bm_suit_raincoat_desc"] = "GİYENİ KURU TUTAN KLASİK SARI BİR YAĞMURLUK. PARLAK RENGİ, ŞİDDETLİ YAĞMURUN GÖRÜŞÜ BOZDUĞU DURUMLARDA TRAFİK GÜVENLİĞİNİ DE ARTIRIR.",
["bm_suit_rusbear_desc"] = "SOYGUN YAPARKEN DONACAKSIN DİYE BİR KURAL YOK. BUNUNLA HEM İYİ GÖRÜNÜR HEM RAHAT EDER HEM DE SOYGUNLARINA DEVAM EDERSİN.",
["bm_suit_scrub_desc"] = "HASTANEDE GÖREV YAPAN BİR CERRAHIN GİYDİĞİ TÜRDEN KORUYUCU KIYAFET. CERRAHİ KIYAFETLERDE GENELLİKLE HEM SAKİNLEŞTİREN HEM DE KAN VE DİĞER VÜCUT SIVILARININ LEKELERİNİ PERSONELİN KOLAYCA FARK ETMESİNİ SAĞLAYAN RENKLER KULLANILIR.",
["bm_suit_slaughterhouse_desc"] = "İYİ BİR TAKTİK YELEĞE VE MUHAREBE PANTOLONUNA ASLA HAYIR DEME. BOL CEPLİ OLSUN. ASLA FAZLA CEP OLMAZ. PAYDAY GANG KARİYERİNİN BAŞLARINDA CHAINS, BU TAKIMI OLUŞTURMAK, DENEMEK, AYARLAMAK VE SOYGUNDA EN İYİ PERFORMANSI VERECEĞİNDEN EMİN OLMAK İÇİN NEREDEYSE İKİ AY UĞRAŞTI. BUNCA YIL SONRA PEK AZ DEĞİŞTİ VE FİZİKSEL AÇIDAN ZORLU SOYGUNLARDA HÂLÂ GÖZDE KIYAFETLERDEN BİRİ.",
["bm_suit_sneak_suit_desc"] = "BU BİR GİZLİLİK KIYAFETİ. SESSİZ HAREKET İÇİN RAHATTIR; YUMUŞAK, SİYAH MALZEMESİ GECE OPERASYONLARINDA KARANLIĞA KARIŞMAYI SAĞLAR. MÜHİMMAT VE EKİPMAN İÇİN CEPLERİ VARDIR.",
["bm_suit_sparkle_desc"] = "İŞTE FARK EDİLMEK, GÖSTERİŞLİ BİR İZLENİM BIRAKMAK MI İSTİYORSUN? EVET, YOLU BU.",
["bm_suit_t800_desc"] = "EK BİR DERİ KATMANI HER ZAMAN İYİ FİKİRDİR. BİR DE BU KADAR İYİ GÖRÜNÜYORSA EN BUDALA ADAM BİLE SANA BULAŞMADAN ÖNCE İKİ KERE DÜŞÜNÜR.",
["bm_suit_texvest_black_desc"] = "KARANLIK VARDIR, AYSIZ BOZKIR GECESİ KADAR KARANLIK VARDIR, BİR DE SEN VARSIN.",
["bm_suit_texvest_blue_desc"] = "BASKI ARTTIĞINDA BİLE SOĞUKKANLILIĞINI KORURSUN.",
["bm_suit_texvest_desc"] = "ZORLU ARAZİDE DE ATINDAN İNMEZ, ÜSTELİK İYİ GÖRÜNÜRSÜN. KOVBOY, AZMİN EFSANEVİ BİR SİMGESİ OLARAK DİMDİK DURUR; HEM DE YAKIŞIKLI BİR SİMGESİ. BU KIYAFET ESKİ BATI’DA İŞE YARIYORDU, BUGÜN DE BAL GİBİ YARAR. MODERN KOVBOY ATALARI KADAR KORKUSUZDUR, SADECE BİRAZ DAHA ŞIKTIR. BİRAZ TARZDAN ZARAR GELMEZ ORTAK.",
["bm_suit_texvest_green_desc"] = "KÖKLERİNİ HATIRLA.",
["bm_suit_tstp_hitman_blue_desc"] = "KEYİFSİZLİĞE KAPILMA; AVINI İNDİRİRKEN RUH HÂLİNİ MAVİYLE İFADE ET!",
["bm_suit_tstp_hitman_brown_desc"] = "ORTAMLA KAYNAŞMAN GEREKEN AMA BUNU YİNE DE TARZ SAHİBİ YAPMAYI İSTEDİĞİN PİS ARKA SOKAKLARDAKİ İNFAZLAR VE SOYGUNLAR İÇİN!",
["bm_suit_tstp_hitman_default_desc"] = "YAĞMURLU BİR GÜNDE İŞ GÖREN USTA TETİKÇİ İÇİN.",
["bm_suit_tstp_hitman_desc"] = "İŞİNDEKİ BECERİSİNİ SANATA DÖNÜŞTÜRMEKLE ÖVÜNEN SOYGUNCU VEYA TETİKÇİ İÇİN BU KIYAFET TAM ARANAN ŞEY OLABİLİR. GELENEKSEL KESİM VE GÖSTERİŞSİZ KUMAŞLAR, EN YENİ TAKTİK LİF TEKNOLOJİSİYLE BULUŞUYOR. YAĞMURA BİLE DAYANIR!",
["bm_suit_tstp_hitman_red_desc"] = "KURBANININ HATIRLAYACAĞI SON ŞEY, RETİNASINA KAZINAN BU KUMAŞIN MUHTEŞEM GÖRÜNÜŞÜ OLACAK. TABİİ ARKADAN İNDİRMEYE KARAR VERMEZSEN. BÖYLESİNE GÖSTERİŞLİ BİR KIYAFETİ GİZLİCE SAKLAMAK BİRAZ ZİYAN OLMAZ MI?",
["bm_suit_tstp_traditional_blue_desc"] = "İSVEÇ KRALI, ÇİNLİ BİR TETİKÇİNİN KIYAFETİNİ GİYMEK İSTEYEN BİR SOYGUNCU OLSAYDI BUNU SEÇEBİLİRDİ!",
["bm_suit_tstp_traditional_brown_desc"] = "70’LERİN HAVASINI HİSSETMEK AMA MODERN BİR DOKUNUŞU DA KORUMAK İSTEYEN SOYGUNCULAR İÇİN.",
["bm_suit_tstp_traditional_default_desc"] = "KALABALIKTA DİKKAT ÇEKMEK İSTEMEYEN SOYGUNCU İÇİN SAKİN TONLAR.",
["bm_suit_tstp_traditional_desc"] = "SERT, ADAM DÖVEN, KAÇAK MAL TAŞIYAN BİR TRİAD GANGSTERİNİN BİLE ARA SIRA ARKASINA YASLANIP RAHATLAMASI GEREKİR. AMA KÖTÜLER UYUYAMAZ; O YÜZDEN İŞLER SARPA SARDIĞINDA DAYANACAK BİR ŞEYİ HEP EL ALTINDA TUTMALISIN. MESELA DOLANDIRDIĞIN UYUŞTURUCU BARONU KAPINI KIRARKEN. İŞTE BU BİR SEÇENEK; DURUMUN NE OLURSA OLSUN TARZINI KORUMANI SAĞLAR!",
["bm_suit_tstp_traditional_red_desc"] = "KIRMIZI VE SİYAH BİRLEŞİMİ ASLA YANILTMAZ.",
["bm_suit_tux_desc"] = "RESMÎ DAVETLER İÇİN GELENEKSEL BİR SMOKİN. KENDİNE ÖZGÜ SİYAH BEYAZ TASARIMINI KARAKTERİSTİK SİYAH PAPYON TAMAMLAR.",
["bm_suit_var_baron_blue_desc"] = "KUTLAMAYI GECE YARISI YAPMAYI TERCİH EDEN SOYGUNCUYA.",
["bm_suit_var_baron_default_desc"] = "KIZIL GÜNEŞ DOĞARKEN KUTLAMAYI TERCİH EDEN SOYGUNCUYA.",
["bm_suit_var_bikerjacket_suit_default_desc"] = "AMERİKA’NIN ANA CADDESİ SEKİZ FARKLI EYALETTEN GEÇER. EN BÜYÜĞÜNÜN HANGİSİ OLDUĞUNU TAHMİN ET.",
["bm_suit_var_bikervest_default_desc"] = "HIZLI YAŞA, DAHA HIZLI SÜR. ÖLÜM YALNIZCA BİR PİT MOLASIDIR.",
["bm_suit_var_boss_suit_default_desc"] = "İNTİKAM ZAMANI GELDİĞİNDE BU TAKIM TAM YERİNİ BULUR.",
["bm_suit_var_boss_suit_green_desc"] = "SİNSİ, YÜZEYİN ALTINDA BEKLEYEN BU KIYAFETİN SAHİBİ; SALDIRI VAKTİ GELENE DEK GERÇEK GÜCÜNÜ SAKLAMANIN DEĞERİNİ BİLİR.",
["bm_suit_var_boss_suit_red_desc"] = "ŞIK VE TALİHİN DAMGASINI TAŞIYAN BU TAKIM HER ORTAMA UYAR.",
["bm_suit_var_boss_suit_yellow_desc"] = "NE DE OLSA ALTIN ÜSTÜN METALDİR. ÖYLEYSE NEDEN GÖSTERİŞLİ, SÜSLÜ BİR DESENE DOKUNMUŞ HÂLİNİ GİYMEYESİN?",
["bm_suit_var_bullranch_suit_black_desc"] = "BAZEN YENİ YOLLAR AÇMAK İÇİN BAZI KURALLARI ÇİĞNEMEK GEREKİR.",
["bm_suit_var_bullranch_suit_blue_desc"] = "İŞLER ZORLAŞINCA GÜÇLÜLER KOT GİYER.",
["bm_suit_var_bullranch_suit_brown_desc"] = "ÖNCÜ RUHU SENİN İÇİNDE YAŞIYOR.",
["bm_suit_var_bullranch_suit_default_desc"] = "DEĞİŞMEYEN TEK ŞEY DEĞİŞİMDİR.",
["bm_suit_var_cargocasual_suit_default_desc"] = "DOĞRU VE YANLIŞIN SINIRLARININ DIŞINDA YAŞIYORSUN.",
["bm_suit_var_classyske_cream_desc"] = "HER EKİM GELDİĞİNDE YABAN MERSİNLİ TURTA VE BİR PARÇA VANİLYALI KREMA, BALKABAĞI TURTASINA GÜZEL BİR ALTERNATİFTİR. SENİN ZEVKİN BUYSA BU TAKIMLA KEMİKLİ TARZINA BÜRÜN.$NL;$NL;YARATICI: LUKE MİLLANTA.",
["bm_suit_var_classyske_default_desc"] = "EVET MİLLET, YİNE YILIN O ZAMANI GELDİ. SIRADAN İNSANLAR, BÜTÜN YIL GİYMEYİ DİLEDİKLERİ ÇILGIN KOSTÜMLERİ GİYEBİLİYOR! AMA BİZ SOYGUNCULARIN BÖYLE DERTLERİ YOK, DEĞİL Mİ? İSTEDİĞİMİZİ İSTEDİĞİMİZ ZAMAN GİYERİZ. YİNE DE BAYRAMIN HAVASINA KEMİKLİ BİR ŞIKLIKLA KATILMAKTA BİR SAKINCA YOK.$NL;$NL;YARATICI: LUKE MİLLANTA.",
["bm_suit_var_classyske_red_desc"] = "BÜTÜN YIL KÂBUS FABRİKASINDA YAŞAMAK MI İSTİYORSUN? BUYUR, DURMA. KAN SIÇRAMALARINDAN BİR TÜRLÜ UZAK DURAMAYAN SOYGUNCULAR İÇİN BU KIYAFET İŞ GÖRÜR. YALNIZ VAMPİRLERE VE BOĞALARA DİKKAT!$NL;$NL;YARATICI: LUKE MİLLANTA.",
["bm_suit_var_clown_2_default_desc"] = "BAIN’LE TANIŞMADAN ÖNCE, DALLAS SAKLANIP CHAINS’İN ATIŞ POLİGONUNU İŞLETMESİNE YARDIM EDERKEN YAŞAYAN EN BAŞARILI SOYGUNCU OLACAĞINI HİÇ DÜŞÜNMEMİŞTİ. AMA YILMADI, ÇİZGİSİNİ BOZMADI VE HÂLÂ DİMDİK AYAKTA. BU TAKIM BAZILARINA SAÇMA GÖRÜNEBİLİR AMA SOYGUNCU BİR PALYAÇO ONU GURURLA TAŞIYABİLİR.$NL;$NL;KONSEPT: ANGUSBURGERS.",
["bm_suit_var_clown_2_orange_desc"] = "SİLAH UZMANI, TATLI DİLLİ, HAZIRCEVAP BİR ŞAİR; CHAINS’İN PEK ÇOK MARİFETİ VAR. DALLAS, PAYDAY GANG’İN BEYNİYSE CHAINS DE KALBİDİR. SOYGUNCULUKTA ON YILI KUTLARKEN BU TAKIMI SEVGİYLE GİY!$NL;$NL;KONSEPT: ANGUSBURGERS.",
["bm_suit_var_clown_2_white_desc"] = "WOLF’UN ELİNDE OLSA BU TAKIMIN İÇİNİ MEMLEKETİ İSVEÇ’TEN GELEN YÜNLE KAPLARDI. AMA DC VE ÇOĞU SOYGUN YERİNİN HAVASI BUNU PEK KULLANIŞSIZ KILARDI. YİNE DE YAPSAYDI ADINI \"KAŞINAN PALYAÇO\" OLARAK DEĞİŞTİRMESİ GEREKEBİLİRDİ. BU DA PEK ŞIK DUYULMUYOR, DEĞİL Mİ?$NL;$NL;KONSEPT: ANGUSBURGERS.",
["bm_suit_var_clown_2_yellow_desc"] = "SHEFFİELD’DAN LONDRA’YA, KARANLIK ARKA SOKAKLARDA İŞ ÇEVİRDİĞİ İLK YILLARDAN BERİ HOXTON’IN KADERİNDE DAHA BÜYÜK İŞLER VARDI. PAYDAY GANG İLE ON YILDAN SONRA (PARMAKLIKLAR ARDINDAKİ O KÜÇÜK ARAYI SAYMAZSAK) BU PALYAÇONUN YILDIZI HÂLÂ YÜKSELİYOR. BU DA ONUN TAKIMI.$NL;$NL;KONSEPT: ANGUSBURGERS.",
["bm_suit_var_clown_black_and_white_desc"] = "SOL VE SAĞ, ÖLÜM VE YAŞAM, HAZ VE BÖLÜNMÜŞ BİR KİŞİLİKLE DOLAŞMANIN GETİRDİĞİ BİTMEK BİLMEZ ZİHİNSEL EZİYET. EH, EN AZINDAN TARTIŞACAK BİRİNİ HEP BULURSUN...",
["bm_suit_var_clown_black_desc"] = "BİR VARMIŞ BİR YOKMUŞ, NEŞELİ BİR HIRSIZ ÇETESİNİN ÜYESİ KÜÇÜK YAŞLI WOLF VARMIŞ. WOLF PEK ÖFKELİ, DENGESİZ BİR ADAMMIŞ; ŞİDDET NÖBETLERİ GEÇİRİR, KÜÇÜK YAŞLI KADINLARIN KILIĞINA GİRER, ALTIN İÇİN YANIP TUTUŞURMUŞ. BİR GÜN WOLF’UN AKLINA BİR FİKİR GELMİŞ. SİYAH KADİFE BİR TAKIM ÇALIP YEREL ÜNİVERSİTEDEKİ BİR DERSE SIZMAYA ÇALIŞMIŞ; SERVETİNDEN AYIRABİLECEĞİ BİR SÜRÜ ZENGİN OLACAĞINI DÜŞÜNMÜŞ. AMA NE YAZIK Kİ GİRERKEN BAHÇIVANA ÇATMIŞ. BAHÇIVAN ALARMI VERİNCE WOLF MAĞARASINA KAÇMAK ZORUNDA KALMIŞ.",
["bm_suit_var_clown_default_desc"] = "HİÇBİR YERDEN ÇIKIP ŞEHRE GELDİ. TANINMAYAN BİR PSİKOPAT. ADINI VEYA KÖKENİNİ KİMSE BİLMİYOR. SÖYLENTİYE GÖRE BİR GANGSTERİ KALEMLE ÖLDÜREN İLK KİŞİYMİŞ. ONUNLA KONUŞMA FIRSATI BULURSAN BU SÖYLENTİYE İNANIRSIN. PEKİ KIYAFETLERİ... BİR DELİNİN Mİ, YOKSA TİYATRO DEHASININ MI KIYAFETLERİ? KARAR SENİN.",
["bm_suit_var_clown_red_desc"] = "SOYGUNCU, KENDİSİNDEN ÖNCE NİCE ÜNLÜ HAYDUDUN GİYDİĞİ TAKIMI ÜZERİNE GEÇİRDİ. BÖYLESİNE KİŞİSEL BİR MASKEYLE, BİR PALYAÇO İÇİN BİLE BÜYÜK BEKLENTİLERDİ BUNLAR. AMA HAYAT ONU O KADAR ÇOK KEZ DÖVE DÖVE SİNDİRMİŞTİ Kİ BUNA HAZIRDI. PEKİ KİMDİ BU SOYGUNCU? NİŞAN ALAN POLİSLER İÇİN ANINDA HEDEF TAHTASINA DÖNÜŞECEK KADAR RENKLİ BİR TAKIM GİYMEYE KİM CESARET EDERDİ?",
["bm_suit_var_clown_white_desc"] = "DUKE’UN BİR ÜNİVERSİTE HOCASI HEP RENKLİ YELEK VE GÖMLEKLERLE BEYAZ TAKIM ELBİSE GİYERDİ. NADİR SANAT ESERLERİ ALIP ÜNİVERSİTE MÜZESİNE VEREN BÜYÜK BİR KAÇAKÇILIK AĞINA KARIŞTIĞI ORTAYA ÇIKINCA BİR TÜR AKIL HOCASINA DÖNÜŞTÜ. HABER DUYULDUĞUNDA SKANDAL BÜYÜDÜ; ÜNİVERSİTE NEREDEYSE BATTI. İYİ NİYETLİ AMA SON DERECE YASA DIŞI PLANLARI BOZULAN PROFESÖR KAYBOLDU VE BİR DAHA HABER ALINAMADI. DUKE BAZEN ANISINI YAŞATMAK İÇİN ONUNKİNE BENZEYEN BU TAKIMI GİYER. ",
["bm_suit_var_cyberhoodie_default_desc"] = "ELEKTRONİK MÜZİKLE KARANLIK İÇ İÇE.",
["bm_suit_var_cyberhoodie_mnt_desc"] = "SİBER YOLLARI HACKLERKEN KIPKIRMIZI YAN.",
["bm_suit_var_cyberhoodie_tgr_desc"] = "BU KAPÜŞONLUNUN RENGİ SARI OLABİLİR AMA CESARETİ TAM!",
["bm_suit_var_cyberhoodie_vpr_desc"] = "ORMANDA KAPÜŞONLU GİYMEN GEREKTİĞİ HÂLDE TARZINDAN ÖDÜN VERMEK İSTEMEDİĞİN ANLAR İÇİN.",
["bm_suit_var_cybertrench_default_desc"] = "MODERN GÖRÜNÜMÜ ESKİ USUL BİR TELEVİZYONLA BULUŞTURUYOR.",
["bm_suit_var_cybertrench_mnt_desc"] = "KENARLAR ALEV ALEV KALSIN.",
["bm_suit_var_cybertrench_tgr_desc"] = "SİYAH BİR EKRANIN ORTASINDAKİ ALTIN RENKLİ PİKSEL ÇİZGİSİ GİBİ.",
["bm_suit_var_cybertrench_vpr_desc"] = "ASİT GİBİ ÇARPICI BİR İZLENİM BIRAK.",
["bm_suit_var_desperado_blue_desc"] = "DALLAS SAHNEYE YÜRÜYÜP GİTARI SAHİBİNİN ELİNDEN KAPTI. GİTARCI İTİRAZ ETMEYE BAŞLADI AMA SOYGUNCUNUN SENİ-GEBERTECEĞİM BAKIŞI ONU SUSTURMAYA YETTİ. DALLAS SAPI SIKICA KAVRAYIP BARA YÖNELDİ; DERİ YELEKLİ BİR SERSERİ ORADA GENÇ BİR KIZI TACİZ EDİYORDU. KİMSE TEPKİ VEREMEDEN DALLAS GİTARI SERSERİNİN KAFASINDA PARÇALADI. ADAM ÇIĞLIKLARLA YERE DÜŞERKEN TAHTA KIYMIKLARI YÜZÜNDE DERİN YARIKLAR AÇTI. DALLAS GİTMEK ÜZERE DÖNDÜ, O SIRADA ORTADAKİ BİR İÇKİ ŞİŞESİNİ DE KAPIP KANLAR İÇİNDEKİ SERSERİYİ YERDE BAYGIN BIRAKTI. ŞÖVALYELİK ÖLDÜ DİYEN KİM?",
["bm_suit_var_desperado_default_desc"] = "RUST SALDIRGANIYLA YÜZ YÜZE DURUYORDU. İKİ ADAM DA RAKİBİNİN SİLAHININ NAMLUSUNA BAKIYORDU. GÜNEŞ ALINLARINA VURURKEN ZAMAN DURMUŞTU. RUST, SİLAH TUTAN AVUCUNDAKİ TERİ HİSSEDEREK TETİK PARMAĞINI DİKKATLE OYNATMAYA BAŞLADI. BİRDEN SİLAHŞORLARIN ARASINA BİR KARGA KONDU. İKİSİNE DE BAKTI; SANKİ SONRAKİ BİRKAÇ DAKİKADA KİMİN HAYATTA KALACAĞINA KARAR VERİYORDU. BAŞINI EĞİP RUST’A GAKLADI. RUST TETİĞİ ÇEKEREK RAKİBİNİN İŞİNİ BİTİRDİ.",
["bm_suit_var_desperado_green_desc"] = "SANGRES ÇOCUKKEN GEZGİN BİR MARİACHİ GRUBU KASABASINA GELMİŞTİ. TROMPETÇİYE HAYRAN KALAN SANGRES, CESARETİNİ TOPLAYIP YANINA GİTTİ; BİR GÜN NASIL MÜZİSYEN OLABİLECEĞİNİ SORDU. MARİACHİ DEDİ Kİ: \"ÇALIŞMALISIN KÜÇÜK ADAM. HER GÜN, BÜTÜN GÜN. HAYATIN, RUHUN, SEVGİLİN OLMALI.\" SANGRES HİÇ MARİACHİ OLMADI AMA FARKLI... KARİYERLERİ BOYUNCA MÜZİSYENİN ÖĞÜDÜNÜ AKLINDAN ÇIKARMADI.",
["bm_suit_var_desperado_red_desc"] = "SİLAHŞOR YERE DÜŞTÜ; SON NEFESİ ÇATLAMIŞ, KURU TOPRAKTAN KUM KALDIRDI. YAKINDAKİ BİR AKREP, ÖLÜŞÜNÜ KAYITSIZCA İZLEDİ. AKBABALAR TEPEDE DÖNMEYE BAŞLARKEN CESEDİN ÜZERİNE BİR GÖLGE DÜŞTÜ; TANINMAYAN BİRİ ÜSTÜNE EĞİLDİ. YIPRANMIŞ, KÖSELE GİBİ BİR EL UZANIP SİLAHŞORUN TABANCASINI ALDI. SOĞUK MAVİ GÖZLER AŞINMIŞ SİLAH ÇELİĞİNİ İNCELEDİ. GÖZLERİN SAHİBİ MEMNUNİYETLE DOĞRULUP YÜRÜDÜ, UFUKTA KAYBOLDU.",
["bm_suit_var_desperado_white_desc"] = "BİR YANINDA KILIFI, OMZUNDA GİTARIYLA YALNIZ BİR ATLI KASABAYA GİRDİ. BEYAZ TAKIMININ YIPRANMIŞ ETEKLERİ, TOZLU YOLLARDA UZUN BİR YOLCULUK ANLATTI. ATININ YANINDA, ADIMLARINA UYARAK BİR ÇAKAL YÜRÜYORDU; UZUN BACAKLARIYLA TOPRAĞA AĞIR AĞIR BASIYORDU. ADAM DÖKÜNTÜ BİR BARIN ÖNÜNDE DURUP SİLAHINI ÇEKTİ, AÇIK KAPIDAN İÇERİ NİŞAN ALDI. ATEŞ ETTİ. BİR ÇIĞLIK DUYULUNCA ÇAKAL İÇERİ FIRLADI. BİRKAÇ SANİYE SONRA SERSERİ GÖRÜNÜŞLÜ BİRİNİN CESEDİNİ SÜRÜKLEYEREK DÖNDÜ. ADAM ATTAN İNİP CANSIZ BEDENİ ATIN ARKASINA ATTI, ŞERİFİN OFİSİNE DOĞRU YOLA KOYULDU...",
["bm_suit_var_enforcer_suit_blood_desc"] = "EN POPÜLER SÜRÜMLERDEN BİRİ. SİYAH BEYAZ ASLA YANILTMAZ... YALNIZ BEYAZA KAN BULAŞTIRMA.",
["bm_suit_var_enforcer_suit_default_desc"] = "BU SÜRÜM DAHA SADE; KALABALIĞA KARIŞMAK İSTEDİĞİN ZAMANLAR İÇİN İDEAL.",
["bm_suit_var_enforcer_suit_dragon_desc"] = "ÖLÜM KALIM SAVAŞINA ŞIK GİTMEK İSTİYORSAN HER ZAMAN RESMİYETE BAĞLI KALABİLİRSİN.",
["bm_suit_var_enforcer_suit_red_dragon_desc"] = "İSTER ÖLÜMÜNE BİR DÜELLO, İSTER ŞİDDETLİ BİR ÇATIŞMA, İSTER ÖNEMLİ BİR PAZARLIK OLSUN; BU ÇEŞİT SENİ YARI YOLDA BIRAKMAZ.",
["bm_suit_var_esport_black_desc"] = "İLGİNÇ BİR BİLGİ: VLAD’IN YARI SARHOŞ HÂLDE KASA SATARAK HERKESİ NASIL ZENGİN EDECEĞİNİ BİTMEK BİLMEDEN ANLATTIĞI TOPLANTIDAN SONRA CHAINS ESKİ EŞOFMANINI ATIP BUNU ALDI.",
["bm_suit_var_esport_default_desc"] = "İLGİNÇ BİLGİ: DALLAS, SUÇ KARİYERİNİN BAŞLARINDA BAĞLI OLDUĞU CHİCAGO MAFYASI İLK KEZ BİRİNİ ÖLDÜRMESİNİ EMRETTİĞİNDE BU KIYAFETİ GİYİYORDU. HEDEFİN GENÇ BİR KADIN MUHBİR OLMASI İÇİNE SİNMEDİ. SONUNDA ÖRGÜTE İHANET ETMESİNE YOL AÇAN BUYDU.",
["bm_suit_var_esport_green_desc"] = "İLGİNÇ BİR BİLGİ: WOLF’UN, İSVEÇ’İN KUZEYİNDEKİ KİRUNA ŞEHRİNİN DIŞINDA, ORMANIN İÇİNDE BİR KÜTÜK EVİ VAR. YILDA BİR KEZ ORAYA DÖNÜP ORMANDA KOŞMAYA ÇALIŞIR. (WOLF KOŞUYA ÇIKTIĞINDA AYILARIN BİLE SAKLANDIĞI SÖYLENİR!)",
["bm_suit_var_esport_white_desc"] = "İLGİNÇ BİR BİLGİ: DALLAS SUÇ KARİYERİNE BAŞLARKEN HOUSTON, ATLANTA DIŞINDA CHAINS’İN SIK UĞRADIĞI BİR ATIŞ POLİGONU İŞLETİYORDU. DALLAS CHİCAGO’DA ÇALIŞTIĞI MAFYAYA İHANET EDİP SAKLANMAK ZORUNDA KALINCA HOUSTON ONU YANINA ALDI, POLİGONDAN İŞ YÜRÜTMESİNE İZİN VERDİ. BU, HOUSTON’IN HAYATINDA KENDİNİ AĞABEYİNDEN BAĞIMSIZ HİSSETTİĞİ TEK DÖNEMDİ.",
["bm_suit_var_esport_yellow_desc"] = "İLGİNÇ BİR BİLGİ: 90’LARDA HOXTON’IN HER GÜN FANATİKÇE ANTRENMAN YAPTIĞI KISA BİR DÖNEM VARDI. KOŞUYA ÇIKAR, AĞIRLIK KALDIRIR, ARA SIRA KRİKET BİLE OYNARDI. BU GEÇİCİ DELİLİK NÖBETİ ONA BİR SÜRELİĞİNE VİSKİ SEVGİSİNİ NEREDEYSE UNUTTURMUŞTU. NEREDEYSE.",
["bm_suit_var_gangstercoat_british_desc"] = "SADE VE AĞIRBAŞLI. AĞZININ KÖŞESİNDE BİR PURO VEYA PİPOYLA İYİ GİDER AMA UNUTMAYIN ÇOCUKLAR: SİGARA ÖLDÜRÜR.",
["bm_suit_var_gangstercoat_default_desc"] = "GÖSTERİŞSİZ AMA MESAJI AÇIK. BUNUN İÇİNDE KİMSE KÖTÜ GÖRÜNMEZ.",
["bm_suit_var_gangstercoat_french_desc"] = "PEMBE ELMAS PEŞİNDEYSEN VE ŞÜPHELİ BİR FRANSIZ AKSANIYLA KONUŞUYORSAN BU KUSURSUZ TAMAMLAYICIDIR. BÜYÜTEÇ İÇİN CEBİ BİLE VAR.",
["bm_suit_var_gangstercoat_irish_desc"] = "AZİZ PATRİCK GÜNÜ’NDE SOYGUN YAPMAK İÇİN MÜKEMMEL.",
["bm_suit_var_general_blue_desc"] = "SAVAŞA DA GEÇİT TÖRENİNE DE HAZIR. MEÇ AYRI SATILIR.",
["bm_suit_var_general_default_desc"] = "ZARİF VE OTORİTER BİR DURUŞ İÇİN.",
["bm_suit_var_general_red_desc"] = "SEN AYRILDIKTAN SONRA SAVAŞ ALANININ ZEMİNİYLE UYUMLU.",
["bm_suit_var_general_white_desc"] = "BUNUN KURU TEMİZLEME FATURASI OLDUKÇA KABARIK GELİR.",
["bm_suit_var_gentleman_default_desc"] = "GECEYE KARIŞIP GEÇMEK İSTEYEN SOYGUNCUYA SADE VE KOYU BİR GÖRÜNÜM...",
["bm_suit_var_gentleman_father_desc"] = "BU TAKIMIN GÖSTERİŞSİZ TONLARINI BEĞENMEK İÇİN DİNDAR, HATTA MANEVİYATA ÖNEM VEREN BİRİ OLMANA GEREK YOK.",
["bm_suit_var_gentleman_marine_desc"] = "SOYGUNDA DEVLET ADAMINA YARAŞIR BİR TAVIR GEREKTİĞİNDE ZARİF VE KASVETLİ BİR KIYAFET.",
["bm_suit_var_gentleman_veteran_desc"] = "KIRDA DA SİPERLERDE DE KAÇIŞ MİNİBÜSÜNÜN ARKA KOLTUĞUNDA DA YERİNİ YADIRGAMAZ.",
["bm_suit_var_gunslinger_casual_desc"] = "KUM TEPELERİNİN ARDINDAN GELDİĞİNİ KİMSE GÖRMEYECEK.",
["bm_suit_var_gunslinger_default_desc"] = "POSTA ARABASINI SOYARKEN ŞİŞKO ARABACIYA CİDDİ OLDUĞUNU GÖSTER.",
["bm_suit_var_gunslinger_piro_desc"] = "TAM ÖĞLE VAKTİ RAKİBİNİN 20 FİT KARŞISINDA DURURKEN TARZINI KONUŞTURMAK İSTEYEN SİLAHŞORA. (YA DA SADECE MATKABIN İŞİNİ BİTİRMESİNİ BEKLEYENE.)",
["bm_suit_var_gunslinger_red_desc"] = "SANA TERS BAKAN ADAMA KAÇ MERMİ SIKARSAN SIK, KOYU KIRMIZI CAN KANI BU TAKIMIN GÖRKEMLİ RENGİNE ERİŞEMEZ.",
["bm_suit_var_highinttech_blue_desc"] = "BU TAKTİK TAKIMIN GÖK MAVİSİ ÇEŞİDİ.",
["bm_suit_var_highinttech_default_desc"] = "BU TAKTİK KIYAFETİN NEREDEYSE TAMAMEN SİYAH ÇEŞİDİ.",
["bm_suit_var_highinttech_green_desc"] = "BU TAKTİK TAKIMIN BEYAZ ÇEŞİDİ.",
["bm_suit_var_highinttech_orange_desc"] = "BU TAKTİK TAKIMIN CANLI KIZIL ÇEŞİDİ.",
["bm_suit_var_hiphop_beige_desc"] = "ŞEHİRLİ KUNG FU USTASI ÇATILARDA İLERLERKEN SİRENLER ULUYORDU. ZAMAN DARALIYORDU. KALP ATIŞLARI KULAKLARINDA SABİT BİR RİTİM TUTUYOR, BEYAZ SPOR AYAKKABILARININ HER ADIMI RİTME EKLENİYORDU. ÖNÜNDE BİNALAR ARASINDA BÜYÜK BİR BOŞLUK VARDI. KARŞI TARAFTA, BİR BACADAN SARKAN, ALIP GETİRMESİ İÇİN GÖNDERİLDİĞİ ÖDÜL DURUYORDU. ATLAYIŞA HAZIRLANDI. TURNA USULÜ HAVALANMA ZAMANI...",
["bm_suit_var_hiphop_default_desc"] = "ÜÇ GANGSTER BOZUNTUSU, ARA SOKAKTA JIRO’NUN ETRAFINI SARDI. CÜZDANINI İSTERKEN IRKÇI HAKARETLER SAVURUYORLARDI. KENDİ BAŞLARINA VE BÜTÜN ÇETELERİNE NE KADAR BÜYÜK DERT AÇTIKLARINI BİR BİLSELERDİ. JIRO SABRETTİ. BAŞKA BİR YERDE OLMASI GEREKİYORDU; KENDİNE FAZLA GÜVENEN ÜÇ APTALIN KIÇINI TEKMELEMEKLE ZAMAN KAYBEDEMEZDİ. AMA NE YAZIK Kİ LAF ANLATILMIYORDU. BİRKAÇ DAKİKA SONRA JIRO ARA SOKAKTAN TEK BAŞINA ÇIKTI. GERİDE GANGSTER ÖZENTİLERİNİN CAN ÇEKİŞEN İNİLTİLERİ DUYULUYOR, KANLARI ASFALTLA KARIŞIP YAĞMUR SUYU MAZGALLARINA SÜZÜLÜYORDU...",
["bm_suit_var_hiphop_green_desc"] = "DÜNYA BÖYLE BİR SAVAŞ GÖRMEDİ. İKİ TARAF, SESLİ KİTLE İMHA SİLAHLARIYLA BİRBİRİNİ YOK ETMEYE HAZIR. METAL, HİP HOP’A KARŞI. NİHAİ HESAPLAŞMA. KİM KAZANACAKTI? ZEBRA TAYTLI GRUP MU, PANTOLONLARINI TERS GİYENLER Mİ?",
["bm_suit_var_hiphop_red_desc"] = "MARVİN GÜNLERDİR BİR ŞEY YEMEMİŞTİ. LANET OLASI SNOOPFATHER ÇETESİ EVİNİ BASMIŞ, SON PARASINI DA ALMIŞTI. ELBETTE PARA, ZEKİCE SAHTE BİR MARULUN İÇİNE GİZLENMİŞTİ. İNTİKAM ALMAYA KARARLI BİR HÂLDE SNOOPFATHER BÖLGESİNE İLERLERKEN MİDESİNDEKİ GURULDAYAN BOŞLUĞU DÜŞÜNÜYORDU...",
["bm_suit_var_hiphop_white_desc"] = "GARTH, KAYKAY SÜRERKEN BÖYLE BİR PANTOLON GİYMEYECEK KADAR AKILLIYDI. PAYDAY GANG İÇİN BİR İŞ YAPARKEN PANTOLONUNUN TEKERLEKLERE TAKILIP ONU DÜŞÜRDÜĞÜNÜ, KARŞIDAN GELEN TRAFİĞE SAVURDUĞUNU FALAN DÜŞÜNSENE; NE KÖTÜ GÖRÜNÜRDÜ!",
["bm_suit_var_hippie_abstraction_desc"] = "1960’LARIN SONLARINDA BİR ADAM DOĞDU. AKIL HOCASI OLACAK KİŞİYLE TANIŞANA DEK HAYATI KAOS, İHANET VE BELAYLA GEÇECEKTİ. AKIL HOCASI ONA BİR ŞEYLER ÖĞRETTİ, DÜNYANIN GERÇEKTE NASIL İŞLEDİĞİNİ ANLATTI. PEK AZ KİŞİNİN BİLDİĞİ, DUYULMAMIŞ SIRLARI AÇIĞA ÇIKARACAK BİR KİTAPTAN SÖZ ETTİ. ADAM BU BİLGİYİ ALIP HAYATINI YENİDEN ŞEKİLLENDİRDİ. SONUNDA TÜM ZAMANLARIN EN BÜYÜK SUÇ DEHALARINDAN BİRİ OLDU; KENDİSİNE HAKSIZLIK EDEN HERKESTEN İNTİKAM ALACAK, HALKIN ASLA HABERDAR OLMAYACAĞI EN BÜYÜK SOYGUNA GİRİŞECEKTİ...",
["bm_suit_var_hippie_default_desc"] = "CHAINS, GÖZ BEBEĞİ 1968 MODEL ÜSTÜ AÇIK OTOMOBİLİN GAZINI KÖKLEDİ. DEATH VALLEY’DEN GEÇEN OTOYOLDA TOZU DUMANA KATARKEN HIZINI SAATTE 88 MİLE ÇIKARDI. DEPODA YETERLİ BENZİN OLMASINI UMUYORDU. ARKADA HOXTON YÜKSEK SESLE HORLUYOR, AYAKLARININ DİBİNDE BOŞ BİR SEK MALT ŞİŞESİ YUVARLANIYORDU. DİKİZ AYNASINDA UZAKTA YANIP SÖNEN MAVİ IŞIKLAR YAKLAŞIYORDU. KAÇACAK YER YOKTU. CHAINS YAVAŞLAYIP HIZI 55’İN HEMEN ALTINDA TUTTU. IŞIKLAR YAKLAŞTI. EYALET DEVRİYE ARACI ARKALARINA GELİNCE MOTORUN KÜKREMESİNİN ÜSTÜNE SİREN SESİ DE EKLENDİ. CHAINS’İN ŞAŞKIN BAKIŞLARI ARASINDA POLİS ARABASI YANLARINDAN GEÇİP GİTTİ; BELLİ Kİ BAŞKA BİR AV ARIYORDU.",
["bm_suit_var_hippie_flowerpower_desc"] = "DUKE DALGIN DALGIN ESKİ AİLE FOTOĞRAFLARINI KARIŞTIRDI. VAY BE, 60’LAR VE 70’LER AİLESİNE MODA BAKIMINDAN HİÇ YARAMAMIŞTI! BABASININ TAM BÖYLE BİR KIYAFETİ VARDI. BELKİ BİR SOYGUNCUNUN ÜZERİNDE DAHA İYİ DURURDU?",
["bm_suit_var_hippie_native_desc"] = "KALABALIK SAHNEDEKİ ŞEYTANLARA ÇIĞLIK ATIYORDU. GICIRDAYAN GÜRÜLTÜ VE GERİ BESLEME DÖNGÜLERİNDEN DÖRT ULUYAN İBLİS. IŞIKLA SESTEN BİR ESRİME. ÖYLESİNE BÜYÜLENMİŞLERDİ Kİ SAHNE GÖREVLİSİNİN GRUBUN YEDEK EKİPMANLARINI ARABASINA DOLDURUP EN YAKIN ÇALINTI MAL ALICISINI BULMAK İÇİN GECEYE KARIŞTIĞINI KİMSE FARK ETMEDİ...",
["bm_suit_var_hippie_tribe_desc"] = "ODA DUMANLA DOLUYDU. SOLGUN GÜNEŞ KİRLİ CAMLARDAN GEÇİYOR, TOPLANANLAR İÇİN DANS EDER GİBİ GÖRÜNEN GÖLGELER DÜŞÜRÜYORDU. HERKES LIZARD KING’İN GELMESİNİ BEKLİYORDU. KAPI AÇILDI; IŞIĞIN ÖNÜNDE SİLUETİ BELİRDİ. BİR YANSIMA GÖZÜNÜN KENARINA ÇARPIP RETİNASINA DÖNDÜ, SÜRÜNGENİMSİ BİR PARILTI YARATTI. ÇÖLDE NE GÖRMÜŞTÜ?",
["bm_suit_var_jumpsuit_blue_desc"] = "BİR ZAMANLAR STEVE ADLI BİR DÜZENBAZ VARDI, CEBİNDE BİR PLAN SAKLARDI. DOST ÇETESİYLE BİR AKIM BAŞLATTI; PEK UZUN SÜRMEDİ. ŞAKADAN FAZLASI BİR BANKA SOYGUNUNDA, SIRADAN BOYACILARINKİNDEN DAHA HAVALI MAVİ TULUMLAR GİYDİLER. REHİNELERİ TUTUP OYUN OYNAMAYA ZORLADILAR; BİRİ ZEMİNİ PARÇALAYANA DEK. POLİS KAPIDAN GELMESİN DİYE UMUYORLARDI.",
["bm_suit_var_jumpsuit_brown_desc"] = "PAYDAY GANG BUGÜNE KADAR GÜNEY’DE PEK İŞ ALMADI; SINIRIN GÜNEYİNİ SAYMIYORUZ BİLE! AMA BU İLERİDE DEĞİŞİRSE DİYE LOCKE, TOZLU OVALARDA İYİ KORUMA SAĞLAYACAK BU TAKIMLARDAN BOL MİKTARDA STOKLADI.",
["bm_suit_var_jumpsuit_default_desc"] = "TEHLİKEYİ KÖŞEDE GÖRDÜĞÜNDE HAYATINDAKİ HER ŞEYİ BIRAKABİLECEK PEK AZ KİŞİ VARDIR. DALLAS GENÇLİĞİNDE BİR ZAMANLAR BUNU YAPABİLECEĞİNİ SANDI; NEREDEYSE HEM AKIL SAĞLIĞINA HEM ÖZGÜRLÜĞÜNE MAL OLUYORDU. O SIRADA BÖYLE BİR TULUM GİYİYORDU VE O GÜN ONU KURTARAN TEK ŞEY O OLDU.",
["bm_suit_var_jumpsuit_green_desc"] = "GÜVENLİ EVİN BİR YERİNDE, ARAMAYA ZAHMET ETME, CHAINS’İN DUYGUSAL DEĞER VERDİĞİ EŞYALARINI SAKLADIĞI BİR SANDIK VAR. İÇİNDE TIPKI BUNUN GİBİ BİR TULUM DA BULUNUYOR. ÖZEL GÜNLERDE ÇIKARIYOR VE NEDENSE ONU ÇOK KORUYOR. \"ÖDÜNÇ ALIRKEN\" YAKALANAN SOYGUNCULAR, YERİNDE BİR YUMRUKLA ÖDÜLLENDİRİLDİ.",
["bm_suit_var_jumpsuit_red_desc"] = "SOYGUNCULARIN LAKAPLARINI DÜNYA ŞEHİRLERİNDEN ALMASININ OLAYI NE? TESADÜF MÜ? TEMBELLER Mİ? HAYAL GÜÇLERİ Mİ YOK? YOKSA ESKİDEN BAIN’İN KURDUĞU, BİLİNMEYEN BÜYÜK BİR PLANIN PARÇASI OLAN DAHA BÜYÜK BİR ŞEY Mİ DÖNÜYOR? PEKİ SIRADA NE VAR, TEKSAS’TAKİ LUBBOCK’UN ADINI TAŞIYAN BİR SOYGUNCU MU? BELKİ TOKYO? BİRAZ AŞIRIYA KAÇIYOR, DEĞİL Mİ? BU AKIM NEREYE KADAR GİDEBİLİR? BÖLÜM 3’TE DE DEVAM EDECEK Mİ? ANLATACAK KADAR YAŞAYANLAR CEVABI ÖĞRENEBİLİR.",
["bm_suit_var_kungfumaster_black_desc"] = "BU TASARIM ZİHNİNİ BOŞALTIP ODAKLANARAK İŞİ BİTİRMEN GEREKEN ANLAR İÇİN.",
["bm_suit_var_kungfumaster_default_desc"] = "BAZI KLASİKLERİN MODASI ASLA GEÇMEZ!",
["bm_suit_var_kungfumaster_red_desc"] = "ELBETTE DİKKAT ÇEKERSİN AMA BU GÖRÜNÜM, NE OLURSA OLSUN DİRENİP SAVAŞMAYI SÜRDÜRMENİ SAĞLAR.",
["bm_suit_var_kungfumaster_white_desc"] = "BAZEN AZI KARAR. ÜSTELİK BUNU GİYDİĞİNDE ÜSTLERİNE ATILMANI HİÇ BEKLEMEYECEKLER.",
["bm_suit_var_leather_black_desc"] = "ORİJİNAL SİYAH VE PARLAK GÖRÜNÜM. BAZILARI HÂLÂ EN İYİSİNİN BU OLDUĞUNU SÖYLÜYOR.",
["bm_suit_var_leather_default_desc"] = "GÖSTERİŞSİZ, İNCE TONLAR VE KORİNT DERİSİ.",
["bm_suit_var_leather_red_desc"] = "HAFİF RUGAN KAPLAMALI KIRMIZI VE SİYAH.",
["bm_suit_var_leather_white_desc"] = "TERTEMİZ VE DİRİ; MORÖTESİ IŞIĞIN ALTINA ÇIKMAYA HAZIR. EN AZINDAN SİLAHLAR PATLAYANA KADAR.",
["bm_suit_var_leatherfluff_suit_default_desc"] = "NEREDEN GELDİĞİNİ ASLA UNUTMA.",
["bm_suit_var_lonorwa_blue_desc"] = "BU ÇEŞİT, AÇIK VE KOYU TONLARI İYİ HARMANLIYOR.",
["bm_suit_var_lonorwa_default_desc"] = "İŞTE KLASİK SÜRÜM BU. GERÇEKTEN KENDİNİ BELLİ EDEN.",
["bm_suit_var_lonorwa_orange_desc"] = "BİRAZ DAHA İŞLEVSEL BİR GÖRÜNÜMDEN ZARAR GELMEZ.",
["bm_suit_var_lonorwa_white_desc"] = "KIŞ TARLALARINDA GÖRÜNMEZ OLMAK MI İSTİYORSUN? BU ÇEŞİT TAM SANA GÖRE.",
["bm_suit_var_lowinttech_blue_desc"] = "PRATİK AMA RAHAT BU TAKIMIN MAVİ ÇEŞİDİ.",
["bm_suit_var_lowinttech_default_desc"] = "BU KULLANIŞLI VE RAHAT TAKIMIN SİYAH ÇEŞİDİ.",
["bm_suit_var_lowinttech_red_desc"] = "BU KULLANIŞLI VE RAHAT TAKIMIN KIRMIZI ÇEŞİDİ.",
["bm_suit_var_lowinttech_yellow_desc"] = "BU KULLANIŞLI VE RAHAT TAKIMIN BEYAZ ÇEŞİDİ.",
["bm_suit_var_mariachi_black_desc"] = "KANUN KAÇAĞI, ÖLMÜŞ SEVGİLİSİNİN MUMYALANMIŞ BEDENİNİ SÜSLEYEN BUKETTEN BİR GÜL ALDI. ONUN CANINI ALAN KARTEL ÜYESİNDEN İNTİKAM ALMAYA YEMİN ETTİ. KAYBININ HESABINI SORARKEN GİYECEĞİ TAKIMIN ÜZERİNE, SEVGİLİSİNİN ANISINA BU GÜLÜ İŞLETTİ.",
["bm_suit_var_mariachi_brown_desc"] = "ASKERLİKTEN DÖNDÜKTEN SONRA CHAINS’İN KAYBOLACAĞI, BİR SÜRE GÖZDEN UZAK KALACAĞI BİR ŞEHRE İHTİYACI VARDI. BİRİSİ SAN FRANSCİSCO’NUN BUNA HARİKA OLDUĞUNU SÖYLEDİ AMA ORADAKİ GRUNGE GRUPLARINI DÜŞÜNMEMİŞTİ. CHAINS’İN GRUNGE GRUPLARINI NE KADAR ÇOOOK SEVDİĞİNİ HEPİMİZ BİLİYORUZ, DEĞİL Mİ? ÖZELLİKLE BERBAT OLANLARI. EVET, CHAINS SF’DE FAZLA KALMADI. BİRAZ GÜNEYE GİTTİ VE KADER BAŞKA PLANLAR GÖSTERMEDEN ÖNCE MEXİCO CİTY’DEKİ MARİACHİ FESTİVALİNDE KISA SÜRE DUBLÖRLÜK YAPTI. BUGÜNE DEK KİMSE ONA CORRİDO SEVİP SEVMEDİĞİNİ SORMADI...",
["bm_suit_var_mariachi_default_desc"] = "WOLF, EN SEVDİĞİ GRUBUN SON ALBÜMÜNÜ SATIN ALMAYA (GERÇEKTEN PARA ÖDEYEREK ALMAYA) KESİN KARARLI BİR ŞEKİLDE PLAKÇIYA GİRDİ. KAPI ARKASINDAN KAPANINCA YÜZÜNDEN NADİREN GÖRÜLEN BİR DEHŞET GEÇTİ. ORTALIKTA TEK BİR 12 İNÇLİK KARTON PLAK KILIFI BİLE YOKTU! HOMURDANARAK TEZGAHTAKİ EŞOFMANLI DİNGİLE YÜRÜYÜP YAKASINA YAPIŞTI. SAKALININ ALTINDAN \"LANET PLAKLAR NEREDE?\" DİYE HIRLADI. ZAVALLI ADAM CD’LERİN PLAKTAN ÜSTÜN OLDUĞUNA DAİR BİR ŞEYLER GEVELEDİ. BUNUN ÜZERİNE WOLF RAFLARDAKİ \"ÜSTÜN\" PLASTİK DİSKLERE BİR SÜRÜ DELİK AÇTI...",
["bm_suit_var_mariachi_red_desc"] = "SÖYLENTİLER, KARMAŞIK AĞINA RÜZGÂR VURDUĞUNDA ÜRPERTİCİ BİR ULUMA ÇIKARAN ÖLÜMCÜL BİR ÇÖL ÖRÜMCEĞİNİ ANLATIR. KİMİLERİ AĞIN SİLAHLI ÇATIŞMALARDA ÖLEN BÜTÜN KAYIP RUHLARIN AĞITLARINI TUTTUĞUNU, KİMİLERİYSE DÜNYANIN BUGÜNKÜ HÂLİNİ KINAYAN KADİM MAYA TANRILARININ ÖFKELİ SESLERİNİ ÇAĞIRDIĞINI SÖYLER.",
["bm_suit_var_mariachi_white_desc"] = "BU TAKIMIN YUMUŞAK PAMUKLU KUMAŞININ BİR HİKÂYESİ VAR. DOKUYAN ADAM, ÖLMÜŞ KIZININ ANISINA ÖLÜLER GÜNÜ’NDEN ÖNCE BİTİREBİLMESİ İÇİN BEKLEYEN TERZİYE ZAMANINDA ULAŞMAK ÜZERE KATIR SIRTINDA BEŞ GÜN YOL GİTTİ. AZICIK YİYECEĞİNİ VE SUYUNU YÜK HAYVANIYLA PAYLAŞIP ZORLU YOLLARLA, FIRTINALARLA, HAYDUTLARLA SAVAŞTI; SONUNDA VARACAĞI YERE ULAŞTI. ARDINDAN GELEN KUTLAMALARDA DOKUMACI, HAVADA KIZININ KAHKAHASINI DUYDUĞUNA YEMİN ETTİ.",
["bm_suit_var_miami_black_desc"] = "SOYGUNCULAR AĞLAMAZ VE ÇOK AZI RİMEL SÜRER. AMA HEMEN HERKESİN İÇİNDEKİ GİZLİ GOTİK RUHU BİR ARA DOYASIYA YAŞADIĞI DÜŞÜNÜLEBİLİR. YA DA BELKİ ÖYLE DEĞİLDİR. BELKİ SADECE RENKLERİ BİRBİRİYLE UYUMLU SEÇMEKLE UĞRAŞMAK İSTEMİYORLARDIR.",
["bm_suit_var_miami_default_desc"] = "BİR KERESİNDE SANGRES, BREZİLYA İLE MEKSİKA ARASINDA UÇAKLA ÇALINTI SİLAH TAŞINMASINA EŞLİK EDİYORDU. BU TAKIMI GİYEN ORTAĞI UÇUŞ SIRASINDA ONA İHANET ETTİ. KISA BİR BOĞUŞMANIN ARDINDAN SANGRES ONU KARGO KAPISINDAN DIŞARI TEKMELEDİ. ARTIK ESKİ OLAN ORTAĞI KOLLARINI ÇILGINCA SAVURUP ÇIĞLIKLARLA DÜŞERKEN SANGRES, TAKIMIN MAVİSİNİN PARLAK MAVİ GÖKYÜZÜNDE NE KADAR İYİ KAMUFLAJ OLDUĞUNU FARK ETMEDEN EDEMEDİ. SONRA YERE \"ŞLAP\" DİYE ÇARPTI VE GÖRÜNTÜ BOZULDU.",
["bm_suit_var_miami_grey_desc"] = "JIMMY, BU TAKIMIN FLORİDA EVERGLADES’DE TİMSAHLARDAN KAÇINMAK İÇİN HARİKA KAMUFLAJ OLDUĞUNA HÂLÂ İNANIYOR. HOXTON ONU DENEMEYE KIŞKIRTTI; HAKLI ÇIKARSA 20.000 $ VERECEĞİNİ SÖYLEDİ. HENÜZ YAPMADI AMA SIĞINAKTA BİRİ KONUYU HER AÇTIĞINDA GEÇİŞTİRİP \"YAKINDA DOSTUM, BELKİ YARIN\" DİYOR.",
["bm_suit_var_miami_pink_desc"] = "RUST, TEKSAS’IN DİNG DONG KASABASINDA YEREL OVERKİLL MC ŞUBESİNE KEŞİF YAPARKEN İDDİAYA GİRİP BİR KEZ BU TAKIMI GİYDİ. YEREL BARA GİRİNCE BİR SÜRÜ TUHAF BAKIŞ TOPLADI AMA TEK KİŞİ BİLE LAF ETMEYE VEYA SORUN ÇIKARMAYA CESARET EDEMEDİ. BİR ADAM TEKSAS’TA BÖYLE BİR TAKIMLA DOLAŞIYORSA DÜNYA ONUN HİÇBİR ŞEYDEN KORKMADIĞINI BİLİR!",
["bm_suit_var_miami_white_desc"] = "SÖYLENTİYE GÖRE MİAMİ POLİS DEPARTMANI’NIN ARŞİVLERİNDE BİR YERDE, DALLAS’I BÖYLE BİR TAKIM GİYMİŞ, ÜSTÜ AÇIK BİR FALCOGİNİ MODEL F SÜRERKEN GÖSTEREN BİR FOTOĞRAF VAR. ELBETTE BU SADECE BİR SÖYLENTİ. DALLAS YANINDA BAHSEDERSEN HER ŞEYİ İNKÂR EDER. ÜSTELİK KONU HER AÇILDIĞINDA KİMLİĞİ BELİRSİZ BİRİ, ARŞİVLERİN BULUNDUĞU KARAKOLUN BODRUMUNU SU BASMASINA YOL AÇARAK, YAKARAK, HAVAYA UÇURARAK VEYA BAŞKA BİR YOLDAN YOK ETMEYE ÇALIŞIR...",
["bm_suit_var_peacoat_black_desc"] = "ÜNLÜ BİR ÖDÜL AVCISI BİR ZAMANLAR BÖYLE BİR CEKETİ ON YIL BOYUNCA HER GÜN GİYERDİ. CRİMENET KURULMADAN ÇOK ÖNCE YILLARCA BAIN’İN PEŞİNİ BIRAKMADI. SONUNDA AVCININ ŞANSI TÜKENİP BAIN TARAFINDAN İNDİRİLDİĞİNDE BAIN CEKETİ HATIRA OLARAK SAKLADI.",
["bm_suit_var_peacoat_blue_desc"] = "SOKOL BİR ZAMANLAR DMİTRİ ADLI BİR İNŞAAT İŞÇİSİ TANIYORDU. HER HAFTA AYNI BARDA BİRLİKTE HOKEY İZLERLERDİ. BU PALTO SOKOL’A O GÜNLERİ HATIRLATIYOR; DMİTRİ’NİN DE AYNISINDAN VARDI. AĞIR ÇALIŞMADAN KİR VE TOZ LEKELERİYLE DOLU, KENARLARI AŞINMIŞ VE SAÇAKLANMIŞTI. AMA GURURLA GİYERDİ; HER KÜÇÜK LEKE, EMEKLE GEÇEN ONURLU BİR HAYATIN HİKÂYESİNİ ANLATIRDI. ",
["bm_suit_var_peacoat_brown_desc"] = "V8 MOTORLU ÜSTÜ AÇIK OTOMOBİL, EN AZ ON POLİS ARACININ TAKİBİNDE OTOYOLDA KÜKRERKEN GÜNEŞ IŞIĞI KOYU YEŞİL BOYASINDA PARLIYORDU. SAN FRANCISCO’NUN KALABALIK SOKAKLARINDA SAĞA SOLA KIVRILDILAR. SÜRÜCÜNÜN ENSESİNDEN SÜZÜLEN TEK BİR TER DAMLASI, DİKKATİNİ MEŞHUR LOMBARD STREET’TE KALDIRIMA ÇARPMASINA YETECEK KADAR DAĞITTI. POLİSLER HÂLÂ PEŞİNDEYKEN ARABADAN İNİP KOŞTU. SONRA TAM OLARAK NE OLDUĞUNU KİMSE BİLMİYOR AMA SÖYLENTİYE GÖRE CHİNATOWN’DA İZİNİ KAYBETTİRDİ. GÖRDÜKLERİ SON ŞEY, KALABALIĞIN İÇİNDE KAYBOLURKEN KAHVERENGİ PALTOSUNUN PARILTISIYDI.",
["bm_suit_var_peacoat_default_desc"] = "UZUN ZAMAN ÖNCE SUÇ DÜNYASINDA KARANLIK BİR GÖLGE DOLAŞIYOR, EN AŞAĞILIK MAFYA ÜYELERİNİ ANLATILAMAZ ŞİDDET EYLEMLERİYLE BİRER BİRER ÖLDÜRÜYORDU. AMERİKA’NIN SUÇ BARONLARINI KORKU SARDI; İNTİKAMIN NE ZAMAN GELECEĞİNİ KİMSE BİLMİYORDU. ÇOK AZ KİŞİ BU GEZGİN DEHŞETİ BİR ANLIĞINA GÖREBİLDİ AMA TEK BİR İBLİS Mİ YOKSA BİRDEN FAZLA MI OLDUĞUNU SÖYLEYEMEDİ. GELEN TEK TARİF ÖLÜMÜN GİYDİĞİ KIYAFETTİ. TIPKI BUNUN GİBİYDİ.",
["bm_suit_var_peacoat_white_desc"] = "MAFYA BABASI, RAKİP ÇETENİN KANLI SONUNU EMRETMEKLE GEÇEN BİR HAFTANIN ARDINDAN AİLESİYLE GÜZEL BİR YEMEK YEMEYE HAZIR HÂLDE RESTORANA GİRDİ. O ÇETENİN TEK SAĞ KALANININ BANYODA BEKLEDİĞİNDEN HABERSİZDİ. MAFYA BABASI PALTOSUNU ÇIKARAMADAN ADAM SIRTINA BİR KURŞUN SIKIP KAN DAVASINI SONSUZA DEK BİTİRDİ.",
["bm_suit_var_poolrepair_default_desc"] = "DOĞRU KADIN VEYA ERKEĞİN ÜZERİNDE BU KIYAFET, ÇARESİZ BİR EV SAHİBİNİN AKLINI ARKADAŞLARININ BODRUM KASASINI BOŞALTMASINA YETECEK KADAR BAŞINDAN ALIR.",
["bm_suit_var_puffervest_suit_default_desc"] = "O DENİZ MELTEMİNİ HİSSET!",
["bm_suit_var_punk_billieboy_desc"] = "UYUM. KORKAKÇA BOYUN EĞME HER AN ETRAFIMIZI SARIYOR. BİR TUĞLA YIĞINI GİBİ HER BİREYİN ZİHNİNE AĞIRLIK YAPIP ONU KABULLENMEYE ZORLUYOR. TABİİ ASİ BİR ÇIĞLIK ATIP YUMRUĞUNU HAVAYA KALDIRMADAN DURAMAYANLARDANSAN BAŞKA. BİR BANKAYA BUNU GİYEREK GİREN SOYGUNCU, DÜNYAYA HİÇBİR ŞEYDEN KORKMADIĞINI GÖSTERİR!",
["bm_suit_var_punk_blue_desc"] = "NEW YORK’TAKİ HER MÜZİSYEN 1983’ÜN MEŞHUR \"MÜZİK DÜKKÂNI SOYGUN SERİSİNİ\" BİLİR. HİKÂYEYE GÖRE JACKET, ÇILGIN SOYGUNCULUK KARİYERİNDEN ÖNCE BİR PUNK GRUBUNDAKİ ARKADAŞLARIYLA DOLAŞIYOR, BİRA VE UYUŞTURUCU KARŞILIĞINDA SAHNE İŞLERİNE YARDIM EDİYORDU. BİR GECE GÖSTERİDEN HEMEN ÖNCE ŞARKICININ EN SEVDİĞİ GİTARIN SOL TELİ KOPTU. ADAM SIRADAN TELLE YETİNMEYİP ÖZEL MARKA İTHAL DÜZ SARIM TELLERİNİ İSTERKEN BÜTÜN DÜKKÂNLAR KAPALIYDI. JACKET YENİ TEL BULMAK İÇİN BİRAZ... YARATICI... OLMAK ZORUNDA KALDI. GÖSTERİYE BEŞ DAKİKA KALA BULDU.",
["bm_suit_var_punk_default_desc"] = "SYDNEY, SON SOYGUNU KUTLAMAK İÇİN SIĞINAKTA PARTİ VERİLEN BİR GECE İDDİAYA GİRİP SAÇINI PARLAK TURUNCUYA BOYAMIŞTI. VLAD DA ORADAYDI; HER ZAMANKİ GÖSTERİŞLİ, ERKEK ŞOVENİSTİ TAVIRLARIYLA DOLANIYORDU. SYDNEY’NİN SAÇINI GÖRÜNCE KENDİNİ TUTAMAYIP RUSÇA \"FAZLA OLGUN BİR HAVUÇ\" HAKKINDA BİR YORUM YAPTI. ŞANSSIZLIĞINA, SYDNEY NE DEDİĞİNİ GERÇEKTEN ANLADI. BİR SÜRE SONRA BANYODA KANAYAN BURNUYLA İLGİLENİRKEN KENDİ KENDİNE GÜLDÜ VE BİR DAHA SYDNEY’NİN SAÇ RENGİNE YORUM YAPMAMAYA KARAR VERDİ. \"YİNE DE\" DİYE DÜŞÜNDÜ, \"BUNA FENA HÂLDE DEĞDİ!\"",
["bm_suit_var_punk_red_desc"] = "LİVERPOOL’DA BİR GECE CLASH KONSERİNDEN DÖNEN HOXTON, GECENİN EN SEVDİĞİ ŞARKISINI MIRILDANARAK BİR ARA SOKAĞA GİRDİ. BÜYÜK ÇÖP KUTUSUNUN ARKASINDAN BIÇAK SALLAYAN İKİ DAZLAK ÇIKTI. BOZUK GİTAR RİFFLERİNİN DOĞAL SARHOŞLUĞUNDAKİ HOX, UZATILAN BIÇAKLARI UMURSAMADAN HOLİGANLARI PATAKLADI. SONRA DA ONLARI SAKLANDIKLARI ÇÖP KUTUSUNA ATTI; BÜTÜN BUNLARI YAPARKEN EN SEVDİĞİ ŞARKIYI MIRILDANMAYI SÜRDÜRÜYORDU...",
["bm_suit_var_punk_scottish_desc"] = "PUNK BİR ZAMANLAR AHLAK PANİĞİNE KAPILAN EBEVEYNLERİN KÂBUSU, GEÇİCİ KONSER MEKÂNINA ÇEVRİLEN PEK ÇOK METRUK DEPONUN DA KURTARICISIYDI. DRAGAN, 1980’LERDE BİR AKŞAM BİR İŞ BAĞLANTISIYLA BULUŞMAK İÇİN LONDRA DOCKLANDS’DEKİ, KÖTÜ ŞÖHRETLİ YEDİ GÜNLÜK \"DEADWEEK\" MOHİKAN SAÇ PARTİSİNE GİTTİ. BAĞLANTI HİÇ GELMEDİ VE DRAGAN ONDAN BİR DAHA HABER ALAMADI. BUGÜN BİLE NE OLDUĞUNU HÂLÂ BİLMİYOR.",
["bm_suit_var_rusbear_arctic_desc"] = "BUNUNLA KARLI ARAZİDE GERÇEKTEN İYİ KAMUFLE OLURSUN.",
["bm_suit_var_rusbear_blacmor_desc"] = "BU ÇEŞİT GECE SOYGUNLARI İÇİN KUSURSUZ.",
["bm_suit_var_rusbear_default_desc"] = "DİKKAT ÇEKEBİLİRSİN AMA EN AZINDAN KAN LEKELERİ BELLİ OLMAZ... O KADAR DA OLMAZ.",
["bm_suit_var_rusbear_quilt_desc"] = "DENİZE Mİ AÇILIYORSUN? NEDEN UYGUN BİR RENK GİYMEYESİN?",
["bm_suit_var_t800_cowboy_desc"] = "AT ÜSTÜNDE GELDİ; ZORLU BİR SOYGUN GÜNÜNÜN ARDINDAN GÖZÜNÜ YEREL SALONA DİKMİŞ SOYGUNCU KADIN.",
["bm_suit_var_t800_default_desc"] = "İSTER ZAMAN YOLCULUĞU YAPAN BİR ÖLÜM MAKİNESİ OL İSTER SONRAKİ SOYGUNUNU YAPARKEN 1950’LERİN GREASER RUHUNU YAŞATMAYA ÇALIŞAN SIRADAN BİRİ; BU TAKIM SENİ KOLLUYOR.",
["bm_suit_var_t800_red_desc"] = "KIRMIZI DERİNİN İDDİALI GÖRÜNÜMÜYLE KÖTÜ ŞÖHRETİNİ GÖSTER.",
["bm_suit_var_t800_toughboy_desc"] = "BU SİYAH BEYAZ BİRLEŞİMİ MUHTEMELEN ÇAMURDA YUVARLANMAYI SEVMEYEN SOYGUNCULARA DAHA UYGUN.",
["bm_suit_var_texvest_default_desc"] = "TAŞRA ŞIKLIĞI.",
["bm_suit_var_xmas_tuxedo_black_desc"] = "MOTOSİKLETİ BOZULMUŞTU. ISSIZLIĞIN ORTASINDA KALMANIN TAM ZAMANIYDI. SIĞINAKTAKİ NOEL PARTİSİNİ KESİN KAÇIRACAKTI. BU YIL RUST’A JIRO’NUN SAKE YUMURTALI KOKTEYLİNDEN YOKTU. KAHRETSİN. ÇANTASINI ALIP YÜRÜMEYE BAŞLADI. GÜNEŞ KARLI MANZARANIN ÜZERİNDE BATIYORDU. DÖKÜNTÜ BİR ÇİFTLİK EVİNİN YANINDAN GEÇERKEN İÇERİDEN YÜREK BURKAN BİR ÇIĞLIK GELDİ. RUST DURAKSADI. ONUN İŞİ DEĞİLDİ. AMA BİR ŞEY FİKRİNİ DEĞİŞTİRDİ. PENCEREDEN YERDE BİRİNİ GÖRÜP İÇERİ KOŞTU; AĞACINI SÜSLERKEN DÜŞMÜŞ YAŞLI BİR KADIN BULDU. KALKMASINA YARDIM EDİP YARALARIYLA İLGİLENDİKTEN SONRA ÇAYA KALDI. MEĞER AHIRDA HÂLÂ ÇALIŞAN KLASİK BİR MOTOSİKLET VARMIŞ, ÖDÜNÇ ALABİLİRMİŞ. BELKİ O PARTİYİ KAÇIRMAYACAKTI...",
["bm_suit_var_xmas_tuxedo_blue_desc"] = "SYDNEY ARA SOKAKTAN BAŞINI UZATIP MAVİ KIRMIZI IŞIKLARI YANIP SÖNEN, SİRENİ ULUYAN POLİS ARABASININ GEÇİŞİNİ İZLEDİ. TAŞIDIĞI GANİMET DOLU ÇANTAYI DÜZELTTİ, TELEFONUNU ÇIKARIP ARADI. HATTIN ÖTEKİ UCUNDAN \"EVET?\" DİYEN BİR SES GELDİ. \"BENİM. 34. SOKAĞIN KÖŞESİ. ORTALIK TEMİZ, BURAYA GEL\" DİYE YANITLAYIP KAPATTI VE BEKLEDİ. RÜZGÂR UĞULDUYOR, KAR SOKAKTA SAVRULUYORDU; O KARANLIĞA BAKIP ENDİŞEYLE HOMURDANIYORDU. BİRKAÇ DAKİKA SONRA BİR MİNİBÜS YANAŞTI. ŞOFÖR İNİP SELAM VERDİ. \"PAKET NEREDE?\" ARA SOKAĞA GİRDİLER. SYDNEY, ÜZERİNDE YAVRULARINI EMZİREN BİR KÖPEĞİN YATTIĞI KUTU YIĞININI GÖSTERDİ. KOCAMAN BİR DESTE PARA ÇIKARIP ŞOFÖRE UZATTI. \"NE YAPACAĞINI BİLİYORSUN DOSTUM.\" ŞOFÖR PARAYI ALIP YANITLADI: \"TAMAMDIR, MERAK ETME. GÜVENDE OLMALARINI SAĞLAYACAĞIM.\"",
["bm_suit_var_xmas_tuxedo_default_desc"] = "KARLI ORMANDA TEK BAŞINA DURAN KÜÇÜK KULÜBENİN TAŞ BACASINDAN DUMAN YÜKSELİYOR. ORTALIK SESSİZ; YALNIZCA KIŞ UYKUSUNDAKİ AĞAÇLARIN KURU DALLARININ AYAZ RÜZGÂRDA HIŞIRTISI DUYULUYOR. UZAKLARDA BİR YERDE GEYİK AİLESİ ISINMAK VE YIRTICILARDAN KORUNMAK İÇİN BİR MAĞARADA TOPLANIYOR. AMA BU GECE WOLF YİYECEK PEŞİNDE DEĞİL. KULÜBESİNDE ATEŞİN BAŞINDA YALNIZ OTURUYOR; ELİNDE SOĞUK BAL ŞARABIYLA SOYGUNCULUĞU BOYUNCA YAŞADIĞI HER ŞEYİ DÜŞÜNÜYOR.",
["bm_suit_var_xmas_tuxedo_green_desc"] = "DUKE BU TATİL ARİFESİNDE BİR KADEH FAZLA BRENDİ İÇMİŞTİ. HOXTON’IN HEDİYE ETTİĞİ ANTİKA İNGİLİZ REVOLVERİNİ YENİDEN BİRLEŞTİRMEYE ÇALIŞIRKEN BAŞI DÖNÜYORDU. KEDİLERİNDEN BİRİ MASANIN YANINDAKİ TABUREDE DİKKATLE İZLİYORDU. YÜKSEK BİR \"FOİNG\" SESİYLE TETİK YAYI ODANIN ÖBÜR UCUNA UÇTU; KEDİ PEŞİNE FIRLADI. İKİSİ DE GÜVENLİ EVİN NOEL AĞACININ DALLARINDA KAYBOLDU VE AĞAÇ DEVRİLDİ. ÜST KAT KORKULUĞUNDAN AŞIP BÜYÜK GÜRÜLTÜYLE AŞAĞI DÜŞTÜ. ARDINDAN BİR \"AAARGH!\" VE \"YUKARIDA NE HALT OLUYOR?\" BAĞIRTISI GELDİ. BİRKAÇ DAKİKA SONRA CHAINS, BAŞINDA NOEL BABA ŞAPKASI VE ELİ YÜZÜNDE, MERDİVENLERİ ÖFKEYLE ÇIKTI. PEK MUTLU DEĞİLDİ. ELİNİ ÇEKİNCE KOCAMAN, ŞİŞMİŞ, BELLİ BİR REN GEYİĞİNİNKİ KADAR KIPKIRMIZI BİR BURUN GÖRÜNDÜ. SANKİ DÜŞEN AĞACIN GÖVDESİ ÇARPMIŞ GİBİ...",
["bm_suit_waistcoat_desc"] = "GÜÇLÜ VE PROFESYONEL BİR HAVA YAYMAK İSTİYORSAN BU KIYAFET İŞİNİ FAZLASIYLA GÖRÜR.",
["bm_suit_winter_suit_desc"] = "ASKERÎ KIŞ KAMUFLAJLI TAM BİR TAKIM. AMAÇ KARDA GÖRÜNÜRLÜĞÜ AZALTMAK.",
["bm_suit_xmas_tuxedo_desc"] = "NOEL ÖNCESİ SOYGUNDU. KASANIN İÇİNDE TEK BİR KİLİT PİMİ BİLE OYNAMIYORDU; BÜTÜN SUÇ LOCKE’TAYDI. MATKAPLARI ÇANTALARA ÖZENLE KOYMAYI UNUTMUŞ, SOYGUNCULAR ORAYA VARANA KADAR DA FARK ETMEMİŞTİ. TWITCH MİNİBÜSTE RAHATÇA BEKLERKEN JIMMY SIRF YAPABİLDİĞİ İÇİN BİR PENCERE KIRDI. HADİ CLOVER! HADİ SANGRES! JACKET VE WICK, SİZ DE! TEK BİR SOYGUNCU BİLE VLAD’IN KAYINBİRADERİNİN GERÇEKTEN SAİNT NİCK OLDUĞUNA İNANMIYORDU.",
