["bm_wpn_prj_hur_desc"] = "KESKİN BİR BALTA HER ZAMAN İŞE YARAR. BU BALTA DA ÖZELLİKLE FIRLATMAYA UYGUN OLDUĞU İÇİN MOTORCULAR ARASINDA POPÜLER OLDU. MOTOSİKLET SÜRMEK BAZEN TEHLİKELİDİR; BİRAZ \"KORUNMAYA\" İHTİYAÇ DUYARSIN. BÖYLECE MOTORCULAR ONU OTOYOL KAVGALARINDA ÇOK KULLANIŞLI BULUNCA BU SPOR BALTASININ STOKLARI BİRDEN TÜKENDİ.",
["bm_wpn_prj_jav"] = "CİRİT",
