["btf_cs1_01_05"] = "ELBETTE EFENDİM, HİÇ SORUN DEĞİL. HEPSİNİ 20'LİKLER HÂLİNDE İSTER MİSİNİZ?",
["btf_cs1_01_06"] = "YARDIMCI OLABİLECEĞİM BAŞKA BİR KONU VAR MI HANIMEFENDİ? TAŞIT KREDİSİ DÜŞÜNÜR MÜSÜNÜZ?",
["btm_cs1_01_01"] = "SİZE YARDIM ETMEKTEN MEMNUN OLURUM. BİR SANİYE LÜTFEN.",
["btm_cs1_01_02"] = "ŞURAYI, ŞURAYI, ŞURAYI... ŞURAYI VE ŞURAYI İMZALARSANIZ. BİR DE ŞURAYI.",
["btm_cs1_01_03"] = "İYİ GÜNLER HANIMEFENDİ. BUGÜN SİZE NASIL YARDIMCI OLABİLİRİM?",
["btm_cs1_01_04"] = "ROBERTS BANK SİZE YARDIM ETMEKTEN MEMNUNİYET DUYAR EFENDİM.",
["btm_cs1_01_05"] = "BUNU YAPABİLİRİM HANIMEFENDİ.",
["btm_cs1_01_06"] = "BUNUN İÇİN KİLİTLİ POŞET İSTER MİSİNİZ EFENDİM? SADECE BİR BUÇUK DOLAR.",
["bul_fex_26c_01"] = "DOSTLARIM, O RUS İÇİN NE DİYE ÇALIŞIYORSUNUZ? BENİ BIRAKIN. KARŞILIĞINI ALIRSINIZ.",
["bul_fex_26c_02"] = "BUNDAN SONRA NE YAPACAĞINIZI ÇOK İYİ DÜŞÜNMELİSİNİZ. BENİ ÖLDÜRÜRSENİZ PİŞMAN OLURSUNUZ. ",
["bul_fex_26c_03"] = "BENİM KİM OLDUĞUMU BİLİYOR MUSUNUZ? BENİ KİMİN KORUDUĞUNU? SİZE SON BİR ŞANS VERİYORUM... HEMEN BURADAN GİDİN, BELKİ KORUYUCULARIM PEŞİNİZE DÜŞMEDEN KAÇACAK KADAR UZAKLAŞABİLİRSİNİZ.",
["bul_fex_tap01_01"] = "RAÚL HANGİ CEHENNEMDE? ONU BULMAN GEREKİYORDU! BU AKŞAM 50 KONUĞUM GELİYOR, SEN BANA BU BOKU YAPIYORSUN, SENİ LANET FAHİŞE! SENİ SİKTİĞİMİN SAN DİMAS'INA GERİ GÖNDERİRİM!",
["bul_fex_tap01_02"] = "SAN DİMAS'LI AŞAĞILIK OROSPU! MİGUEL NEREDE LAN? YARIM SAAT ÖNCE ONU GETİR DEDİM!",
["bul_fex_tap02_01"] = "ALO?",
["bul_fex_tap02_02"] = "SİKTİĞİMİN KAYINBİRADERİNDEN DAHA İYİ, DEĞİL Mİ? ADI NEYDİ... HOOJİN YA DA ÖYLE BİR BOK? NE İSTİYORSUN LAN?",
["bul_fex_tap02_03"] = "SİKTİR GİT, VOTKADA BOĞUL GEBER. ",
["bul_fex_tap03_01"] = "VLAD? BENİ ARAMANA NE VESİLE OLDU?",
["bul_fex_tap03_02"] = "SENİN YAPTIKLARINDAN DAHA KÖTÜ DEĞİL, KÜÇÜK RUS DOSTUM.",
["bul_fex_tap03_03"] = "BİR ARA KAHVEYE GELMELİSİN. YENİ EVCİL HAYVANLARIMI GÖR!",
["bul_fex_tap04_01"] = "EVET?",
["bul_fex_tap04_02"] = "BU NE?",
["bul_fex_tap04_03"] = "NE? VLAD MI? SENİ PİS RUS! KAYINBİRADERİN NASIL? HANİ... NEYDİ ADI... HOOTİEJUDY... HOUDİNİ?",
["bul_fex_tap06_01"] = "ALO?",
["bul_fex_tap06_01a"] = "ALO? ÇABUK OL, MEŞGULÜM.",
["bul_fex_tap06_02"] = "NE? KİMSİNİZ?",
["bul_fex_tap06_03"] = "VLAD? SEN MİSİN, AŞAĞILIK PİÇ?",
["bul_fex_tap07_01"] = "HERKESTEN ÇOK ÖZÜR DİLERİM AMA DAVETSİZ MİSAFİRLERİMİZ VAR. BU YÜZDEN GÜVENLİĞİNİZ İÇİN PARTİYİ BURADA BİTİRMEM GEREKİYOR. LÜTFEN EVLERİNİZE DÖNÜN. GELDİĞİNİZ İÇİN TEŞEKKÜRLER.",
["bul_fex_tap07_01a"] = "SEVGİLİ KONUKLARIM. EN İÇTEN ÖZÜRLERİMİ SUNARIM AMA PARTİMİZE SON DERECE İSTENMEYEN DAVETSİZ MİSAFİRLER GELMİŞ GİBİ GÖRÜNÜYOR. BU NEDENLE, ELBETTE KENDİ GÜVENLİĞİNİZ İÇİN, ÇIKIŞLARA YÖNELMENİZİ RİCA ETMELİYİM.",
["bul_fex_tap07_01b"] = "LÜTFEN DİKKATİNİZİ VEREBİLİR MİSİNİZ? SORUN ÇIKARAN BAZI KONUKLARIMIZIN GELİŞİ NEDENİYLE GÜVENLİĞİNİZİ GARANTİ EDEMİYORUM. BU YÜZDEN GECEMİZİ ERKEN BİTİRMEK ZORUNDAYIZ. LÜTFEN EVLERİNİZE DÖNÜN. YAKINDA YENİDEN TOPLANACAĞIMIZA SÖZ VERİYORUM. BU GECE GELDİĞİNİZ İÇİN TEŞEKKÜRLER! ",
["bul_fex_tap07_02"] = "SANCHEZ, RAÚL HANGİ CEHENNEMDE? BİRİ BURAYI KURŞUN YAĞMURUNA TUTUYOR.",
["bul_fex_tap07_03"] = "MİGUEL! MİKE'I ALIP BENİ BUL. SİKTİĞİMİN PAYDAY GANG'İ BURADA. ",
["bul_fex_tap07_04"] = "NE YAPMANIZ GEREKTİĞİ UMURUMDA DEĞİL. VURUN SİKİKLERİ.",
["bul_fex_tap07_05"] = "KONUKLAR ARAYA GİRERSE ONLARI DA VURUN.",
["bul_fex_tap07_06"] = "NE SİKİM OLUYOR? BUNLARIN OLMASINI ENGELLEYİN DİYE YETERİNCE PARA VERMİYOR MUYUM?",
["bul_fex_tap07_07"] = "KONUKLARI BURADAN ÇIKARIN. SONRA BİRİNİ BENİMLE BULUŞMAYA GÖNDERİN. EVİ GÜVENCEYE ALMALIYIZ!",
["bul_fex_tap07_08"] = "O SİKİK RUS. BUNUN ARKASINDA O VAR. İŞİNİZİ YAPIN DA ŞU MAHREMİYET İHLALİNİ BİTİRİN!",
["bul_fex_tap08_01"] = "VLAD, SENİ BOK PARÇASI. KÜÇÜK AKRABAN NASIL? TURUNCU ONA ÇOK YAKIŞMIŞ DİYE DUYDUM!",
["bul_fex_tap08_02"] = "VLAD, ESKİ İŞ YOLDAŞIM. NASILSIN? KAYINBİRADERİNLE HÂLÂ SORUN YAŞIYOR MUSUN?",
["bul_fex_tap08_03"] = "VAY, MERHABA ESKİ DOSTUM. UŞAKLARIN BANKAMDA İSTEDİĞİN ŞEYİ BULDU SANIRIM? SENİN İÇİN BAŞKA NE YAPABİLİRİM?",
