["com_hm1_03_01"] = "KÖPEKLER! KÖPEKLER! HEPİNİZ DOMUZ GÖTÜ KÖPEK SİKEN PİÇLERSİNİZ! SİZİ BULACAĞIM. DERİNİZİ CANLI CANLI YÜZECEĞİM.",
