["debug_wskn_yellow"] = "SARI",
["dentist_ca1_cbf_01_01"] = "THE GOLDEN GRIN CASINO, VEGAS'IN EN BÜYÜK KUMARHANESİ. NAKİT VARLIKLARI KÜÇÜK ÜLKELERİNKİYLE YARIŞIR, ÜSTELİK HEPSİNİ YERİNDE TUTARLAR. GANGSTER KURUCULARI BANKALARA HAKLI OLARAK ŞÜPHEYLE BAKARMIŞ. BU İŞ BİR PLAN GEREKTİRECEK. SEÇENEKLERİNİZİ İNCELEYİN, İSTİHBARATINIZI KULLANIN VE PLANINIZI TİTİZLİKLE UYGULAYIN.",
["dentist_ca1_cbf_01_02"] = "THE GOLDEN GRIN CASINO, KURULDUĞUNDAN BERİ STRİP'E HÜKMEDİYOR. MAFYA PARASIYLA YAPILDI. O PARANIN BİRAZINI GERİ ALMA VAKTİ. BİR PLANA İHTİYACINIZ OLACAK: ORTAMI İNCELEYİN. DEĞİŞKENLERİ DEĞERLENDİRİN. SEÇENEKLERİNİZİ DÜŞÜNÜN, SONRA DA TEREDDÜT ETMEDEN UYGULAYIN.",
["dentist_ca1_cbf_01_03"] = "THE GOLDEN GRIN CASINO, SAVAŞ SONRASI SERVETİYLE KURULDU. O SERVETİ YENİDEN PAYLAŞTIRMANIN ZAMANI GELDİ. TİTİZ PLANLAMA ŞART. GÖZLEMLEYİN. DEĞERLENDİRİN. UYGULAYIN. BOL ŞANS DİLERDİM AMA BUNUN ŞANSLA İLGİSİ YOK.",
["dentist_ca1_cnc_01_01"] = "THE GOLDEN GRIN CASINO: BÜYÜK BAHİSLER. SIKI GÜVENLİK. BÜYÜK KAZANÇ.",
["dentist_ca1_cnc_01_02"] = "BİR KUMARHANENİN GÜVENLİK SEVİYESİ GENELLİKLE İÇİNDEKİ SERVETİN BÜYÜKLÜĞÜNÜ YANSITIR. THE GOLDEN GRIN CASINO, STRİP'TEKİ EN GÜVENLİ KUMARHANEDİR.",
["dentist_ca1_cnc_01_03"] = "THE GOLDEN GRIN CASINO: ÇOK ZENGİN. ÇOK GÜVENLİ. ÇOK YAKINDA SİZİN TARAFINIZDAN BOŞALTILACAK.",
["dentist_ca1_debrief_01_01"] = "İYİ DÜŞÜNÜLMÜŞ VE KARARLILIKLA UYGULANMIŞ BİR PLANIN ÖDÜLÜNÜ ALDINIZ. ÇOK ETKİLEYİCİ. SİZE YENİDEN İHTİYACIM OLDUĞUNDA İLETİŞİME GEÇECEĞİM.",
["dentist_ca1_debrief_01_02"] = "PLANINIZI ACIMASIZ BİR VERİMLİLİKLE UYGULADINIZ. ETKİLENDİM. HİZMETLERİNİZE YENİDEN İHTİYACIM OLDUĞUNDA BENDEN HABER ALACAKSINIZ.",
["dentist_ca1_debrief_01_03"] = "İYİ DÜŞÜNÜLMÜŞ BİR PLANIN FAYDASINI GÖRDÜNÜZ. DİSİPLİNİNİZ ETKİLEYİCİ. KAZANCINIZIN TADINI ÇIKARIN. UZMANLIĞINIZA YENİDEN İHTİYACIM OLDUĞUNDA SİZİNLE İLETİŞİME GEÇECEĞİM.",
["dentist_ca1_debrief_02_01"] = "İYİCE DÜŞÜNÜLMÜŞ VE KARARLILIKLA UYGULANMIŞ BİR PLANIN MEYVELERİNİ TOPLADINIZ. ÇOK ETKİLEYİCİ. SİZE YENİDEN İHTİYACIM OLDUĞUNDA ULAŞACAĞIM.",
